INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mauromedda/agent-toolkit/scm', 'scm', 'mauromedda', 'agent-toolkit', 'community', 'scm mauromedda agent-toolkit community The scm skill provides production-quality tools and patterns for AI-powered development workflows, covering Git best practices, branching, and team collaboration. It benefits developers and teams seeking to optimize their workflow. SCM技能提供Git最佳实践和AI工具集成，实现高效开发 SCMスキルはGitベストプラクティスとAIエージェントを統合し、高効率な開発を実現 SCM 스킬은 Git 최고의 실천과 AI 툴을 통합하여 효율적인 개발을 제공 El skill SCM de Claude Code ofrece herramientas y patrones de alta calidad para flujos de trabajo de desarrollo con Git, incluyendo branching, commits y PRs Le skill SCM de Claude Code propose des outils et des modèles de haute qualité pour les flux de travail de développement avec Git, notamment le branching, les commits et les PR Das SCM-Skill von Claude Code bietet hochwertige Tools und Muster für Entwicklungsworkflows mit Git, einschließlich Branching, Commits und PRs O SCM é uma habilidade de controle de versão que cobre branching, commits, PRs e resolução de conflitos para equipes de desenvolvimento SCM - это навык контроля версий, который охватывает ветвление, коммиты, PR и разрешение конфликтов для команд разработки ИИ Агентов SCM هي مهارة لإدارة الإصدارات التي تغطي الفرع، التعهدات، وطلبات السحب وحل النزاعات لفريق التطوير للوكلاء الذكيين scm setup guide Git best practices how to use scm scm vs gitflow scm install what is scm scm alternative conflict resolution techniques AI-powered development workflows SCM技能 Git最佳实践 AI工具集成 源代码管理 版本控制 Git工作流 代码审查 开发效率 AI开发工具 Enforces atomic commits with one logical change per commit Implements conventional commits using `type(scope): description` format Maintains clean history through rebasing before merge Supports branch naming conventions with `type/ticket-description` format Facilitates team collaboration through pull requests (PRs) and conflict resolution scm is a source control management skill that implements Git best practices and workflows for efficient development and team collaboration');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mhylle/claude-skills-collection/adr', 'community', 'mhylle', 'claude-skills-collection', 'mhylle/claude-skills-collection', 'adr', 0, 0, 60, '2026-03-08T01:57:15.272Z', '2026-03-08T02:00:21.676Z', 'eddd29ec26866931c2803ba38bf2603406a0bfa4fba3b9f720a27d1298e471c5', '{"id":"mhylle/claude-skills-collection/adr","name":"adr","description":{"en":"The adr skill enables developers to document significant architectural and technical decisions in a standardized, searchable format. This skill is designed for AI agents, optimizing codebase research and context management workflows.","zh":"adr 技术用于记录代码库的重要架构和技术决策，提供标准化和可搜索的格式以优化 LLM 的上下文效率","ja":"adr 技術は、コードベースの重要なアーキテクチャと技術的決定を記録し、LLM のコンテキスト効率を最適化するための標準化された検索可能な形式を提供します","ko":"adr 기술은 코드베이스의 중요한 아키텍처와 기술적 결정을 기록하고 LLM의 컨텍스트 효율성을 최적화하기 위한 표준화된 검색 가능한 형식을 제공합니다","es":"ADR es un sistema de registros de decisiones arquitectónicas para Claude Code que mejora la eficiencia de tus proyectos","fr":"ADR est un système d''enregistrement des décisions d''architecture pour Claude Code qui améliore l''efficacité de vos projets","de":"ADR ist ein System für Architekturentscheidungsregister für Claude Code, das die Effizienz Ihrer Projekte verbessert","pt":"ADR é uma habilidade para documentar decisões arquitetônicas e técnicas em um formato padronizado e otimizado para eficiência de contexto de LLM","ru":"ADR — это навык для документирования архитектурных и технических решений в стандартизированном формате, оптимизированном для эффективности контекста LLM","ar":"ADR هو مهارة لتسجيل القرارات الهندسية والتقنية في شكل موحد ومحسّن لэффективية سياق LLM"},"seo":{"title":{"en":"adr: Optimized Codebase Research for AI Agents | AI Agent...","zh":"adr 技术指南：代码库研究和上下文管理","ja":"adr セットアップガイド：AIエージェントによるコードベースの研究とコンテキスト管理","ko":"adr 설정 가이드: Claude Code 코드베이스 연구 및 컨텍스트 관리","es":"ADR: Guía de implementación para registros de decisiones ...","fr":"ADR : Guide de mise en œuvre pour les enregistrements de ...","de":"ADR: Implementierungsleitfaden für Architekturentscheidun...","pt":"ADR: Guia de Configuração para Ferramentas de Inteligênci...","ru":"ADR: Руководство по настройке для ИИ Агентов","ar":"ADR: دليل الإعداد لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient codebase research with adr. Discover how to document architectural decisions in a standardized format, optimized for LLM context efficiency....","zh":"adr 技术使 Claude Code 的代码库研究、上下文管理和实现规划变得高效。了解 adr 的工作原理和优势","ja":"adr 技術により、Claude Code のコードベースの研究、コンテキスト管理、実装計画が効率化されます。adr の仕組みとメリットを確認しましょう","ko":"adr 기술을 통해 Claude Code의 코드베이스 연구, 컨텍스트 관리 및 구현 계획이 효율적으로 진행됩니다. adr의 작동 방식과 장점을 알아보세요","es":"Mejora la eficiencia de tus proyectos con ADR, un sistema de registros de decisiones arquitectónicas para Claude Code","fr":"Améliorez l''efficacité de vos projets avec ADR, un système d''enregistrement des décisions d''architecture pour Claude Code","de":"Verbessern Sie die Effizienz Ihrer Projekte mit ADR, einem System für Architekturentscheidungsregister für Claude Code","pt":"Aprenda a configurar ADR para documentar decisões arquitetônicas e técnicas em um formato padronizado e otimizado para eficiência de contexto de LLM","ru":"Узнайте, как настроить ADR для документирования архитектурных и технических решений в стандартизированном формате, оптимизированном для эффективности контекс...","ar":"تعلم كيفية تكوين ADR لتسجيل القرارات الهندسية والتقنية في شكل موحد ومحسّن لэффективية سياق LLM"},"definition":{"en":"adr is a skill for documenting architectural decisions in a standardized format, using small, focused files and a central INDEX.md for efficient LLM consumption.","zh":"adr 是一种用于记录代码库架构和技术决策的技术，提供小型、集中式的文件和快速参考块","ja":"adr は、コードベースのアーキテクチャと技術的決定を記録する技術であり、小規模な集中式ファイルとクイックリファレンスブロックを提供します","ko":"adr는 코드베이스의 아키텍처와 기술적 결정을 기록하는 기술로, 작은集中식 파일과 빠른 참조 블록을 제공합니다","es":"ADR es un sistema de registros de decisiones arquitectónicas que documenta decisiones técnicas en un formato estandarizado","fr":"ADR est un système d''enregistrement des décisions d''architecture qui documente les décisions techniques dans un format standardisé","de":"ADR ist ein System für Architekturentscheidungsregister, das technische Entscheidungen in einem standardisierten Format dokumentiert","pt":"ADR é um registro de decisões arquitetônicas e técnicas em um formato padrão","ru":"ADR — это запись архитектурных и технических решений в стандартизированном формате","ar":"ADR هو سجل للقرارات الهندسية والتقنية في شكل موحد"},"features":{"en":["Generates Architectural Decision Records (ADRs) in a standardized format","Utilizes small, focused files with one decision per ADR and minimal content","Includes a Quick Reference block summarizing the entire ADR in the first 5 lines","Employs a central INDEX.md file for listing all ADRs with one-line summaries","Optimizes ADRs for efficient LLM consumption and context efficiency"],"zh":["小型、集中式的文件","快速参考块","中央 INDEX.md 文件","LLM 上下文效率优化","标准化和可搜索的格式"],"ja":["小規模な集中式ファイル","クイックリファレンスブロック","中央の INDEX.md ファイル","LLM コンテキスト効率最適化","標準化された検索可能な形式"],"ko":["작은集中식 파일","빠른 참조 블록","중앙 INDEX.md 파일","LLM 컨텍스트 효율성 최적화","표준화된 검색 가능한 형식"],"es":["Registros de decisiones arquitectónicas en archivos pequeños y enfocados","Bloque de referencia rápida para resumir decisiones","Índice centralizado de todos los registros de decisiones","Diseñado para la eficiencia de consumo de LLM","Compatibilidad con Claude Code para flujos de trabajo de investigación y planificación"],"fr":["Enregistrements des décisions d''architecture dans des fichiers petits et ciblés","Bloc de référence rapide pour résumer les décisions","Index centralisé de tous les enregistrements des décisions","Conçu pour l''efficacité de consommation de LLM","Compatibilité avec Claude Code pour les flux de travail de recherche et de planification"],"de":["Architekturentscheidungsregister in kleinen und fokussierten Dateien","Schnellreferenzblock für die Zusammenfassung von Entscheidungen","Zentraler Index aller Architekturentscheidungsregister","Entworfen für die Effizienz von LLM-Verbrauch","Kompatibilität mit Claude Code für Forschungs- und Planungsworkflows"],"pt":["Arquivos pequenos e focados, um por decisão","Bloco de referência rápida com resumo de 5 linhas","Índice centralizado em INDEX.md","Otimizado para eficiência de contexto de LLM","Padronização de decisões arquitetônicas e técnicas"],"ru":["Маленькие и сосредоточенные файлы, один на решение","Блок быстрого справочника с кратким изложением в 5 строк","Централизованный индекс в INDEX.md","Оптимизировано для эффективности контекста LLM","Стандартизация архитектурных и технических решений"],"ar":["ملفات صغيرة ومُركّزة، واحدة لكل قرار","كتلة مرجعية سريعة مع ملخص 5 أسطر","فهرس مركزي في INDEX.md","محسّن لэффективية سياق LLM","توحيد القرارات الهندسية والتقنية"]},"keywords":{"en":["how to use adr","what is adr","adr alternative","adr vs architectural decision making","adr install","adr setup guide","adr for AI agents","adr and LLM context efficiency","adr for codebase research"],"zh":["adr 技术","代码库研究","上下文管理","LLM 效率优化","架构决策记录","技术决策记录","代码库管理","adr 设置指南"],"ja":["adr 技術","コードベースの研究","コンテキスト管理","LLM 効率最適化","アーキテクチャ決定の記録","技術的決定の記録","コードベースの管理","adr セットアップガイド","AIエージェント"],"ko":["adr 기술","코드베이스 연구","컨텍스트 관리","LLM 효율성 최적화","아키텍처 결정을 기록","기술적 결정을 기록","코드베이스 관리","adr 설정 가이드","AI 에이전트"],"es":["ADR","registros de decisiones arquitectónicas","Claude Code","eficiencia de proyectos","LLM","herramientas de desarrollo","registros de decisiones técnicas","planificación de implementación","investigación de código"],"fr":["ADR","enregistrements des décisions d''architecture","Claude Code","efficacité de projets","LLM","outils de développement","enregistrements des décisions techniques","planification de mise en œuvre","recherche de code"],"de":["ADR","Architekturentscheidungsregister","Claude Code","Projekteffizienz","LLM","Entwicklungstools","Architekturentscheidungsregister","Implementierungsplanung","Code-Forschung"],"pt":["ADR","Ferramentas de Inteligência Artificial","Documentação de decisões arquitetônicas","LLM","Eficiência de contexto","Padronização de decisões técnicas","Guia de configuração ADR","Otimização de contexto para LLM"],"ru":["ADR","ИИ Агенты","Документирование архитектурных решений","LLM","Эффективность контекста","Стандартизация технических решений","Руководство по настройке ADR","Оптимизация контекста для LLM"],"ar":["ADR","أدوات الذكاء الاصطناعي","تسجيل القرارات الهندسية","LLM","эффективية سياق","توحيد القرارات التقنية","دليل الإعداد ADR","تحسين سياق ل LLM"]}},"owner":"mhylle","repo":"claude-skills-collection","repoPath":"mhylle/claude-skills-collection","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.272Z","topics":[],"category":"community","skillMd":{"name":"adr","description":"Document architectural decisions in standardized ADR format. This skill should be used when making significant technical decisions, choosing between approaches, establishing patterns, or when other skills (create-plan, implement-plan, brainstorm) identify decisions that need documentation. Triggers on document decision, create ADR, architectural decision, or automatically when invoked by other skills during planning and implementation.","bodyPreview":"# Architectural Decision Records (ADR)\n\nDocument significant architectural and technical decisions in a standardized, searchable format optimized for LLM context efficiency.\n\n## Design Principles\n\n### Context Conservation\n\nADRs are designed for efficient LLM consumption:\n\n1. **Small, focused files** - One decision per ADR, minimal content\n2. **Quick Reference block** - First 5 lines summarize the entire ADR\n3. **Central INDEX.md** - Single file listing all ADRs with one-line summaries\n\n### LLM R","body":"# Architectural Decision Records (ADR)\n\nDocument significant architectural and technical decisions in a standardized, searchable format optimized for LLM context efficiency.\n\n## Design Principles\n\n### Context Conservation\n\nADRs are designed for efficient LLM consumption:\n\n1. **Small, focused files** - One decision per ADR, minimal content\n2. **Quick Reference block** - First 5 lines summarize the entire ADR\n3. **Central INDEX.md** - Single file listing all ADRs with one-line summaries\n\n### LLM Reading Strategy\n\nWhen consulting ADRs, follow this tiered approach:\n\n```\nTIER 1: Read INDEX.md (one file, all summaries)\n        ↓ Identify potentially relevant ADRs\nTIER 2: Read Quick Reference block only (first 10 lines of candidate ADRs)\n        ↓ Confirm relevance\nTIER 3: Read full ADR content (only when details are needed)\n```\n\n**Implementation**:\n```\n# Tier 1: Scan index\nRead(\"docs/decisions/INDEX.md\")\n\n# Tier 2: Quick reference only (use limit parameter)\nRead(\"docs/decisions/ADR-0001-title.md\", limit=10)\n\n# Tier 3: Full content (only if needed)\nRead(\"docs/decisions/ADR-0001-title.md\")\n```\n\n## When to Use This Skill\n\n**Directly invoked when:**\n- Making a significant technical decision\n- Choosing between architectural approaches\n- Establishing patterns or conventions\n- Documenting why a particular technology was selected\n\n**Automatically invoked by other skills when:**\n- **create-plan**: Design decision is made in Phase 4\n- **implement-plan**: Mismatch discovered or architectural choice made during implementation\n- **brainstorm**: Key decisions identified during analysis\n\n## ADR Location and Naming\n\n**Directory**: `docs/decisions/`\n\n**Naming Convention**: `ADR-NNNN-short-title.md`\n- `NNNN`: Zero-padded sequential number (0001, 0002, etc.)\n- `short-title`: Lowercase, hyphenated description (max 50 chars)\n\n**Examples**:\n- `ADR-0001-use-jwt-for-authentication.md`\n- `ADR-0002-postgresql-over-mongodb.md`\n- `ADR-0003-event-sourcing-for-audit.md`\n\n## Getting the Next ADR Number\n\nBefore creating an ADR, determine the next sequence number:\n\n```bash\n# Find highest existing ADR number\nls docs/decisions/ADR-*.md 2>/dev/null | sort -t- -k2 -n | tail -1 | grep -oP ''ADR-\\K\\d+'' || echo \"0000\"\n```\n\nIf no ADRs exist, start with `0001`.\n\n## ADR Status Values\n\n| Status | Meaning |\n|--------|---------|\n| **Proposed** | Under consideration, not yet decided |\n| **Accepted** | Decision made, ready for implementation |\n| **Deprecated** | Was accepted, now superseded |\n| **Superseded** | Replaced by another ADR (link to replacement) |\n\n## Creating an ADR\n\n### Required Information\n\nGather these inputs (ask user if not provided):\n\n| Field | Description | Required |\n|-------|-------------|----------|\n| Title | Short, descriptive title | Yes |\n| Context | Why is this decision needed? | Yes |\n| Options | What alternatives were considered? | Yes |\n| Decision | What was decided? | Yes |\n| Rationale | Why this option? | Yes |\n| Consequences | What are the implications? | Yes |\n| Related ADRs | Links to related decisions | If applicable |\n\n### ADR Template\n\nUse this format (also in `references/adr-template.md`):\n\n```markdown\n# ADR-NNNN: [Title]\n\n> **Quick Reference** | Status: [Accepted] | Date: [YYYY-MM-DD]\n> **Decision**: [One sentence: what was decided]\n> **Context**: [One sentence: why this decision was needed]\n> **Alternatives**: [Rejected options, comma-separated]\n> **Impact**: [Key areas affected, comma-separated]\n\n---\n\n## Context\n\n[2-3 sentences max. The problem or opportunity being addressed.]\n\n## Decision\n\n**We will use [chosen option].**\n\n[1-2 sentences explaining the decision.]\n\n## Alternatives Considered\n\n| Option | Pros | Cons | Why Not |\n|--------|------|------|---------|\n| [Option A] | [Key pro] | [Key con] | [Brief reason] |\n| [Option B] | [Key pro] | [Key con] | [Brief reason] |\n\n## Consequences\n\n- **Positive**: [Key benefit]\n- **Negative**: [Key trade-off]\n- **Requires**: [What must be done as a result]\n\n## Related\n\n- [ADR-XXXX](./ADR-XXXX-title.md): [Relationship]\n```\n\n### Quick Reference Block (Mandatory)\n\nThe first 5 lines after the title form the **Quick Reference** block. This enables LLMs to assess relevance without reading the full document.\n\n**Format** (must fit in ~5 lines):\n```markdown\n> **Quick Reference** | Status: [Status] | Date: [Date]\n> **Decision**: [One sentence summary of what was decided]\n> **Context**: [One sentence on why this decision was needed]\n> **Alternatives**: [Comma-separated list of rejected options]\n> **Impact**: [Comma-separated list of affected areas/components]\n```\n\n**Example**:\n```markdown\n> **Quick Reference** | Status: Accepted | Date: 2024-01-15\n> **Decision**: Use JWT tokens for API authentication instead of sessions.\n> **Context**: Need stateless auth for horizontal scaling of API servers.\n> **Alternatives**: Session cookies, OAuth tokens, API keys\n> **Impact**: Auth service, API gateway, client SDKs\n```\n\n### Keeping ADRs Small\n\n**Target size**: 30-50 lines maximum (excluding Quick Reference)\n\n**One decision per ADR**. If you find yourself documenting multiple decisions, split into separate ADRs:\n\n| Instead of | Create |\n|------------|--------|\n| \"Database and caching choices\" | ADR-0001: PostgreSQL for primary database |\n| | ADR-0002: Redis for session caching |\n| \"Authentication architecture\" | ADR-0003: JWT for API auth |\n| | ADR-0004: OAuth2 for third-party integration |\n\n**Use tables over prose** - More scannable, less verbose:\n\n```markdown\n## Alternatives Considered\n\n| Option | Pros | Cons | Why Not |\n|--------|------|------|---------|\n| MongoDB | Flexible schema | No ACID | Need transactions |\n| MySQL | Mature, fast | Less JSON support | PostgreSQL better fit |\n```\n\n## Workflow\n\n### Step 1: Detect ADR Trigger\n\nAn ADR should be created when:\n\n1. **Explicit request**: User asks to document a decision\n2. **Design choice**: During planning, a significant choice between approaches is made\n3. **Pattern establishment**: A new convention or pattern is being introduced\n4. **Technology selection**: A library, framework, or service is chosen\n5. **Architecture change**: Structural changes to the system\n6. **Deviation from plan**: Implementation differs from original plan for good reason\n\n### Step 2: Gather Information\n\nIf invoked automatically by another skill, extract:\n- Context from the current discussion\n- Options that were considered\n- The decision that was made\n- Rationale from the analysis\n\nIf information is incomplete, ask the user:\n\n```\nTo document this architectural decision, I need:\n1. What problem or context led to this decision?\n2. What options were considered?\n3. Why was this option chosen over others?\n4. What are the expected consequences?\n```\n\n### Step 3: Create ADR File\n\n1. Determine next ADR number\n2. Generate filename from title\n3. Write ADR using template\n4. Report creation to calling context\n\n### Step 4: Update INDEX.md (Required)\n\n**Always update `docs/decisions/INDEX.md`** when creating, modifying, or deprecating an ADR.\n\n#### INDEX.md Structure\n\n```markdown\n# Architectural Decision Records\n\nQuick reference index for all architectural decisions. Read this file first to identify relevant ADRs.\n\n## Active Decisions\n\n| ADR | Decision | Impact | Date |\n|-----|----------|--------|------|\n| [0001](./ADR-0001-use-jwt-auth.md) | Use JWT for API authentication | Auth, API | 2024-01-15 |\n| [0002](./ADR-0002-postgresql-database.md) | PostgreSQL as primary database | Data layer | 2024-01-16 |\n| [0003](./ADR-0003-redis-caching.md) | Redis for session and query caching | Performance | 2024-01-17 |\n\n## Superseded Decisions\n\n| ADR | Was | Replaced By | Date |\n|-----|-----|-------------|------|\n| [0000](./ADR-0000-example.md) | Session-based auth | ADR-0001 | 2024-01-10 |\n\n## By Category\n\n### Authentication & Security\n- [ADR-0001](./ADR-0001-use-jwt-auth.md): JWT for API authentication\n\n### Data & Storage\n- [ADR-0002](./ADR-0002-postgresql-database.md): PostgreSQL as primary database\n- [ADR-0003](./ADR-0003-redis-caching.md): Redis for caching\n\n### API Design\n(none yet)\n\n### Infrastructure\n(none yet)\n```\n\n#### Updating INDEX.md\n\nWhen adding a new ADR:\n1. Add row to \"Active Decisions\" table\n2. Add entry under appropriate category (create category if needed)\n\nWhen deprecating an ADR:\n1. Move row from \"Active Decisions\" to \"Superseded Decisions\"\n2. Add \"Replaced By\" reference\n3. Update category listing\n\n#### Creating INDEX.md\n\nIf `docs/decisions/INDEX.md` doesn''t exist, create it:\n\n```bash\nmkdir -p docs/decisions\n```\n\nThen write the initial structure with the first ADR entry.\n\n## Integration with Other Skills\n\n### From create-plan\n\nWhen create-plan makes a design decision in Phase 4, it should invoke this skill:\n\n```\nTRIGGER: Design option selected in create-plan Phase 4\nACTION: Create ADR documenting the decision\nLINK: Reference ADR in plan''s \"Design Decision\" section\n```\n\nThe plan should include:\n```markdown\n## Design Decision\n\n[Brief description]\n\nSee [ADR-NNNN](../decisions/ADR-NNNN-title.md) for full rationale.\n```\n\n### From implement-plan\n\nWhen implement-plan encounters an architectural choice:\n\n```\nTRIGGER:\n- Mismatch between plan and reality requiring decision\n- New pattern being established\n- Technology choice during implementation\n\nACTION: Create ADR documenting the decision\nLINK: Note in plan file and inline status\n```\n\n### From brainstorm\n\nWhen brainstorm identifies key decisions:\n\n```\nTRIGGER: Analysis identifies significant decisions that should be documented\nACTION: Create ADRs for each major decision (can be \"Proposed\" status)\nLINK: Reference in brainstorm output''s \"Key Decisions\" section\n```\n\n## Response Format (for subagent use)\n\nWhen this skill is invoked by another skill (as a subagent), return concise output:\n\n```\nSTATUS: CREATED\nADR: docs/decisions/ADR-NNNN-title.md\nINDEX: docs/decisions/INDEX.md (updated)\nDECISION: [One-line summary of decision]\nIMPACT: [Comma-separated affected areas]\n```\n\n**Always confirm INDEX.md was updated** - this is critical for LLM discoverability.\n\n## Listing Existing ADRs\n\nTo review existing decisions:\n\n```bash\n# List all ADRs with status\ngrep -l \"Status.*Accepted\" docs/decisions/ADR-*.md | while read f; do\n  title=$(head -1 \"$f\" | sed ''s/# //'')\n  echo \"$f: $title\"\ndone\n```\n\n## Searching ADRs\n\nFind ADRs related to a topic:\n\n```bash\n# Search ADR content\ngrep -l \"authentication\" docs/decisions/ADR-*.md\n```\n\n## Deprecating an ADR\n\nWhen a decision is superseded:\n\n1. Update old ADR status: `**Status**: Superseded by [ADR-NNNN](./ADR-NNNN-title.md)`\n2. Create new ADR referencing the old one in \"Related Decisions\"\n3. Update any plans or docs referencing the old ADR\n\n## Quality Checklist\n\nBefore finalizing an ADR:\n\n**Structure (Context Conservation)**:\n- [ ] Quick Reference block is complete (all 5 lines)\n- [ ] Quick Reference fits in first 10 lines of file\n- [ ] Total ADR is under 50 lines\n- [ ] One decision per ADR (no bundled decisions)\n- [ ] Uses tables instead of verbose prose\n\n**Content**:\n- [ ] Decision is clearly stated in one sentence\n- [ ] Context is 2-3 sentences max\n- [ ] At least 2 alternatives listed with pros/cons\n- [ ] Consequences include positive AND negative\n\n**Index**:\n- [ ] INDEX.md updated with new entry\n- [ ] Category section updated\n- [ ] Impact areas listed accurately\n\n## Best Practices\n\n### Writing Concise ADRs\n\n1. **One sentence, one decision**: If you can''t state the decision in one sentence, you may be bundling multiple decisions\n2. **Tables over paragraphs**: Alternatives table is more scannable than prose\n3. **Impact over rationale**: Focus on what''s affected, not lengthy justification\n4. **Quick Reference is the ADR**: If someone only reads the Quick Reference, they should understand the decision\n\n### Size Guidelines\n\n| Section | Target Length |\n|---------|---------------|\n| Quick Reference | 5 lines (mandatory) |\n| Context | 2-3 sentences |\n| Decision | 1-2 sentences |\n| Alternatives table | 2-4 rows |\n| Consequences | 3 bullets |\n| Total ADR | 30-50 lines |\n\n### When to Split ADRs\n\nSplit into multiple ADRs when:\n- Decision covers multiple technologies\n- Decision affects unrelated areas\n- You''re writing \"and\" in the decision statement\n- Different stakeholders care about different parts\n\n### When NOT to Create an ADR\n\n- Minor implementation details\n- Obvious choices with no real alternatives\n- Temporary decisions that will be revisited\n- Style preferences (unless establishing standards)\n\n### ADR Maintenance\n\n- Review ADRs quarterly for relevance\n- Deprecate outdated decisions promptly\n- Keep INDEX.md as the single source of truth\n- Categories in INDEX.md should match project structure\n\n## Resources\n\n### references/\n- `adr-template.md`: Standalone ADR template (30-50 lines target)\n- `index-template.md`: INDEX.md template for new projects\n"},"lastSynced":"2026-03-08T02:00:21.676Z","agentAnalysis":{"suitability":{"en":"Ideal for Technical Writing Agents requiring structured documentation of architectural decisions","zh":"非常适合需要结构化架构决策文档的技术写作AI Agent。","ja":"構造化されたアーキテクチャ決定事項の文書化を必要とするテクニカルライティングAgentに理想的です。","ko":"구조화된 아키텍처 결정 사항 문서화가 필요한 기술 문서 작성 AI Agent에 이상적입니다.","es":"Ideal para Agentes de Escritura Técnica que requieren documentación estructurada de decisiones arquitectónicas","fr":"Idéal pour les Agents d''Écriture Technique nécessitant une documentation structurée des décisions architecturales","de":"Ideal für technische Schreibagenten, die eine strukturierte Dokumentation von Architektenentscheidungen erfordern","pt":"Ideal para Agentes de Redação Técnica que exigem documentação estruturada de decisões arquiteturais","ru":"Идеально для агентов технической документации, требующих структурированной документации архитектурных решений","ar":"مثالي لوكلاء الكتابة الفنية الذين يتطلبون توثيقًا متكاملًا لقرارات التصميم المعماري"},"recommendation":{"en":"Empowers agents to efficiently manage and search architectural decision records using standardized, minimal content files and a central INDEX.md, optimized for LLM context efficiency with Quick Reference blocks","zh":"使Agent能够使用标准化的、最小内容文件和中央INDEX.md高效管理和搜索架构决策记录，并通过Quick Reference块优化LLM上下文效率。","ja":"標準化された最小限のコンテンツファイルと中央INDEX.mdを使用して、アーキテクチャ決定記録を効率的に管理および検索するAgentを強化し、Quick ReferenceブロックによるLLMコンテキスト効率を最適化します。","ko":"표준화된 최소 내용 파일과 중앙 INDEX.md를 사용하여 아키텍처 결정 기록을 효율적으로 관리 및 검색하도록 Agent를 강화하며, Quick Reference 블록으로 LLM 컨텍스트 효율성을 최적화합니다.","es":"Habilita a los agentes a gestionar y buscar registros de decisiones arquitectónicas de manera eficiente utilizando archivos de contenido minimalistas y estandarizados y un INDEX.md central, optimizado para la eficiencia del contexto de LLM con bloques de Referencia Rápida","fr":"Permet aux agents de gérer et de rechercher des enregistrements de décisions architecturales de manière efficace en utilisant des fichiers de contenu minimalistes et standardisés et un INDEX.md central, optimisé pour l''efficacité du contexte de LLM avec des blocs de Référence Rapide","de":"Ermächtigt die Agenten, Architektenentscheidungsprotokolle effizient zu verwalten und zu suchen, indem standardisierte, minimale Inhaltsdateien und ein zentrales INDEX.md verwendet werden, optimiert für die Kontexteffizienz von LLM mit Schnellreferenzblöcken","pt":"Permite que os agentes gerenciem e pesquisem registros de decisões arquiteturais de forma eficiente usando arquivos de conteúdo minimalistas e padronizados e um INDEX.md central, otimizado para eficiência de contexto de LLM com blocos de Referência Rápida","ru":"Позволяет агентам эффективно управлять и искать записи архитектурных решений, используя стандартизированные, минимальные файлы содержания и центральный INDEX.md, оптимизированный для эффективности контекста LLM с блоками быстрого обращения","ar":"تمكن الوكلاء من إدارةและสؤال سجلات قرارات التصميم المعماري بفعالية باستخدام ملفات محتوى معيارية ومحددة وملف INDEX.md مركزي، متوافق مع كفاءة السياق LLM مع كتلة المراجع السريعة"},"useCases":{"en":["Documenting technical debt","Standardizing architectural decisions","Improving codebase research with searchable ADRs"],"zh":["技术债务文档化","架构决策标准化","通过可搜索的ADR改进代码库研究"],"ja":["テクニカルデブトの文書化","アーキテクチャ決定事項の標準化","検索可能なADRによるコードベース調査の改善"],"ko":["기술 부채 문서화","아키텍처 결정 사항 표준화","검색 가능한 ADR로 코드베이스 연구 개선"],"es":["Documentar deuda técnica","Establecer estándares para decisiones arquitectónicas","Mejorar la investigación de código con ADRs buscables"],"fr":["Documenter la dette technique","Standardiser les décisions architecturales","Améliorer la recherche de code avec des ADRs recherchables"],"de":["Technische Schulden dokumentieren","Architektenentscheidungen standardisieren","Codebasis-Recherche mit suchbaren ADRs verbessern"],"pt":["Documentação de dívida técnica","Padronização de decisões arquiteturais","Melhoria da pesquisa da base de código com ADRs pesquisáveis"],"ru":["Документирование технического долга","Стандартизация архитектурных решений","Улучшение исследования кодовой базы с помощью поиска ADR"],"ar":["توثيق الديون الفنية","تقييس قرارات التصميم المعماري","تحسين بحث قاعدة الشفرة مع سجلات ADR قابلة للبحث"]},"limitations":{"en":["Requires adherence to ADR file format standards","Limited to text-based documentation"],"zh":["需要遵循ADR文件格式标准","仅限于基于文本的文档"],"ja":["ADRファイル形式標準の遵守が必要","テキストベースの文書に限定される"],"ko":["ADR 파일 형식 표준 준수 필요","텍스트 기반 문서로 제한됨"],"es":["Requiere adherencia a los estándares de formato de archivo ADR","Limitado a la documentación basada en texto"],"fr":["Exige l''adhesion aux normes de format de fichier ADR","Limité à la documentation basée sur le texte"],"de":["Erfordert die Einhaltung der ADR-Dateiformatstandards","Begrenzt auf textbasierte Dokumentation"],"pt":["Exige aderência aos padrões de formato de arquivo ADR","Limitado à documentação baseada em texto"],"ru":["Требует соблюдения стандартов формата файла ADR","Ограничен документацией на основе текста"],"ar":["يتطلب الالتزام بمعايير تنسيق ملف ADR","محدود بالتوثيق القائم على النص"]},"version":4},"contentHash":"eddd29ec26866931c2803ba38bf2603406a0bfa4fba3b9f720a27d1298e471c5","qualityScore":60}');
