INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mhylle/claude-skills-collection/adr', 'adr', 'mhylle', 'claude-skills-collection', 'community', 'adr mhylle claude-skills-collection community The adr skill enables developers to document significant architectural and technical decisions in a standardized, searchable format. This skill is designed for AI agents, optimizing codebase research and context management workflows. adr 技术用于记录代码库的重要架构和技术决策，提供标准化和可搜索的格式以优化 LLM 的上下文效率 adr 技術は、コードベースの重要なアーキテクチャと技術的決定を記録し、LLM のコンテキスト効率を最適化するための標準化された検索可能な形式を提供します adr 기술은 코드베이스의 중요한 아키텍처와 기술적 결정을 기록하고 LLM의 컨텍스트 효율성을 최적화하기 위한 표준화된 검색 가능한 형식을 제공합니다 ADR es un sistema de registros de decisiones arquitectónicas para Claude Code que mejora la eficiencia de tus proyectos ADR est un système d''enregistrement des décisions d''architecture pour Claude Code qui améliore l''efficacité de vos projets ADR ist ein System für Architekturentscheidungsregister für Claude Code, das die Effizienz Ihrer Projekte verbessert ADR é uma habilidade para documentar decisões arquitetônicas e técnicas em um formato padronizado e otimizado para eficiência de contexto de LLM ADR — это навык для документирования архитектурных и технических решений в стандартизированном формате, оптимизированном для эффективности контекста LLM ADR هو مهارة لتسجيل القرارات الهندسية والتقنية في شكل موحد ومحسّن لэффективية سياق LLM how to use adr what is adr adr alternative adr vs architectural decision making adr install adr setup guide adr for AI agents adr and LLM context efficiency adr for codebase research adr 技术 代码库研究 上下文管理 LLM 效率优化 架构决策记录 技术决策记录 代码库管理 adr 设置指南 Generates Architectural Decision Records (ADRs) in a standardized format Utilizes small, focused files with one decision per ADR and minimal content Includes a Quick Reference block summarizing the entire ADR in the first 5 lines Employs a central INDEX.md file for listing all ADRs with one-line summaries Optimizes ADRs for efficient LLM consumption and context efficiency adr is a skill for documenting architectural decisions in a standardized format, using small, focused files and a central INDEX.md for efficient LLM consumption.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('darkroomengineering/cc-settings/qa', 'community', 'darkroomengineering', 'cc-settings', 'darkroomengineering/cc-settings', 'qa', 0, 0, 60, '2026-03-08T01:57:15.272Z', '2026-03-08T02:00:23.214Z', 'ee70681c3009cbeba8ab504a122506bca38bd63462a086c559a1f0e2b71c2ebf', '{"id":"darkroomengineering/cc-settings/qa","name":"qa","description":{"en":"The qa skill enables developers to perform visual and accessibility validation using pinchtab, combining automated tooling with structured design review methodology. This benefits developers and designers who need to ensure their applications meet visual and accessibility standards.","zh":"视觉QA验证结合自动化工具和结构化设计审查方法，确保设计的一致性和质量","ja":"ピンチタブを使用した視覚的およびアクセシビリティの検証により、デザインの的一貫性と品質を確保します","ko":"핀치탭을_사용한_시각적_및_접근성_검증을_통해_디자인의_일관성_및_품질을_보장합니다","es":"La validación visual de QA combina herramientas automatizadas con una metodología de revisión de diseño estructurada para garantizar la calidad visual de los productos","fr":"La validation visuelle de QA combine des outils automatisés avec une méthodologie de revue de conception structurée pour assurer la qualité visuelle des produits","de":"Die visuelle QA-Validierung kombiniert automatisierte Tools mit einer strukturierten Design-Review-Methodik, um die visuelle Qualität von Produkten sicherzustellen","pt":"A validação visual QA combina ferramentas automatizadas com metodologia de revisão de design estruturada","ru":"Визуальная проверка QA сочетает автоматизированные инструменты с методологией структурированного обзора дизайна","ar":"التحقق المرئي للجودة يجمع بين أدوات التلقائية و منهجية مراجعة التصميم الهيكلية"},"seo":{"title":{"en":"qa: Visual Validation Setup Guide | AI Agent Skill","zh":"QA_SETUP_GUIDE","ja":"AIエージェントのQAベストプラクティス","ko":"QA_구성_가이드","es":"Guía de configuración de QA para validación visual","fr":"Guide de mise en place de QA pour validation visuelle","de":"Einrichtungsleitfaden für QA-Visual-Validation","pt":"Guia de Configuração de QA: Validação Visual com Pinchtab","ru":"Настройка ИИ Агентов: Руководство по визуальной проверке ...","ar":"دليل إعداد جهاز QA: التحقق المرئي باستخدام Pinchtab"},"description":{"en":"Unlock efficient visual QA validation with pinchtab. Learn how to combine automated tooling with design review methodology and improve your workflow today!","zh":"自动化工具与结构化设计审查方法相结合的视觉QA验证","ja":"ピンチタブを使用した視覚的およびアクセシビリティの検証","ko":"핀치탭을_사용한_시각적_및_접근성_검증","es":"Aprende a implementar una metodología de revisión de diseño estructurada con herramientas automatizadas para la validación visual de QA","fr":"Découvrez comment mettre en place une méthodologie de revue de conception structurée avec des outils automatisés pour la validation visuelle de QA","de":"Erfahren Sie, wie Sie eine strukturierte Design-Review-Methodik mit automatisierten Tools für die visuelle QA-Validierung implementieren","pt":"Aprenda a configurar a validação visual QA com pinchtab e melhore a acessibilidade do seu projeto","ru":"Узнайте, как настроить визуальную проверку QA с помощью Pinchtab и улучшить доступность вашего проекта","ar":"تعلم كيفية إعداد التحقق المرئي للجودة باستخدام Pinchtab وتحسين إمكانية الوصول لمشروعك"},"definition":{"en":"qa is a visual validation methodology that combines automated tooling with structured design review, prioritizing impact and specificity in critique.","zh":"什么是QA？QA是指使用自动化工具和结构化设计审查方法进行视觉和访问性验证","ja":"QAとは？QAは、ピンチタブを使用した視覚的およびアクセシビリティの検証を指します","ko":"QA란？QA는_핀치탭을_사용한_시각적_및_접근성_검증을_의미합니다","es":"La validación visual de QA es una técnica que utiliza herramientas automatizadas y revisión de diseño para garantizar la calidad visual de los productos","fr":"La validation visuelle de QA est une technique qui utilise des outils automatisés et une revue de conception pour assurer la qualité visuelle des produits","de":"Die visuelle QA-Validierung ist eine Technik, die automatisierte Tools und Design-Review verwendet, um die visuelle Qualität von Produkten sicherzustellen","pt":"Validação visual QA é uma abordagem que combina ferramentas automatizadas com revisão de design para garantir a acessibilidade","ru":"Визуальная проверка QA - это подход, который сочетает автоматизированные инструменты с обзором дизайна для обеспечения доступности","ar":"التحقق المرئي للجودة هو نهج يجمع بين أدوات التلقائية ومراجعة التصميم لضمان إمكانية الوصول"},"features":{"en":["Combines automated tooling with structured design review methodology","Utilizes pinchtab for visual and accessibility validation","Employs a screenshot-first approach for accurate critique","Prioritizes impact in validation, focusing on critical issues","Supports specific and detailed critique, including spacing and rhythm analysis"],"zh":["使用pinchtab进行视觉和访问性验证","结合自动化工具和结构化设计审查方法","优先考虑影响和具体的设计细节","提供Screenshot-first的设计审查方法","支持结构化的设计审查和反馈"],"ja":["ピンチタブを使用した視覚的およびアクセシビリティの検証","自動化ツールと構造化デザインレビューメソッドの組み合わせ","影響と具体的なデザイン詳細を優先する","スクリーンショットファーストのデザインレビューメソッドを提供","構造化デザインレビューとフィードバックをサポート"],"ko":["핀치탭을_사용한_시각적_및_접근성_검증","자동화_도구와_구조화된_디자인_리뷰_방법의_조합","영향과_구체적인_디자인_세부를_우선시","스크린샷_최우선의_디자인_리뷰_방법을_제공","구조화된_디자인_리뷰와_피드백을_지원"],"es":["Validación visual utilizando pinchtab","Metodología de revisión de diseño estructurada","Herramientas automatizadas para la detección de errores","Análisis de espaciado y ritmo de diseño","Revisión de la accesibilidad de los productos"],"fr":["Validation visuelle utilisant pinchtab","Méthodologie de revue de conception structurée","Outils automatisés pour la détection d''erreurs","Analyse de l''espacement et du rythme de conception","Revue de l''accessibilité des produits"],"de":["Visuelle Validierung mit pinchtab","Strukturierte Design-Review-Methodik","Automatisierte Tools für die Fehlererkennung","Analyse des Abstands und des Design-Rhythmus","Überprüfung der Zugänglichkeit von Produkten"],"pt":["Validação visual com pinchtab","Metodologia de revisão de design estruturada","Análise de acessibilidade automatizada","Foco em impacto e priorização de problemas","Análise de espaçamento e ritmo de design"],"ru":["Визуальная проверка с помощью pinchtab","Методология структурированного обзора дизайна","Автоматизированный анализ доступности","Фокус на влиянии и приоритизация проблем","Анализ间距 и ритма дизайна"],"ar":["التحقق المرئي باستخدام Pinchtab","منهجية مراجعة التصميم الهيكلية","تحليل إمكانية الوصول التلقائي","التركيز على التأثير وتحديد أولويات المشاكل","تحليل المسافة وايقاع التصميم"]},"keywords":{"en":["how to use qa for visual validation","qa alternative to manual testing","qa vs manual validation","qa install guide for developers","qa setup for automated testing","what is qa in software development"],"zh":["QA","视觉验证","访问性验证","自动化工具","结构化设计审查","pinchtab","设计审查","Screenshot-first"],"ja":["QA","AIエージェント","視覚的検証","アクセシビリティ検証","自動化ツール","構造化デザインレビュー","ピンチタブ","デザインレビュー","スクリーンショットファースト"],"ko":["QA","AI_에이전트","시각적_검증","접근성_검증","자동화_도구","구조화된_디자인_리뷰","핀치탭","디자인_리뷰","스크린샷_최우선"],"es":["QA visual","validación visual","herramientas de QA","metodología de revisión de diseño","pinchtab","accesibilidad","diseño de productos","calidad visual","automatización de pruebas"],"fr":["QA visuelle","validation visuelle","outils de QA","méthodologie de revue de conception","pinchtab","accessibilité","conception de produits","qualité visuelle","automatisation des tests"],"de":["Visuelle QA","visuelle Validierung","QA-Tools","Design-Review-Methodik","pinchtab","Zugänglichkeit","Produktdesign","visuelle Qualität","Testautomatisierung"],"pt":["validação visual QA","pinchtab","acessibilidade","revisão de design","análise de acessibilidade","desenvolvimento web","ferramentas de QA","melhoria de acessibilidade"],"ru":["визуальная проверка QA","ИИ Агенты","pinchtab","доступность","обзор дизайна","анализ доступности","веб-разработка","инструменты QA","улучшение доступности"],"ar":["التحقق المرئي للجودة","أدوات الذكاء الاصطناعي","Pinchtab","إمكانية الوصول","مراجعة التصميم","تحليل إمكانية الوصول","تطوير الويب","أدوات الجودة","تحسين إمكانية الوصول"]}},"owner":"darkroomengineering","repo":"cc-settings","repoPath":"darkroomengineering/cc-settings","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.272Z","topics":[],"category":"community","skillMd":{"name":"qa","description":"|","bodyPreview":"# Visual QA Validation\n\nVisual and accessibility validation using pinchtab. Combines automated tooling with structured design review methodology.\n\n## Core Philosophy\n\n- **Screenshot first, then critique.** Always look at the actual rendered output, not just the code.\n- **Be specific.** \"The spacing looks off\" is useless. \"The gap between the heading and paragraph is 32px but should be 16px based on the surrounding spacing rhythm\" is useful.\n- **Prioritize impact.** Not every pixel matters. Focus","body":"# Visual QA Validation\n\nVisual and accessibility validation using pinchtab. Combines automated tooling with structured design review methodology.\n\n## Core Philosophy\n\n- **Screenshot first, then critique.** Always look at the actual rendered output, not just the code.\n- **Be specific.** \"The spacing looks off\" is useless. \"The gap between the heading and paragraph is 32px but should be 16px based on the surrounding spacing rhythm\" is useful.\n- **Prioritize impact.** Not every pixel matters. Focus on what users will actually notice.\n- **Reference the intent.** Compare against design tokens, mockups, or stated design goals.\n\n## Quick Start\n\n```bash\n# Validate dev server\npinchtab nav http://localhost:3000\npinchtab text        # Token-efficient content check (~800 tokens)\npinchtab screenshot  # Visual inspection\npinchtab snap -i -c  # Interactive compact accessibility tree\n```\n\n---\n\n## Review Categories (Priority Order)\n\n### 1. Layout & Spacing\n\n**Check for:**\n- Consistent spacing rhythm (is everything on the spacing grid?)\n- Alignment -- are elements that should be aligned actually aligned?\n- Padding consistency within similar components\n- Container widths and max-widths\n- No horizontal overflow\n- Responsive behavior (if multiple viewport screenshots available)\n\n**Common issues:**\n- Inconsistent padding in cards (e.g., 24px top, 16px sides)\n- Elements slightly off-grid (15px instead of 16px)\n- Text not aligned with adjacent elements\n- Sections with wildly different vertical spacing\n\n### 2. Typography\n\n**Check for:**\n- Hierarchy -- is it clear what''s a heading vs body vs caption?\n- Line length -- body text should be 45-75 characters per line\n- Line height -- too tight or too loose for the font size?\n- Font weight usage -- are weights used consistently for the same role?\n- Heading hierarchy is correct (h1 > h2 > h3)\n- Orphans/widows -- single words on their own line in headings\n\n**Common issues:**\n- Heading that doesn''t look like a heading (weight/size too close to body)\n- Body text line length > 80 characters (hard to read)\n- Inconsistent heading sizes across sections\n- All-caps text without letter-spacing adjustment\n\n### 3. Color & Contrast\n\n**Check for:**\n- Text meets 4.5:1 contrast ratio\n- UI elements meet 3:1 contrast ratio\n- Consistent use of brand colors\n- Color meaning consistency (is the same blue used for links AND errors?)\n- Dark mode issues (if applicable)\n- Hover/active state visibility\n- UI elements are distinguishable\n\n**Common issues:**\n- Light gray text on white background (contrast fail)\n- Primary color used for too many different purposes\n- Borders that are nearly invisible\n- Status colors that conflict (green for danger, red for success)\n\n### 4. Visual Hierarchy\n\n**Check for:**\n- Eye flow -- where does the eye go first? Is that correct?\n- CTA prominence -- is the primary action the most visible element?\n- Information density -- too sparse or too crowded?\n- Grouping -- are related items visually grouped?\n- White space -- is it used intentionally or just leftover?\n\n**Common issues:**\n- Two equally prominent CTAs competing for attention\n- Important information buried below less important elements\n- Sections that feel disconnected from each other\n- Dense walls of text without visual breaks\n\n### 5. Component Quality\n\n**Check for:**\n- Button sizing and padding consistency\n- Input field styling consistency\n- Card styling consistency (shadows, borders, radius)\n- Icon sizing and alignment with text\n- Image aspect ratios and cropping\n\n**Common issues:**\n- Buttons with inconsistent padding or height\n- Mixed border-radius values (some 8px, some 12px, some 4px)\n- Icons misaligned with adjacent text baselines\n- Images stretched or poorly cropped\n\n### 6. Accessibility\n\n- [ ] All images have `alt` text\n- [ ] Icon-only buttons have `aria-label`\n- [ ] Form inputs have labels\n- [ ] Heading hierarchy is correct\n- [ ] Focus order is logical\n- [ ] Interactive elements >= 44x44px\n- [ ] Adequate spacing between touch targets\n- [ ] Focus indicators present (no `outline: none` without replacement)\n\n### 7. Polish & Micro-details\n\n**Check for:**\n- Hover states exist and are visible\n- Focus states for keyboard navigation\n- Loading states (skeleton screens, spinners)\n- Empty states (what shows when there''s no data?)\n- Transitions between states (abrupt vs smooth)\n- Error states are clear\n\n**Common issues:**\n- No hover state on interactive elements\n- Focus ring removed with no replacement\n- Abrupt content shifts when data loads\n- No empty state -- just a blank area\n\n### 8. Responsive Issues (if multiple viewports available)\n\n**Check for:**\n- Content readable on mobile (not too small)\n- Touch targets >= 44px on mobile\n- Navigation accessible on small screens\n- Images not overflowing containers\n- Horizontal scroll (almost always a bug)\n\n---\n\n## Workflow\n\n1. **Navigate** to target URL\n2. **Screenshot** current state\n3. **Snapshot** accessibility tree\n4. **Analyze** against review categories above\n5. **Score** using the output format below\n6. **Report** issues with actionable fixes\n\n### After Building a Component\n\n1. Render the component in the browser\n2. Take a screenshot\n3. Run visual QA review\n4. Fix issues\n5. Re-screenshot and verify\n\n### After Building a Full Page\n\n1. Screenshot at desktop (1440px), tablet (768px), and mobile (375px)\n2. Run responsive review across all three\n3. Run full review on the desktop version\n4. Fix issues, prioritizing critical ones\n\n### Comparing to a Mockup\n\n1. Get the mockup image:\n   - **From Figma (preferred):** Use `/figma` to launch Figma desktop, navigate to the frame, and screenshot it directly\n   - **Manual:** Figma export, screenshot, or user-provided image\n2. Screenshot the implementation at the same viewport size\n3. Run comparison review\n4. Fix deviations by priority\n\n---\n\n## Commands\n\n```bash\n# Navigate\npinchtab nav http://localhost:3000/page\n\n# Token-efficient page text (~800 tokens — preferred first step)\npinchtab text\n\n# Screenshot\npinchtab screenshot\n\n# Interactive compact accessibility tree\npinchtab snap -i -c\n\n# Interact with elements\npinchtab click e5\npinchtab fill e3 \"test input\"\n\n# Hover states and scroll for below-fold content\npinchtab hover e5\npinchtab scroll down\npinchtab scroll up\n\n# Keyboard interaction\npinchtab press Enter\npinchtab press Tab\n```\n\n**Multi-instance parallel QA:** Test multiple viewports simultaneously using separate pinchtab instances for desktop, tablet, and mobile widths.\n\n---\n\n## Output Formats\n\n### Full Review\n\n```\n## QA Report: [Page/Component]\n\n**Overall impression:** [One sentence -- first gut reaction]\n**Quality score:** [1-10] / 10\n\n### Critical Issues (fix before shipping)\n1. **[Category]:** [Specific issue with exact details]\n   -> **Fix:** [Actionable recommendation]\n\n### Improvements (should fix)\n1. **[Category]:** [Specific issue]\n   -> **Fix:** [Recommendation]\n\n### Minor Polish (nice to fix)\n1. **[Category]:** [Specific issue]\n   -> **Fix:** [Recommendation]\n\n### What''s Working Well\n- [Specific praise -- what''s well-executed]\n- [Another positive]\n\n### Passed Checks\n- [x] Touch targets adequate\n- [x] Heading hierarchy correct\n\n### Issues Found\n- [ ] Missing alt text on hero image\n  -> Add alt=\"...\" to components/hero/index.tsx:15\n\n- [ ] Contrast too low on muted text\n  -> Change text-gray-400 to text-gray-500\n\n### Recommendations\n- Consider adding loading skeleton for async content\n```\n\n### Quick Review\n\n```\n## Quick QA: [Page/Component Name]\n\nScore: [X]/10\n\nTop 3 fixes:\n1. [Most impactful issue + fix]\n2. [Second issue + fix]\n3. [Third issue + fix]\n\nLooks good: [What''s working]\n```\n\n### Comparison Review (Implementation vs Mockup)\n\n```\n## Design vs Implementation Review\n\n**Fidelity score:** [1-10] / 10\n\n### Deviations Found\n1. **[Element]:** Mockup shows [X], implementation has [Y]\n   Impact: [High/Medium/Low]\n   -> **Fix:** [How to match the mockup]\n\n### Matching Well\n- [Elements that accurately match the design]\n```\n\n---\n\n## Prerequisites\n\nRequires `pinchtab` (installed by `setup.sh`).\n"},"lastSynced":"2026-03-08T02:00:23.214Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing advanced visual and accessibility validation capabilities using pinchtab.","zh":"非常适合需要使用pinchtab进行高级视觉和可访问性验证的前端代理","ja":"pinchtabを使用した高度な視覚的およびアクセシビリティの検証機能が必要なフロントエンドエージェントに最適","ko":"pinchtab를 사용하여 고급 시각적 및 접근성 유효성 검사를 필요로 하는 프론트엔드 에이전트에 적합","es":"Perfecto para Agentes Frontend que necesitan capacidades avanzadas de validación visual y de accesibilidad utilizando pinchtab.","fr":"Parfait pour les agents Frontend ayant besoin de capacités avancées de validation visuelle et d''accessibilité utilisant pinchtab.","de":"Perfekt für Frontend-Agents, die erweiterte visuelle und barrierefreie Validierungsfunktionen unter Verwendung von pinchtab benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de capacidades avançadas de validação visual e de acessibilidade usando pinchtab.","ru":"Идеально подходит для фронтенд-агентов, которым необходимы продвинутые возможности визуальной и доступности проверки с помощью pinchtab.","ar":"مثالي لعميل واجهة المستخدم الذي يحتاج إلى إمكانيات متقدمة للتحقق البصري وتوافق معايير الإمكانية باستخدام pinchtab."},"recommendation":{"en":"Empowers agents to perform comprehensive content analysis using automated tooling and structured design review methodology, focusing on visual QA validation and prioritizing impact based on surrounding spacing rhythm.","zh":"赋予代理人使用自动化工具和结构化设计审查方法ology进行全面内容分析的能力，重点关注视觉QA验证，并根据周围间距节奏优先考虑影响","ja":"自動化ツールと構造化されたデザインレビューメソドロジーを使用して包括的なコンテンツ分析を実行するエージェントをEmpowerし、視覚的なQA検証に焦点を当て、周囲のスペースのリズムに基づいて影響を優先する","ko":"자동화 도구와 구조화된 디자인 리뷰 방법론을 사용하여 포괄적인 콘텐츠 분석을 수행할 수 있는 에이전트를 강화하고, 시각적 QA 유효성 검증에 중점을 두고, 주변 간격 리듬에 따라 영향을 우선순위로 지정","es":"Habilita a los agentes a realizar un análisis de contenido integral utilizando herramientas automatizadas y una metodología de revisión de diseño estructurada, centrándose en la validación de QA visual y priorizando el impacto en función del ritmo del espaciado circundante.","fr":"Permet aux agents d''effectuer une analyse de contenu complète à l''aide d''outils automatisés et d''une méthodologie de revue de conception structurée, en se concentrant sur la validation de la QA visuelle et en donnant la priorité à l''impact en fonction du rythme de l''espacement environnant.","de":"Ermächtigt die Agents, eine umfassende Inhaltsanalyse mithilfe automatisierter Werkzeuge und einer strukturierten Design-Review-Methodik durchzuführen, die sich auf die visuelle QA-Validierung konzentriert und die Auswirkungen basierend auf dem umgebenden Spacing-Rhythmus priorisiert.","pt":"Habilita os agentes a realizar uma análise de conteúdo abrangente utilizando ferramentas automatizadas e uma metodologia de revisão de design estruturada, com foco na validação de QA visual e priorizando o impacto com base no ritmo do espaçamento circundante.","ru":"Позволяет агентам выполнять всесторонний анализ контента с помощью автоматических инструментов и структурированной методологии рассмотрения дизайна, сосредоточив внимание на визуальной проверке QA и расставляя приоритеты воздействия на основе ритма окружающего пространства.","ar":"تمكّن الوكيل من إجراء تحليل محتوى شامل باستخدام أدوات تلقائية و منهجية مراجعة تصميم منظمّة، مع التركيز على التحقق البصري من جودة الإنتاج وتحديد الأولويات بناءً على تأثير الإيقاع في المسافة المحيطة."},"useCases":{"en":["Automating visual and accessibility validation for web applications","Generating detailed critique reports with specific feedback on spacing and design rhythm","Debugging visual inconsistencies and accessibility issues in rendered output"],"zh":["为Web应用程序自动执行视觉和可访问性验证","生成详细的批评报告，包括对间距和设计节奏的具体反馈","调试渲染输出中的视觉不一致性和可访问性问题"],"ja":["Webアプリケーションの視覚的およびアクセシビリティの検証を自動化する","スペースとデザインのリズムに関する具体的なフィードバックを含む詳細な批評レポートを生成する","レンダリングされた出力の中の視覚的不一致とアクセシビリティの問題をデバッグする"],"ko":["웹 애플리케이션의 시각적 및 접근성 유효성 검사를 자동화","간격 및 디자인 리듬에 대한 구체적인 피드백을 포함한詳細한 비평 보고서 생성","렌더링된 출력의 시각적 불일치 및 접근성 문제 디버깅"],"es":["Automatizar la validación visual y de accesibilidad para aplicaciones web","Generar informes detallados de crítica con comentarios específicos sobre el espaciado y el ritmo del diseño","Depurar inconsistencias visuales y problemas de accesibilidad en la salida renderizada"],"fr":["Automatiser la validation visuelle et d''accessibilité pour les applications Web","Générer des rapports de critique détaillés avec des commentaires spécifiques sur l''espacement et le rythme de la conception","Déboguer les incohérences visuelles et les problèmes d''accessibilité dans la sortie rendue"],"de":["Automatisieren der visuellen und barrierefreien Validierung für Webanwendungen","Erstellen detaillierter Kritikberichte mit spezifischem Feedback zum Spacing und Designrhythmus","Debuggen von visuellen Inkonsistenzen und Barrierefreiheitsproblemen in der gerenderten Ausgabe"],"pt":["Automatizar a validação visual e de acessibilidade para aplicações web","Gerar relatórios de crítica detalhados com feedback específico sobre espaçamento e ritmo de design","Depurar incongruências visuais e problemas de acessibilidade na saída renderizada"],"ru":["Автоматизировать визуальную и доступность проверку для веб-приложений","Генерировать подробные отчеты с конкретными комментариями о пробеле и ритме дизайна","Отлаживать визуальные несоответствия и проблемы доступности в отображаемом выводе"],"ar":["تحسين التحقق البصري وتوافق معايير الإمكانية لبرامج التطبيق على شبكة الإنترنت","إنتاج تقارير تفصيلية لتقديم ملاحظات محددة حول المسافة والإيقاع في التصميم","تصحيح الشوائب المرئية والمشاكل المتعلقة بتوافق معايير الإمكانية في الإخراج المُحدّث"]},"limitations":{"en":["Requires pinchtab integration","Limited to visual and accessibility validation","Needs structured design review methodology for effective use"],"zh":["需要pinchtab集成","仅限视觉和可访问性验证","需要结构化设计审查方法ology才能有效使用"],"ja":["pinchtabの統合が必要","視覚的およびアクセシビリティの検証のみ","有効に使用するには構造化されたデザインレビューメソドロジーが必要"],"ko":["pinchtab 통합 필요","시각적 및 접근성 유효성 검사만 해당","효과적으로 사용하려면 구조화된 디자인 리뷰 방법론 필요"],"es":["Requiere integración con pinchtab","Limitado a la validación visual y de accesibilidad","Necesita una metodología de revisión de diseño estructurada para un uso efectivo"],"fr":["Nécessite une intégration avec pinchtab","Limité à la validation visuelle et d''accessibilité","Nécessite une méthodologie de revue de conception structurée pour une utilisation efficace"],"de":["Benötigt eine Integration mit pinchtab","Begrenzt auf die visuelle und barrierefreie Validierung","Benötigt eine strukturierte Design-Review-Methodik für eine effektive Verwendung"],"pt":["Requer integração com pinchtab","Limitado à validação visual e de acessibilidade","Necessita de metodologia de revisão de design estruturada para uso eficaz"],"ru":["Требует интеграции с pinchtab","Ограничен визуальной и доступностью проверкой","Требует структурированной методологии рассмотрения дизайна для эффективного использования"],"ar":["يحتاج إلى دمج pinchtab","محدود بالتحقق البصري وتوافق معايير الإمكانية","يحتاج إلى منهجية مراجعة تصميم منظمّة لاستخدامه الفعّال"]},"version":4},"contentHash":"ee70681c3009cbeba8ab504a122506bca38bd63462a086c559a1f0e2b71c2ebf","qualityScore":60}');
