INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('darkroomengineering/cc-settings/qa', 'qa', 'darkroomengineering', 'cc-settings', 'community', 'qa darkroomengineering cc-settings community The qa skill enables developers to perform visual and accessibility validation using pinchtab, combining automated tooling with structured design review methodology. This benefits developers and designers who need to ensure their applications meet visual and accessibility standards. 视觉QA验证结合自动化工具和结构化设计审查方法，确保设计的一致性和质量 ピンチタブを使用した視覚的およびアクセシビリティの検証により、デザインの的一貫性と品質を確保します 핀치탭을_사용한_시각적_및_접근성_검증을_통해_디자인의_일관성_및_품질을_보장합니다 La validación visual de QA combina herramientas automatizadas con una metodología de revisión de diseño estructurada para garantizar la calidad visual de los productos La validation visuelle de QA combine des outils automatisés avec une méthodologie de revue de conception structurée pour assurer la qualité visuelle des produits Die visuelle QA-Validierung kombiniert automatisierte Tools mit einer strukturierten Design-Review-Methodik, um die visuelle Qualität von Produkten sicherzustellen A validação visual QA combina ferramentas automatizadas com metodologia de revisão de design estruturada Визуальная проверка QA сочетает автоматизированные инструменты с методологией структурированного обзора дизайна التحقق المرئي للجودة يجمع بين أدوات التلقائية و منهجية مراجعة التصميم الهيكلية how to use qa for visual validation qa alternative to manual testing qa vs manual validation qa install guide for developers qa setup for automated testing what is qa in software development QA 视觉验证 访问性验证 自动化工具 结构化设计审查 pinchtab 设计审查 Screenshot-first Combines automated tooling with structured design review methodology Utilizes pinchtab for visual and accessibility validation Employs a screenshot-first approach for accurate critique Prioritizes impact in validation, focusing on critical issues Supports specific and detailed critique, including spacing and rhythm analysis qa is a visual validation methodology that combines automated tooling with structured design review, prioritizing impact and specificity in critique.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('johnlindquist/claude/debug', 'community', 'johnlindquist', 'claude', 'johnlindquist/claude', 'debug', 0, 0, 60, '2026-03-08T01:57:15.272Z', '2026-03-08T02:00:25.472Z', '1f986abc0792e51373a463953c05072a7180d28508211663af2ee7df49ef7554', '{"id":"johnlindquist/claude/debug","name":"debug","description":{"en":"Debug is a complete debugging workflow that enforces root cause analysis for developers, combining codebase investigation, GitHub issues search, and multi-framework reasoning.","zh":"Debug技能提供了一个完整的调试工作流，包括代码调查、GitHub问题搜索和多框架推论","ja":"デバッグ機能は、コード検索、GitHub問題検索、多フレームワーク推論を組み合わせた根本原因分析を実現します","ko":"디버그 기능은 코드 조사를 통해根本原因을分析하고 수정합니다","es":"Nuestra herramienta de depuración utiliza una combinación de investigación de código, búsqueda de problemas en GitHub y razonamiento multi-marco para identificar y solucionar problemas","fr":"Notre outil de débogage utilise une combinaison de recherche de code, de recherche de problèmes sur GitHub et de raisonnement multi-cadre pour identifier et résoudre les problèmes","de":"Unser Debug-Tool verwendet eine Kombination aus Code-Untersuchung, GitHub-Problemsuche und Multi-Framework-Reasoning, um Probleme zu identifizieren und zu lösen","pt":"O debug é uma ferramenta de análise de causa raiz que combina investigação de código, busca de issues no GitHub e raciocínio multi-framework para encontrar e corrigir problemas","ru":"Debug - это инструмент анализа причин, который объединяет исследование кода, поиск проблем на GitHub и многофреймворкное рассуждение для выявления и исправления проблем","ar":"Debug هو أداة تحليل السبب الجذري التي تجمع بين التحقيق في الكود والبحث عن مشاكل في GitHub والاستدلال متعدد الإطارات لتحديد ومعالجة المشاكل"},"seo":{"title":{"en":"Debug: Root Cause Debugging Workflow for AI Agents","zh":"Debug Setup Guide: 代码调试工作流","ja":"デバッグ ベストプラクティス: AIエージェントによる根本原因分析","ko":"디버그 워크플ロー 가이드: 코드 조사 및 수정","es":"Guía de configuración de depuración con análisis de causa...","fr":"Guide de débogage avec analyse de cause racine pour les d...","de":"Debug-Setup-Leitfaden mit Root-Cause-Analyse für Entwickler","pt":"Guia de Configuração do Debug - Análise de Causa Raiz","ru":"Настройка Debug - Полный Анализ Причин","ar":"إعداد Debug - تحليل السبب الجذري"},"description":{"en":"Unlock efficient debugging with Debug''s systematic approach. Learn how to investigate, understand, and fix issues with codebase investigation and GitHub issu...","zh":"使用Debug技能进行代码调试，实现根本原因分析和自动修复建议","ja":"AIエージェントを使用したデバッグ：コード検索、GitHub問題検索、多フレームワーク推論","ko":"디버그 기능으로 코드를 조사하고 수정하세요: Gemini CLI와 AI 분석","es":"Aprende a depurar código con nuestra guía de depuración que combina investigación de código, búsqueda de problemas en GitHub y razonamiento multi-marco","fr":"Découvrez comment déboguer votre code avec notre guide qui combine recherche de code, recherche de problèmes sur GitHub et raisonnement multi-cadre","de":"Erfahren Sie, wie Sie Code mit unserer Debug-Anleitung debuggen, die Code-Untersuchung, GitHub-Problemsuche und Multi-Framework-Reasoning kombiniert","pt":"Aprenda a usar o debug para investigar, entender e corrigir problemas no seu código com análise de causa raiz e recomendações de código","ru":"Узнайте, как использовать Debug для расследования, понимания и исправления проблем в вашем коде с помощью анализа причин и рекомендаций по коду","ar":"تعلم كيفية استخدام Debug لتحقيق التحليل الجذري لتحديد وتصحيح مشاكل في كودك"},"definition":{"en":"Debug is a systematic debugging approach that investigates, understands, and fixes issues through codebase investigation, GitHub issues search, and multi-framework reasoning.","zh":"Debug是指一种代码调试技术，用于查找和修复代码错误","ja":"デバッグとは、根本原因を分析してコードのバグを修正するための手法です","ko":"디버그란 코드의 오류를 찾고 수정하는 기술입니다","es":"Depuración es un proceso de análisis de causa raíz que utiliza técnicas de investigación y razonamiento para identificar y solucionar problemas en el código","fr":"Le débogage est un processus d''analyse de cause racine qui utilise des techniques de recherche et de raisonnement pour identifier et résoudre les problèmes dans le code","de":"Debugging ist ein Prozess der Root-Cause-Analyse, der Untersuchungs- und Reasoning-Techniken verwendet, um Probleme im Code zu identifizieren und zu lösen","pt":"O debug é uma ferramenta de análise de causa raiz que ajuda a identificar e corrigir problemas no código","ru":"Debug - это инструмент анализа причин, который помогает выявить и исправить проблемы в коде","ar":"Debug هو أداة تحليل السبب الجذري التي تساعد في تحديد ومعالجة مشاكل في الكود"},"features":{"en":["Codebase investigation for relevant code search","GitHub issues search for known issues and workarounds","Multi-framework reasoning for systematic thinking","Fix generation with specific recommendations and code","Integration with Gemini CLI for AI analysis"],"zh":["代码调查：搜索相关代码","GitHub问题搜索：找到已知问题和解决方法","多框架推论：应用系统化思维","修复生成：提供具体的修复建议和代码"],"ja":["コード検索：関連するコードを検索","GitHub問題検索：既知の問題と解決方法を探す","多フレームワーク推論：体系的な思考を適用","修復生成：具体的な修復提案とコードを提供"],"ko":["코드 조사: 관련 코드를 검색","GitHub 문제 검색: 알려진 문제와 해결 방법을 찾기","다중 프레임워크 추론: 체계적인 사고를 적용","수정 생성: 구체적인 수정 제안과 코드 제공"],"es":["Investigación de código para encontrar problemas","Búsqueda de problemas en GitHub para encontrar soluciones conocidas","Razonamiento multi-marco para aplicar un enfoque sistemático","Generación de soluciones con recomendaciones específicas y código","Análisis de causa raíz para identificar la fuente del problema","Integración con Gemini CLI para análisis de AI"],"fr":["Recherche de code pour trouver des problèmes","Recherche de problèmes sur GitHub pour trouver des solutions connues","Raisonnement multi-cadre pour appliquer une approche systématique","Génération de solutions avec des recommandations spécifiques et du code","Analyse de cause racine pour identifier la source du problème","Intégration avec Gemini CLI pour l''analyse de l''IA"],"de":["Code-Untersuchung, um Probleme zu finden","GitHub-Problemsuche, um bekannte Lösungen zu finden","Multi-Framework-Reasoning, um einen systematischen Ansatz anzuwenden","Generierung von Lösungen mit spezifischen Empfehlungen und Code","Root-Cause-Analyse, um die Quelle des Problems zu identifizieren","Integration mit Gemini CLI für die AI-Analyse"],"pt":["Investigação de código para encontrar problemas","Busca de issues no GitHub para encontrar soluções conhecidas","Raciocínio multi-framework para encontrar a causa raiz","Geração de recomendações de código para corrigir problemas","Integração com o Gemini CLI para análise de código","Suporte a múltiplos frameworks de desenvolvimento"],"ru":["Исследование кода для выявления проблем","Поиск проблем на GitHub для нахождения известных решений","Многофреймворкное рассуждение для выявления коренной причины","Генерация рекомендаций по коду для исправления проблем","Интеграция с Gemini CLI для анализа кода","Поддержка нескольких фреймворков разработки"],"ar":["التحقيق في الكود لتحديد المشاكل","البحث عن مشاكل في GitHub لتحديد الحلول المعروفة","الاستدلال متعدد الإطارات لتحديد السبب الجذري","توليد توصيات الكود لمعالجة المشاكل","التكامل مع Gemini CLI للتحليل الكودي","دعم إطارات متعددة من التطوير"]},"keywords":{"en":["how to use debug","debug setup guide","debug alternative","debug vs print statements","debug install","root cause debugging","codebase investigation","GitHub issues search"],"zh":["代码调试","AI代码分析","GitHub问题搜索","多框架推论","修复生成","Debug技能","代码调查","AIエージェント"],"ja":["コードデバッグ","AIコード分析","GitHub問題検索","多フレームワーク推論","修復生成","デバッグ機能","コード検索","AIエージェント"],"ko":["코드 디버깅","AI 코드 분석","GitHub 문제 검색","다중 프레임워크 추론","수정 생성","디버그 기능","코드 조사","AI 에이전트"],"es":["depuración de código","análisis de causa raíz","herramientas de depuración","investigación de código","búsqueda de problemas en GitHub","razonamiento multi-marco","generación de soluciones","Gemini CLI","análisis de AI","desarrollo de software"],"fr":["débogage de code","analyse de cause racine","outils de débogage","recherche de code","recherche de problèmes sur GitHub","raisonnement multi-cadre","génération de solutions","Gemini CLI","analyse de l''IA","développement de logiciels"],"de":["Code-Debugging","Root-Cause-Analyse","Debug-Tools","Code-Untersuchung","GitHub-Problemsuche","Multi-Framework-Reasoning","Lösungsgenerierung","Gemini CLI","AI-Analyse","Software-Entwicklung"],"pt":["debug","análise de causa raiz","investigação de código","busca de issues no GitHub","raciocínio multi-framework","geração de recomendações de código","Gemini CLI","desenvolvimento de software","correção de problemas"],"ru":["debug","анализ причин","исследование кода","поиск проблем на GitHub","многофреймворкное рассуждение","генерация рекомендаций по коду","Gemini CLI","разработка программного обеспечения","исправление проблем"],"ar":["debug","تحليل السبب الجذري","تحقيق في الكود","البحث عن مشاكل في GitHub","الاستدلال متعدد الإطارات","توليد توصيات الكود","Gemini CLI","تطوير البرمجيات","معالجة المشاكل","أدوات الذكاء الاصطناعي"]}},"owner":"johnlindquist","repo":"claude","repoPath":"johnlindquist/claude","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.272Z","topics":[],"category":"community","skillMd":{"name":"debug","description":"Unified debugging workflow enforcing root cause protocol. Investigate → Understand → Reason → Fix. Use when debugging bugs, errors, or unexpected behavior.","bodyPreview":"# Debug - Root Cause Debugging Workflow\n\nComplete debugging workflow that enforces root cause analysis: Investigate → Understand → Reason → Fix.\n\n## Overview\n\nDebug combines multiple debugging approaches:\n- **Codebase investigation** - Search for relevant code\n- **GitHub issues search** - Find known issues and workarounds\n- **Multi-framework reasoning** - Apply systematic thinking\n- **Fix generation** - Specific recommendations with code\n\n## Prerequisites\n\n```bash\n# Gemini CLI for AI analysis\npi","body":"# Debug - Root Cause Debugging Workflow\n\nComplete debugging workflow that enforces root cause analysis: Investigate → Understand → Reason → Fix.\n\n## Overview\n\nDebug combines multiple debugging approaches:\n- **Codebase investigation** - Search for relevant code\n- **GitHub issues search** - Find known issues and workarounds\n- **Multi-framework reasoning** - Apply systematic thinking\n- **Fix generation** - Specific recommendations with code\n\n## Prerequisites\n\n```bash\n# Gemini CLI for AI analysis\npip install google-generativeai\nexport GEMINI_API_KEY=your_api_key\n\n# gh CLI for GitHub issue search\nbrew install gh\ngh auth login\n```\n\n## Debugging Workflows\n\n### Full Debug (Recommended for Complex Issues)\n\n```bash\n# Phase 1: Investigate codebase\nrg -l \"error pattern\" --type ts\nrg \"relevant_function\" -A 10 -B 5\n\n# Phase 2: Search GitHub for known issues\ngh search issues \"error message\" --repo owner/repo --limit 10\ngh issue view 123 --repo owner/repo\n\n# Phase 3: Reason about root cause\ngemini -m pro -o text -e \"\" \"Given this error and code context, what is the root cause?\n\nError: [error message]\n\nCode:\n\\$(cat src/file.ts)\n\nInvestigation findings:\n- [finding 1]\n- [finding 2]\n\nApply first principles, systematic, and critical thinking frameworks.\"\n\n# Phase 4: Generate fix\ngemini -m pro -o text -e \"\" \"Based on root cause: [cause]\n\nProvide:\n1. Specific code fix\n2. Before/after code\n3. How to verify\n4. How to prevent\"\n```\n\n### Quick Debug (Simple Issues)\n\n```bash\n# Skip deep reasoning, focus on investigation + fix\nrg \"error pattern\" --type ts -A 5 -B 5\n\ngemini -m pro -o text -e \"\" \"Debug this quickly:\n\nProblem: [description]\nError: [message]\n\nCode:\n\\$(cat src/problematic-file.ts)\n\nGive me the root cause and fix in 3 sentences.\"\n```\n\n### Debug with Context (Known Files)\n\n```bash\n# When you already know which files are involved\ngemini -m pro -o text -e \"\" \"Debug using these files:\n\nProblem: [description]\n\nFile 1:\n\\$(cat src/file1.ts)\n\nFile 2:\n\\$(cat src/file2.ts)\n\nProvide:\n1. Root cause\n2. Specific fix with line numbers\n3. Verification steps\"\n```\n\n### Comprehensive Diagnosis (Complex Issues)\n\n```bash\n# Parallel investigation of multiple sources\n\n# Terminal 1: Codebase search\nrg \"error\" --type ts --stats > /tmp/codebase.txt &\n\n# Terminal 2: GitHub issues\ngh search issues \"error\" --limit 20 > /tmp/github.txt &\n\n# Terminal 3: Git history\ngit log --oneline --all -S \"problematic_function\" > /tmp/history.txt &\n\nwait\n\n# Synthesize findings\ngemini -m pro -o text -e \"\" \"Synthesize these diagnostic findings:\n\nCodebase:\n\\$(cat /tmp/codebase.txt)\n\nGitHub Issues:\n\\$(cat /tmp/github.txt)\n\nGit History:\n\\$(cat /tmp/history.txt)\n\nProvide unified diagnosis with:\n1. Most likely root cause\n2. Confidence level\n3. Key evidence\n4. Differential diagnosis\n5. Recommended action\"\n```\n\n## Root Cause Protocol\n\n**Always follow this hierarchy:**\n\n1. **INVESTIGATE** - Search for evidence first\n2. **UNDERSTAND** - Read relevant code\n3. **REASON** - Apply systematic thinking\n4. **FIX** - Only then propose changes\n\n### Forbidden Shortcuts\n\n| Symptom | BANNED Fix | REQUIRED Fix |\n|---------|-----------|--------------|\n| Null error | `if (x) { x.y }` | Find why x is null |\n| Timeout | Increase timeout | Find what''s slow |\n| Flaky test | Skip test | Find race condition |\n| Type error | `as any` | Fix type hierarchy |\n\n## Investigation Commands\n\n### Codebase Search\n\n```bash\n# Find error patterns\nrg \"throw.*Error\" --type ts -A 3\n\n# Find function definitions\nrg \"function functionName|const functionName\" --type ts\n\n# Find usages\nrg \"functionName\\(\" --type ts\n\n# Find recent changes\ngit log --oneline -20 --all -- src/problematic/\ngit diff HEAD~5 -- src/problematic/\n```\n\n### GitHub Issue Search\n\n```bash\n# Search issues\ngh search issues \"error message\" --repo owner/repo --state all\n\n# View issue details\ngh issue view 123 --repo owner/repo --comments\n\n# Search across multiple repos\nfor repo in repo1 repo2 repo3; do\n  gh search issues \"error\" --repo owner/$repo --limit 5\ndone\n```\n\n### Log Analysis\n\n```bash\n# Find logs first\nfind . -name \"*.log\" -type f\n\n# Tail recent logs\ntail -100 logs/app.log | grep -i error\n\n# Search logs for patterns\ngrep -n \"ERROR\\|WARN\" logs/*.log | tail -50\n```\n\n## Framework-Based Reasoning\n\n### First Principles\n\n```bash\ngemini -m pro -o text -e \"\" \"Apply first principles to this bug:\n\nProblem: [description]\n\nQuestions:\n1. What is this code supposed to do?\n2. What is it actually doing?\n3. What assumptions are being made?\n4. Which assumption is wrong?\"\n```\n\n### Systematic Analysis\n\n```bash\ngemini -m pro -o text -e \"\" \"Systematically analyze:\n\nProblem: [description]\n\nWalk through:\n1. Input → What data enters?\n2. Processing → What transformations?\n3. State → What state changes?\n4. Output → What comes out?\n5. Where does expected diverge from actual?\"\n```\n\n### Critical Thinking\n\n```bash\ngemini -m pro -o text -e \"\" \"Challenge assumptions:\n\nProblem: [description]\n\nFor each potential cause:\n- What evidence supports it?\n- What evidence contradicts it?\n- What would we expect to see if true?\n- Can we rule it out?\"\n```\n\n## Output Format\n\nA debug session should produce:\n\n```markdown\n## ROOT CAUSE\nSingle sentence identifying the actual cause.\n\n## CONFIDENCE\nhigh | medium | low\n\n## FIX\nSpecific code changes:\n- File: src/file.ts\n- Line: 42\n- Before: `oldCode()`\n- After: `newCode()`\n\n## VERIFICATION\nHow to verify the fix works:\n1. Run test: `npm test -- specific.test.ts`\n2. Manual check: [steps]\n\n## PREVENTION\nHow to prevent this in the future:\n- Add validation at boundary\n- Add regression test\n```\n\n## Best Practices\n\n1. **Logs first** - Read logs before reading code\n2. **Evidence required** - No fix without citing specific evidence\n3. **One cause** - Find THE root cause, not symptoms\n4. **Verify hypothesis** - Test your theory before fixing\n5. **Prevent recurrence** - Add tests for the failure mode\n6. **Document findings** - Capture what you learned\n"},"lastSynced":"2026-03-08T02:00:25.472Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing advanced root cause analysis and debugging capabilities.","zh":"非常适合需要高级根因分析和调试功能的开发代理。","ja":"高度な根本原因分析およびデバッグ機能を必要とする開発エージェントに最適です。","ko":"고급 루트 원인 분석 및 디버깅 기능을 필요로 하는 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan análisis de causa raíz avanzado y capacidades de depuración.","fr":"Parfait pour les agents de développement ayant besoin d''une analyse de cause racine avancée et de capacités de débogage.","de":"Perfekt für Entwicklungssagenten, die erweiterte Root-Cause-Analyse- und Debugging-Funktionen benötigen.","pt":"Perfeito para agentes de desenvolvimento que precisam de análise avançada de causa raiz e capacidades de depuração.","ru":"Идеально подходит для агентов разработки, которым необходимы продвинутые возможности анализа причин и отладки.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى تحليل متقدم للسبب الجذري وقدرات فحص الأخطاء."},"recommendation":{"en":"Empowers agents to perform comprehensive codebase investigations, utilizing GitHub issues search and multi-framework reasoning to generate specific fix recommendations with code, streamlining the debugging workflow.","zh":"赋予代理执行全面的代码库调查的能力，利用GitHub问题搜索和多框架推理来生成具有代码的特定修复建议，简化了调试工作流程。","ja":"エージェントが包括的なコードベースの調査を実行できるようにし、GitHubの問題検索とマルチフレームワークの推論を利用してコードを含む特定の修正の推奨事項を生成し、デバッグのワークフローを合理化します。","ko":"에이전트가 포괄적인 코드베이스 조사를 수행할 수 있도록 하며 GitHub 문제 검색 및 多 프레임워크 추론을 사용하여 코드가 포함된 특정 수정 권장 사항을 생성하여 디버깅 워크플로우를 간소화합니다.","es":"Habilita a los agentes a realizar investigaciones de código integral, utilizando la búsqueda de problemas de GitHub y razonamiento multi-marco para generar recomendaciones de solución específicas con código, simplificando el flujo de trabajo de depuración.","fr":"Permet aux agents d''effectuer des enquêtes sur l''ensemble du code, en utilisant la recherche de problèmes GitHub et le raisonnement multi-cadre pour générer des recommandations de correction spécifiques avec du code, rationalisant ainsi le flux de travail de débogage.","de":"Ermächtigt Agenten, umfassende Codebasis-Untersuchungen durchzuführen, indem GitHub-Probleme gesucht und multi-Rahmen-Reasoning verwendet werden, um spezifische Behebungs-Empfehlungen mit Code zu generieren, wodurch der Debug-Workflow rationalisiert wird.","pt":"Habilita os agentes a realizar investigações abrangentes do código, utilizando a busca de problemas do GitHub e o raciocínio multi-plataforma para gerar recomendações de reparo específicas com código, racionalizando o fluxo de trabalho de depuração.","ru":"Наделяет агентов возможностью проводить комплексные расследования кодовой базы, используя поиск проблем на GitHub и многофреймворкное рассуждение для генерации конкретных рекомендаций по исправлению с кодом, оптимизируя рабочий процесс отладки.","ar":"يمنح الوكلاء القدرة على إجراء تحقيقات شاملة لقاعدة الشفرة، باستخدام بحث مشاكل GitHub والاستدلال متعدد الإطارات ل生成 توصيات محددة للإصلاح بالرمز، وتبسيط تدفق عمل فحص الأخطاء."},"useCases":{"en":["Investigating codebase issues using systematic thinking","Searching GitHub issues for known problems and workarounds","Generating specific recommendations with code for fix generation"],"zh":["使用系统化思维调查代码库问题","在GitHub问题中搜索已知问题和解决方法","生成具有代码的特定修复建议"],"ja":["体系的な思考を使用してコードベースの問題を調査する","GitHubの問題で既知の問題と回避策を検索する","コードを含む特定の修正の推奨事項を生成する"],"ko":["시스템화된 사고를 사용하여 코드베이스 문제를 조사하다","GitHub 문제에서 알려진 문제 및 해결책을 검색하다","코드가 포함된 특정 수정 권장 사항을 생성하다"],"es":["Investigación de problemas de código utilizando pensamiento sistemático","Búsqueda de problemas conocidos y soluciones alternativas en GitHub","Generación de recomendaciones específicas con código para la generación de soluciones"],"fr":["Enquête sur les problèmes de code à l''aide d''une pensée systématique","Recherche de problèmes connus et de solutions de contournement sur GitHub","Génération de recommandations spécifiques avec du code pour la génération de corrections"],"de":["Untersuchung von Codebasis-Problemen unter Verwendung systematischen Denkens","Suche nach bekannten Problemen und Lösungen in GitHub","Generierung spezifischer Empfehlungen mit Code für die Fehlerbehebung"],"pt":["Investigação de problemas da base de código usando pensamento sistemático","Pesquisa de problemas conhecidos e soluções no GitHub","Geração de recomendações específicas com código para geração de reparos"],"ru":["Расследование проблем кодовой базы с помощью системного мышления","Поиск известных проблем и обходных путей на GitHub","Генерация конкретных рекомендаций с кодом для генерации исправлений"],"ar":["تحقيق في مشاكل قاعدة الشفرة باستخدام التفكير المنهجي","بحث مشاكل معروفة وحلول بديلة على GitHub","توليد توصيات محددة بالرمز لتحسين الإصلاح"]},"limitations":{"en":["Requires Gemini CLI for AI analysis","Limited to codebase and GitHub issues search"],"zh":["需要Gemini CLI进行AI分析","仅限代码库和GitHub问题搜索"],"ja":["AI分析にGemini CLIが必要","コードベースとGitHubの問題検索のみ"],"ko":["AI 분석에 Gemini CLI가 필요함","코드베이스 및 GitHub 문제 검색만"],"es":["Requiere Gemini CLI para análisis de IA","Limitado a la búsqueda de código y problemas de GitHub"],"fr":["Nécessite Gemini CLI pour l''analyse IA","Limité à la recherche de code et de problèmes GitHub"],"de":["Benötigt Gemini CLI für die KI-Analyse","Begrenzt auf Codebasis- und GitHub-Probleme-Suche"],"pt":["Requer Gemini CLI para análise de IA","Limitado à base de código e busca de problemas do GitHub"],"ru":["Требуется Gemini CLI для анализа ИИ","Ограничен кодовой базой и поиском проблем на GitHub"],"ar":["يتطلب Gemini CLI لتحليل الذكاء الاصطناعي","محدود بقاعدة الشفرة وبحث مشاكل GitHub"]},"version":4},"contentHash":"1f986abc0792e51373a463953c05072a7180d28508211663af2ee7df49ef7554","qualityScore":60}');
