INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('johnlindquist/claude/debug', 'debug', 'johnlindquist', 'claude', 'community', 'debug johnlindquist claude community Debug is a complete debugging workflow that enforces root cause analysis for developers, combining codebase investigation, GitHub issues search, and multi-framework reasoning. Debug技能提供了一个完整的调试工作流，包括代码调查、GitHub问题搜索和多框架推论 デバッグ機能は、コード検索、GitHub問題検索、多フレームワーク推論を組み合わせた根本原因分析を実現します 디버그 기능은 코드 조사를 통해根本原因을分析하고 수정합니다 Nuestra herramienta de depuración utiliza una combinación de investigación de código, búsqueda de problemas en GitHub y razonamiento multi-marco para identificar y solucionar problemas Notre outil de débogage utilise une combinaison de recherche de code, de recherche de problèmes sur GitHub et de raisonnement multi-cadre pour identifier et résoudre les problèmes Unser Debug-Tool verwendet eine Kombination aus Code-Untersuchung, GitHub-Problemsuche und Multi-Framework-Reasoning, um Probleme zu identifizieren und zu lösen O debug é uma ferramenta de análise de causa raiz que combina investigação de código, busca de issues no GitHub e raciocínio multi-framework para encontrar e corrigir problemas Debug - это инструмент анализа причин, который объединяет исследование кода, поиск проблем на GitHub и многофреймворкное рассуждение для выявления и исправления проблем Debug هو أداة تحليل السبب الجذري التي تجمع بين التحقيق في الكود والبحث عن مشاكل في GitHub والاستدلال متعدد الإطارات لتحديد ومعالجة المشاكل how to use debug debug setup guide debug alternative debug vs print statements debug install root cause debugging codebase investigation GitHub issues search 代码调试 AI代码分析 GitHub问题搜索 多框架推论 修复生成 Debug技能 代码调查 AIエージェント Codebase investigation for relevant code search GitHub issues search for known issues and workarounds Multi-framework reasoning for systematic thinking Fix generation with specific recommendations and code Integration with Gemini CLI for AI analysis Debug is a systematic debugging approach that investigates, understands, and fixes issues through codebase investigation, GitHub issues search, and multi-framework reasoning.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bjeber/cc-md-search-cli/ccmds', 'community', 'bjeber', 'cc-md-search-cli', 'bjeber/cc-md-search-cli', 'ccmds', 0, 0, 60, '2026-03-08T01:57:15.273Z', '2026-03-08T02:00:25.730Z', '52512042ee6a5c7aab01080dcb12cfb55b18d3817d3095ae6bd1987cb874443f', '{"id":"bjeber/cc-md-search-cli/ccmds","name":"ccmds","description":{"en":"ccmds is a documentation search CLI designed for AI coding assistants, enabling efficient searches for setup, configuration, and API questions. It benefits developers by providing quick access to relevant documentation.","zh":"ccmds 是一个文档搜索 CLI，设计用于 AI 编码助手。它可以快速找到所需文档，提高开发效率","ja":"ccmds は、AI コーディング アシスタント用に設計されたドキュメント検索 CLI です。必要なドキュメントを見つけることができます - AIエージェント","ko":"ccmds는 AI 코딩 어시스턴트를 위해 설계된 문서 검색 CLI입니다. 필요한 문서를 찾을 수 있습니다 - AI 에이전트","es":"ccmds es una herramienta de línea de comandos para la búsqueda de documentación diseñada para asistentes de codificación AI. Mejora la eficiencia en la búsqueda de información","fr":"ccmds est un outil de ligne de commande pour la recherche de documentation conçu pour les assistants de codage IA. Il améliore l''efficacité de la recherche d''informations","de":"ccmds ist ein Kommandozeilen-Tool für die Suche nach Dokumentation, das für AI-Coding-Assistenten entwickelt wurde. Es verbessert die Effizienz bei der Suche nach Informationen","pt":"O ccmds é uma ferramenta de linha de comando para busca de documentação, projetada para assistentes de codificação AI. Ele permite uma busca eficiente de documentação sem a necessidade de ler arquivos diretamente.","ru":"Ccnds - это инструмент командной строки для поиска документации, предназначенный для помощников кодирования ИИ Агенты. Он позволяет выполнять эффективный поиск документации без необходимости直接 читать файлы.","ar":"ccmds هي أداة سطر الأوامر للبحث عن المستندات المصممة للمساعد في كتابة التعليمات البرمجية