INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bjeber/cc-md-search-cli/ccmds', 'ccmds', 'bjeber', 'cc-md-search-cli', 'community', 'ccmds bjeber cc-md-search-cli community ccmds is a documentation search CLI designed for AI coding assistants, enabling efficient searches for setup, configuration, and API questions. It benefits developers by providing quick access to relevant documentation. ccmds 是一个文档搜索 CLI，设计用于 AI 编码助手。它可以快速找到所需文档，提高开发效率 ccmds は、AI コーディング アシスタント用に設計されたドキュメント検索 CLI です。必要なドキュメントを見つけることができます - AIエージェント ccmds는 AI 코딩 어시스턴트를 위해 설계된 문서 검색 CLI입니다. 필요한 문서를 찾을 수 있습니다 - AI 에이전트 ccmds es una herramienta de línea de comandos para la búsqueda de documentación diseñada para asistentes de codificación AI. Mejora la eficiencia en la búsqueda de información ccmds est un outil de ligne de commande pour la recherche de documentation conçu pour les assistants de codage IA. Il améliore l''efficacité de la recherche d''informations ccmds ist ein Kommandozeilen-Tool für die Suche nach Dokumentation, das für AI-Coding-Assistenten entwickelt wurde. Es verbessert die Effizienz bei der Suche nach Informationen O ccmds é uma ferramenta de linha de comando para busca de documentação, projetada para assistentes de codificação AI. Ele permite uma busca eficiente de documentação sem a necessidade de ler arquivos diretamente. Ccnds - это инструмент командной строки для поиска документации, предназначенный для помощников кодирования ИИ Агенты. Он позволяет выполнять эффективный поиск документации без необходимости直接 читать файлы. ccmds هي أداة سطر الأوامر للبحث عن المستندات المصممة للمساعد في كتابة التعليمات البرمجية AI. وهي تسمح بالبحث الفعال عن المستندات دون الحاجة إلى قراءة الملفات مباشرة how to use ccmds ccmds documentation search ccmds setup guide ccmds alternative ccmds vs documentation search tools installing ccmds configuring ccmds ccmds for AI coding assistants efficient documentation search ccmds 文档搜索 CLI AI 编码助手 开发效率 配置文件 命令行工具 Utilizes the `ccmds config` command to view current configuration Initializes a `.ccmdsrc` file using the `ccmds init` command Supports setup and configuration queries through the CLI Enables efficient searching of documentation using specific keywords Facilitates questions about API, installation, and configuration ccmds is a command-line interface tool for searching documentation, designed to assist AI coding assistants with efficient information retrieval.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tofunori/plot-annotator/plot', 'community', 'tofunori', 'plot-annotator', 'tofunori/plot-annotator', 'plot', 0, 0, 60, '2026-03-08T01:57:15.273Z', '2026-03-08T02:00:28.144Z', 'b3c234c8ff8e545566501d2b32fbcc7c66f67f82b9377d772301157c0efcdd4d', '{"id":"tofunori/plot-annotator/plot","name":"plot","description":{"en":"The plot skill is a visual annotation tool for AI-assisted matplotlib modification, benefiting developers and data scientists working with Claude Code & Codex CLI. It enables annotation and modification of plots with ease.","zh":"Plot Skill 是一个用于 AI 协助的 Matplotlib 修改工具，提供注释和修改功能","ja":"Plot スキルは AI アシストの Matplotlib 修正ツールで、注釈と修正機能を提供","ko":"Plot Skill은 AI 보조의 Matplotlib 수정 도구로, 주석 및 수정 기능을 제공","es":"La herramienta de anotación visual de gráficos es una herramienta de AI que permite modificar gráficos matplotlib con Claude Code y Codex CLI","fr":"L''outil d''annotation visuelle de graphiques est un outil d''IA qui permet de modifier les graphiques matplotlib avec Claude Code et Codex CLI","de":"Das visuelle Plot-Annotations-Tool ist ein AI-Tool, das die Bearbeitung von matplotlib-Graphen mit Claude Code und Codex CLI ermöglicht","pt":"A ferramenta de anotação visual plot é uma solução para modificar matplotlib com Claude Code e Codex CLI","ru":"Инструмент визуальной аннотации plot - это решение для модификации matplotlib с помощью Claude Code и Codex CLI","ar":"أداة التخطيط هي حل لتعديل مخططات Matplotlib مع Claude Code و Codex CLI"},"seo":{"title":{"en":"Plot: Visual Annotation Tool for AI-Assisted Matplotlib M...","zh":"AIエージェント Plot_SETUP GUIDE - Matplotlib 修改工具","ja":"AIエージェント Plot セットアップガイド - Matplotlib 修正ツール","ko":"AI 에이전트 Plot 설정 가이드 - Matplotlib 수정 도구","es":"Herramienta de Anotación Visual de Gráficos con Claude Co...","fr":"Outil d''Annotation Visuelle de Graphiques avec Claude Cod...","de":"Visuelle Plot-Annotations-Tool mit Claude Code und Codex CLI","pt":"Guia de Configuração do Plot - Ferramenta de Anotação Vis...","ru":"ИИ Агент Plot: Настройка Инструмента Визуальной Аннотации...","ar":"دليل إعداد أداة التخطيط - أداة تعليمية بصرية لمخططات Matp..."},"description":{"en":"Discover how to annotate matplotlib plots with Claude Code & Codex CLI using the plot skill - get started with our setup guide and tutorials","zh":"使用 Plot Skill 实现 AI 协助的 Matplotlib 修改，包括注释和修改功能","ja":"Plot スキルを使用して AI アシストの Matplotlib 修正を実現し、注釈と修正機能を提供","ko":"Plot Skill을 사용하여 AI 보조의 Matplotlib 수정을 구현하고, 주석 및 수정 기능을 제공","es":"Aprende a utilizar la herramienta de anotación visual de gráficos para modificar gráficos matplotlib con Claude Code y Codex CLI","fr":"Découvrez comment utiliser l''outil d''annotation visuelle de graphiques pour modifier les graphiques matplotlib avec Claude Code et Codex CLI","de":"Erfahren Sie, wie Sie das visuelle Plot-Annotations-Tool verwenden, um matplotlib-Graphen mit Claude Code und Codex CLI zu bearbeiten","pt":"Aprenda a configurar a ferramenta de anotação visual plot para matplotlib com Claude Code e Codex CLI","ru":"Узнайте, как настроить инструмент визуальной аннотации plot для matplotlib с помощью Claude Code и Codex CLI","ar":"تعرف على كيفية إعداد أداة التخطيط بأداة تعليمية بصرية لمخططات Matplotlib مع Claude Code و Codex CLI"},"definition":{"en":"Plot is a visual plot annotation tool for AI-assisted matplotlib modification with Claude Code & Codex CLI, allowing for annotation and modification of plots","zh":"Plot Skill 是一个用于注释和修改 Matplotlib 图表的 AI 工具","ja":"Plot スキルは Matplotlib 図の注釈と修正のための AI ツール","ko":"Plot Skill은 Matplotlib 그래프의 주석 및 수정을 위한 AI 도구","es":"Un plot es una herramienta de anotación visual que permite modificar gráficos matplotlib","fr":"Un plot est un outil d''annotation visuelle qui permet de modifier les graphiques matplotlib","de":"Ein Plot ist ein visuelles Annotations-Tool, das die Bearbeitung von matplotlib-Graphen ermöglicht","pt":"O plot é uma ferramenta de anotação visual para matplotlib","ru":"Plot - это инструмент визуальной аннотации для matplotlib","ar":"أداة التخطيط هي أداة تعليمية بصرية لمخططات Matplotlib"},"features":{"en":["Displays current plot and annotations using `/plot` or `/plot show` command","Loads images and launches annotator with `/plot load <chemin>` command","Launches HTML annotator with `/plot annotate` command","Lists annotations by group with `/plot zones` command","Applies modifications to plots with `/plot apply` command"],"zh":["支持 Claude Code 和 Codex CLI","提供注释和修改 Matplotlib 图表的功能","支持图表区域注释和修改","提供 `/plot` 和 `/plot show` 命令","支持图表加载和注释","提供图表区域列表和修改功能"],"ja":["Claude Code と Codex CLI をサポート","Matplotlib 図の注釈と修正機能を提供","図の領域注釈と修正をサポート","`/plot` と `/plot show` コマンドを提供","図のロードと注釈をサポート","図の領域リストと修正機能を提供"],"ko":["Claude Code와 Codex CLI 지원","Matplotlib 그래프의 주석 및 수정 기능 제공","그래프 영역 주석 및 수정 지원","`/plot` 및 `/plot show` 명령 제공","그래프 로드 및 주석 지원","그래프 영역 목록 및 수정 기능 제공"],"es":["Anotación visual de gráficos matplotlib","Modificación de gráficos con Claude Code y Codex CLI","Uso de zonas coloridas para annotar gráficos","Listado de anotaciones por grupo","Aplicación de modificaciones a gráficos","Carga de imágenes y lanzamiento del annotador"],"fr":["Annotation visuelle de graphiques matplotlib","Modification de graphiques avec Claude Code et Codex CLI","Utilisation de zones colorées pour annoter des graphiques","Liste des annotations par groupe","Application de modifications à des graphiques","Chargement d''images et lancement de l''annotateur"],"de":["Visuelle Annotierung von matplotlib-Graphen","Bearbeitung von Graphen mit Claude Code und Codex CLI","Verwendung von farbigen Zonen zur Annotierung von Graphen","Auflistung von Annotierungen nach Gruppe","Anwendung von Änderungen an Graphen","Laden von Bildern und Starten des Annotators"],"pt":["Anotação visual de plots com zonas coloridas","Modificação de plots com Claude Code e Codex CLI","Comando `/plot` para exibir o plot atual e suas anotações","Comando `/plot load` para carregar uma imagem e lançar o annotador","Comando `/plot annotate` para lançar o annotador HTML","Comando `/plot zones` para listar as anotações por grupo"],"ru":["Визуальная аннотация plot с цветными зонами","Модификация plot с помощью Claude Code и Codex CLI","Команда `/plot` для отображения текущего plot и его аннотаций","Команда `/plot load` для загрузки изображения и запуска аннотатора","Команда `/plot annotate` для запуска аннотатора HTML","Команда `/plot zones` для перечисления аннотаций по группам"],"ar":["أداة تعليمية بصرية لمخططات Matplotlib مع مناطق ملونة","تعديل مخططات Matplotlib مع Claude Code و Codex CLI","الأمر `/plot` لعرض مخطط الحالي وتعليقاته","الأمر `/plot load` لتحميل صورة وتشغيل أداة التعليق","الأمر `/plot annotate` لتشغيل أداة التعليق HTML","الأمر `/plot zones` لاستعراض التعليقات حسب المجموعة"]},"keywords":{"en":["how to use plot with matplotlib","plot alternative to manual annotation","plot setup guide for AI agents","what is plot in AI-assisted development","plot vs other annotation tools","installing plot for Claude Code & Codex CLI","plot tutorial for data scientists","matplotlib plot annotation with plot skill","plot skill for AI-assisted development"],"zh":["AI エージェント","Matplotlib 修改","Plot Skill","Claude Code","Codex CLI","图表注释","图表修改","AI 工具"],"ja":["AI エージェント","Matplotlib 修正","Plot スキル","Claude Code","Codex CLI","図の注釈","図の修正","AI ツール"],"ko":["AI 에이전트","Matplotlib 수정","Plot Skill","Claude Code","Codex CLI","그래프 주석","그래프 수정","AI 도구"],"es":["herramienta de anotación visual de gráficos","modificación de gráficos matplotlib","Claude Code","Codex CLI","AI para gráficos","anotación de gráficos","gráficos matplotlib","herramientas de AI para desarrolladores","plot annotation tool"],"fr":["outil d''annotation visuelle de graphiques","modification de graphiques matplotlib","Claude Code","Codex CLI","IA pour graphiques","annotation de graphiques","graphiques matplotlib","outils d''IA pour développeurs","plot annotation tool"],"de":["visuelles Annotations-Tool für Graphen","Bearbeitung von matplotlib-Graphen","Claude Code","Codex CLI","KI für Graphen","Annotierung von Graphen","matplotlib-Graphen","KI-Tools für Entwickler","plot annotation tool"],"pt":["plot matplotlib","anotação visual","Claude Code","Codex CLI","ferramenta de anotação","modificação de matplotlib","matplotlib python","anotação de plots"],"ru":["ИИ Агент plot","визуальная аннотация","matplotlib","Claude Code","Codex CLI","инструмент аннотации","модификация matplotlib","matplotlib python","аннотация plot"],"ar":["أداة التخطيط","أداة تعليمية بصرية","مخططات Matplotlib","Claude Code","Codex CLI","أداة تعليق","تعديل مخططات Matplotlib","مخططات Matplotlib بال파يثون","تعليق مخططات"]}},"owner":"tofunori","repo":"plot-annotator","repoPath":"tofunori/plot-annotator","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.273Z","topics":[],"category":"community","skillMd":{"name":"plot","description":"Annoter visuellement des plots matplotlib et les modifier via référence par couleur","bodyPreview":"# Skill Plot - Annotation visuelle de plots\n\nWorkflow pour annoter des plots matplotlib avec des zones colorées et les modifier par référence.\n\n## Commandes\n\n| Commande | Description |\n|----------|-------------|\n| `/plot` ou `/plot show` | Affiche le plot actuel et ses annotations |\n| `/plot load <chemin>` | Charge une image et lance l''annotateur |\n| `/plot annotate` | Lance l''annotateur HTML |\n| `/plot zones` | Liste les annotations par groupe |\n| `/plot apply` | Applique les modifications au c","body":"# Skill Plot - Annotation visuelle de plots\n\nWorkflow pour annoter des plots matplotlib avec des zones colorées et les modifier par référence.\n\n## Commandes\n\n| Commande | Description |\n|----------|-------------|\n| `/plot` ou `/plot show` | Affiche le plot actuel et ses annotations |\n| `/plot load <chemin>` | Charge une image et lance l''annotateur |\n| `/plot annotate` | Lance l''annotateur HTML |\n| `/plot zones` | Liste les annotations par groupe |\n| `/plot apply` | Applique les modifications au code source |\n| `/plot list` | Liste tous les plots sauvegardés |\n\n---\n\n## Pipeline complet\n\n### Étape 1: Charger le plot\n```bash\n/plot load /chemin/vers/figure.png\n```\nActions:\n1. Copier l''image vers `~/.claude/plots/current.png`\n2. Chercher le script source automatiquement (grep dans le projet)\n3. Demander la commande de régénération\n4. Sauvegarder les métadonnées\n5. Lancer l''annotateur\n\n### Étape 2: Annoter (utilisateur)\nL''utilisateur dans le navigateur:\n- Zoom/pan pour naviguer\n- Dessiner formes + ajouter texte descriptif\n- **➕ Nouveau groupe** pour séparer les annotations\n- 💾 Sauvegarder\n\n### Étape 3: Appliquer les modifications\n```bash\n/plot apply\n```\nClaude:\n1. Lit les annotations groupées\n2. Pour chaque groupe: forme(s) + texte = une modification\n3. Trouve l''élément matplotlib correspondant\n4. Modifie le code source\n5. Régénère le plot\n\n---\n\n## Format des annotations (JSON)\n\n```json\n{\n  \"zones\": [\n    {\n      \"id\": \"blue\",\n      \"color\": \"#2196F3\",\n      \"type\": \"rect\",\n      \"group_id\": 2,\n      \"bbox\": [1730, 115, 2266, 300],\n      \"label\": null\n    },\n    {\n      \"id\": \"blue\",\n      \"color\": \"#2196F3\",\n      \"type\": \"text\",\n      \"group_id\": 2,\n      \"text\": \"remplacer Dynamic par Updated\",\n      \"position\": [726, 172],\n      \"label\": null\n    },\n    {\n      \"id\": \"red\",\n      \"color\": \"#F44336\",\n      \"type\": \"rect\",\n      \"group_id\": 3,\n      \"bbox\": [197, 1283, 2299, 1487],\n      \"label\": null\n    },\n    {\n      \"id\": \"red\",\n      \"color\": \"#F44336\",\n      \"type\": \"text\",\n      \"group_id\": 3,\n      \"text\": \"plus petit labels\",\n      \"position\": [1758, 1490],\n      \"label\": null\n    }\n  ],\n  \"created\": \"2026-01-22T16:09:51.051Z\",\n  \"plot_name\": \"current\"\n}\n```\n\n**Interprétation:**\n- **Groupe 2 (bleu):** Rectangle sur titre/légende + \"remplacer Dynamic par Updated\"\n- **Groupe 3 (rouge):** Rectangle sur x-axis + \"plus petit labels\"\n\n---\n\n## Logique de `/plot apply`\n\n### 1. Parser les annotations par groupe\n```python\n# Pseudo-code\ngroups = {}\nfor zone in annotations[\"zones\"]:\n    gid = zone[\"group_id\"]\n    if gid not in groups:\n        groups[gid] = {\"shapes\": [], \"text\": None, \"color\": zone[\"id\"]}\n    if zone[\"type\"] == \"text\":\n        groups[gid][\"text\"] = zone[\"text\"]\n    else:\n        groups[gid][\"shapes\"].append(zone)\n```\n\n### 2. Pour chaque groupe, identifier la modification\n| Zone (bbox) | Texte | Action matplotlib |\n|-------------|-------|-------------------|\n| Titre (haut centre) | \"changer X\" | `ax.set_title(...)` |\n| Légende | \"modifier label\" | `ax.legend(...)` ou dans `plot()/scatter()` |\n| Axes X (bas) | \"plus petit\" | `ax.tick_params(axis=''x'', labelsize=...)` |\n| Axes Y (gauche) | \"rotation\" | `ax.set_ylabel(..., rotation=...)` |\n| Points scatter | \"enlever bordure\" | `scatter(..., edgecolors=''none'')` |\n| Ligne | \"changer couleur\" | `plot(..., color=''...'')` |\n\n### 3. Mapper bbox → élément du plot\nPour une image 4200×1650:\n- **Titre:** y < 200, x centré\n- **Légende:** souvent coin supérieur droit ou selon `loc=`\n- **X-axis labels:** y > 1400 (bas)\n- **Y-axis labels:** x < 200 (gauche)\n- **Zone données:** rectangle central\n\n### 4. Modifier le code source\n1. Lire `current_meta.json` pour obtenir `source_script`\n2. Trouver la fonction/section qui génère le plot\n3. Appliquer la modification (ex: ajouter `labelsize=8`)\n4. Sauvegarder le fichier\n\n### 5. Régénérer le plot\n```bash\ncd {regen_cwd} && {regen_cmd}\n```\n\n---\n\n## Actions détaillées par commande\n\n### `/plot show`\n```python\n# 1. Afficher l''image\nRead(\"~/.claude/plots/current.png\")\n\n# 2. Lire métadonnées\nmeta = Read(\"~/.claude/plots/current_meta.json\")\n\n# 3. Lire annotations\nannotations = Read(\"~/.claude/plots/current_annotations.json\")\n\n# 4. Résumer par groupe\nfor group_id, items in group_by(annotations, \"group_id\"):\n    shapes = [i for i in items if i[\"type\"] != \"text\"]\n    text = next((i[\"text\"] for i in items if i[\"type\"] == \"text\"), None)\n    print(f\"Groupe {group_id}: {len(shapes)} forme(s), instruction: {text}\")\n```\n\n### `/plot annotate`\nLance l''annotateur vide (sans image). L''utilisateur peut drag & drop ou cliquer \"current.png\".\n```bash\nfuser -k 8888/tcp 2>/dev/null || true\nsleep 1\npython3 ~/.claude/tools/annotate_server.py &\nsleep 2\nxdg-open \"http://localhost:8888/annotate.html\"  # Sans ?load=true → démarre vide\n```\n\n### `/plot zones`\nLire et afficher `current_annotations.json` groupé par `group_id`.\n\n### `/plot load <chemin>`\n1. `cp <chemin> ~/.claude/plots/current.png`\n2. Chercher script source:\n   ```bash\n   # Extraire nom fichier\n   filename=$(basename <chemin> .png)\n   # Trouver projet root\n   project_root=$(git -C $(dirname <chemin>) rev-parse --show-toplevel 2>/dev/null)\n   # Chercher dans les .py\n   grep -r \"$filename\" --include=\"*.py\" \"$project_root\"\n   ```\n3. Demander commande regen (AskUserQuestion)\n4. Sauver métadonnées\n5. Lancer annotateur avec `?load=true` pour charger l''image automatiquement:\n   ```bash\n   fuser -k 8888/tcp 2>/dev/null || true\n   sleep 1\n   python3 ~/.claude/tools/annotate_server.py &\n   sleep 2\n   xdg-open \"http://localhost:8888/annotate.html?load=true\"\n   ```\n\n### `/plot apply`\n**IMPORTANT:** Suivre cette logique exacte avec CONFIRMATION OBLIGATOIRE:\n\n1. **Lire les fichiers**\n   ```\n   annotations = ~/.claude/plots/current_annotations.json\n   meta = ~/.claude/plots/current_meta.json\n   ```\n\n2. **Grouper les annotations**\n   ```\n   Pour chaque group_id unique:\n     - Collecter les formes (rect, circle, line)\n     - Extraire le texte (instruction)\n   ```\n\n3. **Pour chaque groupe, analyser:**\n   - Où pointe la forme? (bbox → élément matplotlib)\n   - Que demande le texte? (instruction)\n\n4. **Lire le code source** (`meta.source_script`)\n\n5. **AFFICHER UN RÉSUMÉ DÉTAILLÉ** (NE PAS MODIFIER ENCORE!)\n   ```markdown\n   ## Modifications proposées\n\n   **Fichier:** `/chemin/vers/script.py`\n\n   ### Groupe X (couleur):\n   - **Zone ciblée:** [description de l''élément, ex: \"Titre principal\", \"Légende\", \"Labels axe X\"]\n   - **Instruction:** \"texte de l''annotation\"\n   - **Modification proposée:**\n     - Ligne ~XX: `ancien_code`\n     - Devient: `nouveau_code`\n\n   ### Groupe Y (couleur):\n   - **Zone ciblée:** ...\n   - **Instruction:** ...\n   - **Modification proposée:** ...\n\n   ---\n   **Confirmer ces modifications?** (oui/non)\n   ```\n\n6. **ATTENDRE LA CONFIRMATION EXPLICITE**\n   - Si \"oui\" → procéder aux modifications\n   - Si \"non\" → demander ce qui doit être ajusté\n   - NE JAMAIS modifier le code sans confirmation!\n\n7. **Appliquer les modifications** (seulement après confirmation)\n\n8. **Régénérer** si `regen_cmd` disponible\n\n---\n\n## Contrôles de l''annotateur\n\n| Action | Contrôle |\n|--------|----------|\n| Zoom | Molette souris |\n| Pan | Espace+drag, Clic-droit+drag, ou bouton ✋ |\n| Dessiner | Choisir outil (rect/circle/line/freedraw/text) |\n| Texte | Outil 📝 + clic → modal stylée (Enter=OK, Esc=annuler) |\n| Nouveau groupe | Bouton ➕ (sépare les annotations) |\n| Labels | Bouton 🏷️ → panneau latéral |\n| Sauvegarder | Bouton 💾 (auto-save sur disque) |\n| Supprimer | Sélection + Delete |\n\n---\n\n## Fichiers\n\n| Fichier | Contenu |\n|---------|---------|\n| `~/.claude/plots/current.png` | Plot actuel (sauvegardé auto quand user drop + save) |\n| `~/.claude/plots/current_annotated.png` | Plot avec annotations visuelles |\n| `~/.claude/plots/current_meta.json` | Métadonnées (source_script détecté auto) |\n| `~/.claude/plots/current_annotations.json` | Zones annotées avec group_id |\n| `~/.claude/tools/annotate.html` | App HTML (Fabric.js) |\n| `~/.claude/tools/annotate_server.py` | Serveur Python (port 8888) |\n\n## Détection automatique\n\nQuand l''utilisateur drop une image dans l''annotateur et clique Save:\n1. L''image de fond → `current.png`\n2. Le nom du fichier est envoyé au serveur\n3. Le serveur cherche dans les projets connus (`grep -r \"filename\" --include=\"*.py\"`)\n4. Si trouvé → `current_meta.json` est mis à jour avec `source_script`\n\n**Projets scannés:**\n- Dossiers des précédents `/plot load`\n- `~/Github`, `/media/*/Data/Github`\n\n---\n\n## Couleurs disponibles\n\n| Couleur | Hex | Usage suggéré |\n|---------|-----|---------------|\n| blue | #2196F3 | Annotations principales |\n| red | #F44336 | Erreurs, suppressions |\n| green | #4CAF50 | Validations, OK |\n| yellow | #FFEB3B | Attention, warnings |\n| orange | #FF9800 | Modifications secondaires |\n| purple | #9C27B0 | Notes spéciales |\n\n---\n\n## Exemple complet\n\n```\nUtilisateur: /plot load /media/data/outputs/fig_trends.png\n\nClaude: Plot chargé.\n- Source: /media/data/scripts/plot_trends.py\n- Commande regen: python scripts/plot_trends.py --output outputs/\n- Annotateur: http://localhost:8888/annotate.html\n\n[Utilisateur annote: rect bleu sur légende + texte \"Dynamic → Updated\"]\n[Utilisateur annote: rect rouge sur x-axis + texte \"smaller font\"]\n[Utilisateur clique 💾]\n\nUtilisateur: /plot apply\n\nClaude: J''ai analysé 2 groupes d''annotations. Voici les modifications proposées:\n\n---\n## Modifications proposées\n\n**Fichier:** `/media/data/scripts/plot_trends.py`\n\n### Groupe 2 (bleu) - Légende\n- **Zone ciblée:** Légende (bbox: 2491,1146 → 3054,1301)\n- **Instruction:** \"Dynamic → Updated\"\n- **Modification proposée:**\n  - Ligne 45: `label=''Dynamic (Sentinel-2)''`\n  - Devient: `label=''Updated (Sentinel-2)''`\n\n### Groupe 3 (rouge) - Labels axe X\n- **Zone ciblée:** Labels axe X (bbox: 197,1283 → 2299,1487)\n- **Instruction:** \"smaller font\"\n- **Modification proposée:**\n  - Ajouter après ligne 52: `ax.tick_params(axis=''x'', labelsize=8)`\n\n---\n**Confirmer ces modifications?** (oui/non)\n\nUtilisateur: oui\n\nClaude: Modifications appliquées ✓\n- Ligne 45: label mis à jour\n- Ligne 53: tick_params ajouté\n\nRégénération du plot...\n[Commande exécutée]\n\n✅ Nouveau plot généré. Voici le résultat:\n[Affiche le nouveau plot]\n```\n"},"lastSynced":"2026-03-08T02:00:28.144Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Science Agents needing advanced matplotlib plot modification and annotation capabilities.","zh":"非常适合需要高级matplotlib图表修改和注释功能的数据科学代理。","ja":"データサイエンスエージェントが高度なmatplotlibプロットの修正と注釈機能を必要とする場合に最適です。","ko":"데이터 과학 에이전트가 고급 matplotlib 플롯 수정 및 주석 기능을 필요로 할 때 적합합니다.","es":"Perfecto para Agentes de Ciencia de Datos que necesitan capacidades de modificación y anotación de gráficos avanzadas de matplotlib.","fr":"Parfait pour les agents de science des données qui ont besoin de capacités de modification et d''annotation de graphiques avancées de matplotlib.","de":"Perfekt für Data Science-Agents, die erweiterte matplotlib-Plot-Modifizierungs- und Anmerkungsfunktionen benötigen.","pt":"Perfeito para Agentes de Ciência de Dados que necessitam de capacidades avançadas de modificação e anotação de gráficos matplotlib.","ru":"Идеально для агентов Data Science, которым необходимы продвинутые возможности изменения и аннотации графиков matplotlib.","ar":"مثالي للوكلاء علم البيانات الذين يحتاجون إلى إمكانيات متقدمة لتعديل وتعليق مخططات matplotlib."},"recommendation":{"en":"Empowers agents to visually annotate and modify plots using matplotlib, enabling easy reference and modification of plot zones with HTML annotation tools and supporting libraries like Claude Code and Codex CLI.","zh":"赋予代理以使用matplotlib进行可视化注释和修改图表的能力，实现使用HTML注释工具和支持库（如Claude Code和Codex CLI）轻松引用和修改图表区域。","ja":"エージェントがmatplotlibを使用してプロットを視覚的に注釈付けおよび修正できるようにし、HTML注釈ツールやClaude CodeおよびCodex CLIなどのサポートライブラリを使用してプロット領域を簡単に参照および修正できるようにします。","ko":"에이전트가 matplotlib를 사용하여 시각적 주석 및 플롯 수정을 가능하게 하여 HTML 주석 도구 및 Claude Code 및 Codex CLI와 같은 지원 라이브러리를 사용하여 플롯 영역을 쉽게 참조 및 수정할 수 있습니다.","es":"Habilita a los agentes a anotar y modificar visualmente los gráficos usando matplotlib, lo que permite una fácil referencia y modificación de zonas de gráficos con herramientas de anotación HTML y bibliotecas de apoyo como Claude Code y Codex CLI.","fr":"Permet aux agents d''annoter et de modifier visuellement les graphiques à l''aide de matplotlib, ce qui permet une référence et une modification faciles des zones de graphique avec des outils d''annotation HTML et des bibliothèques de support comme Claude Code et Codex CLI.","de":"Ermöglicht es Agenten, Plots visuell mit matplotlib zu annotieren und zu modifizieren, wodurch eine einfache Referenz und Modifizierung von Plot-Bereichen mit HTML-Anmerkungstools und unterstützenden Bibliotheken wie Claude Code und Codex CLI ermöglicht wird.","pt":"Habilita os agentes a anotar e modificar visualmente os gráficos usando matplotlib, permitindo fácil referência e modificação de zonas de gráficos com ferramentas de anotação HTML e bibliotecas de suporte como Claude Code e Codex CLI.","ru":"Наделяет агентов возможностью визуально аннотировать и изменять графики с помощью matplotlib, что позволяет легко ссылаться и изменять зоны графиков с помощью инструментов аннотации HTML и поддерживающих библиотек, таких как Claude Code и Codex CLI.","ar":"يمنح الوكلاء القدرة على تعليق وتعديل الرسوم البيانية بحرية باستخدام matplotlib، مما يسمح بالمرجع السهل وتعديل مناطق الرسم البياني بأدوات التعليق HTML والمكتبات الداعمة مثل Claude Code و Codex CLI."},"useCases":{"en":["Annotating plots with colored zones for data visualization","Modifying existing plots with ease using reference commands","Listing and applying annotations to plot groups"],"zh":["使用颜色区域注释图表以实现数据可视化","使用引用命令轻松修改现有图表","列出并将注释应用于图表组"],"ja":["データ視覚化のためにプロットに色付けされたゾーンで注釈を付ける","参照コマンドを使用して既存のプロットを簡単に修正する","プロットグループに注釈をリストし適用する"],"ko":["데이터 시각화를 위해 플롯에 색상 영역으로 주석을 달기","참조 명령을 사용하여 기존 플롯을 쉽게 수정하기","플롯 그룹에 주석을 나열하고 적용하기"],"es":["Anotar gráficos con zonas de colores para la visualización de datos","Modificar gráficos existentes con facilidad usando comandos de referencia","Listar y aplicar anotaciones a grupos de gráficos"],"fr":["Annoter des graphiques avec des zones de couleurs pour la visualisation de données","Modifier des graphiques existants avec facilité en utilisant des commandes de référence","Répertorier et appliquer des annotations à des groupes de graphiques"],"de":["Plots mit farbigen Zonen für die Datenvisualisierung annotieren","Bestehende Plots mithilfe von Referenzbefehlen leicht modifizieren","Anotierungen auflisten und auf Plot-Gruppen anwenden"],"pt":["Anotar gráficos com zonas coloridas para visualização de dados","Modificar gráficos existentes com facilidade usando comandos de referência","Listar e aplicar anotações a grupos de gráficos"],"ru":["Аннотировать графики цветными зонами для визуализации данных","Изменять существующие графики с легкостью, используя команды ссылок","Перечислять и применять аннотации к группам графиков"],"ar":["تعليق الرسوم البيانية بأزоны ملونة لتصور البيانات","تعديل الرسوم البيانية الحالية بسهولة باستخدام أوامر المرجع","قائمة وتطبيق التعليقات على مجموعات الرسوم البيانية"]},"limitations":{"en":["Requires matplotlib library","Compatible with Claude Code and Codex CLI only"],"zh":["需要matplotlib库","仅与Claude Code和Codex CLI兼容"],"ja":["matplotlibライブラリが必要","Claude CodeおよびCodex CLIのみと互換性がある"],"ko":["matplotlib 라이브러리가 필요","Claude Code 및 Codex CLI만과 호환됨"],"es":["Requiere la biblioteca matplotlib","Compatible solo con Claude Code y Codex CLI"],"fr":["Nécessite la bibliothèque matplotlib","Compatible uniquement avec Claude Code et Codex CLI"],"de":["Benötigt die matplotlib-Bibliothek","Kompatibel nur mit Claude Code und Codex CLI"],"pt":["Requer biblioteca matplotlib","Compatível apenas com Claude Code e Codex CLI"],"ru":["Требуется библиотека matplotlib","Совместимо только с Claude Code и Codex CLI"],"ar":["يتطلب مكتبة matplotlib","متوافق فقط مع Claude Code و Codex CLI"]},"version":4},"contentHash":"b3c234c8ff8e545566501d2b32fbcc7c66f67f82b9377d772301157c0efcdd4d","qualityScore":60}');
