INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tofunori/plot-annotator/plot', 'plot', 'tofunori', 'plot-annotator', 'community', 'plot tofunori plot-annotator community The plot skill is a visual annotation tool for AI-assisted matplotlib modification, benefiting developers and data scientists working with Claude Code & Codex CLI. It enables annotation and modification of plots with ease. Plot Skill 是一个用于 AI 协助的 Matplotlib 修改工具，提供注释和修改功能 Plot スキルは AI アシストの Matplotlib 修正ツールで、注釈と修正機能を提供 Plot Skill은 AI 보조의 Matplotlib 수정 도구로, 주석 및 수정 기능을 제공 La herramienta de anotación visual de gráficos es una herramienta de AI que permite modificar gráficos matplotlib con Claude Code y Codex CLI L''outil d''annotation visuelle de graphiques est un outil d''IA qui permet de modifier les graphiques matplotlib avec Claude Code et Codex CLI Das visuelle Plot-Annotations-Tool ist ein AI-Tool, das die Bearbeitung von matplotlib-Graphen mit Claude Code und Codex CLI ermöglicht A ferramenta de anotação visual plot é uma solução para modificar matplotlib com Claude Code e Codex CLI Инструмент визуальной аннотации plot - это решение для модификации matplotlib с помощью Claude Code и Codex CLI أداة التخطيط هي حل لتعديل مخططات Matplotlib مع Claude Code و Codex CLI how to use plot with matplotlib plot alternative to manual annotation plot setup guide for AI agents what is plot in AI-assisted development plot vs other annotation tools installing plot for Claude Code & Codex CLI plot tutorial for data scientists matplotlib plot annotation with plot skill plot skill for AI-assisted development AI エージェント Matplotlib 修改 Plot Skill Claude Code Codex CLI 图表注释 图表修改 AI 工具 Displays current plot and annotations using `/plot` or `/plot show` command Loads images and launches annotator with `/plot load <chemin>` command Launches HTML annotator with `/plot annotate` command Lists annotations by group with `/plot zones` command Applies modifications to plots with `/plot apply` command Plot is a visual plot annotation tool for AI-assisted matplotlib modification with Claude Code & Codex CLI, allowing for annotation and modification of plots');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('github/gh-aw/gh-agent-session', 'community', 'github', 'gh-aw', 'github/gh-aw', 'gh-agent-session', 0, 0, 60, '2026-03-08T01:57:15.274Z', '2026-03-08T02:00:33.822Z', '405f6c0254baf0251cb7c481f8eeff00c523defd44e7547db3e5efcbd8d5ba67', '{"id":"github/gh-aw/gh-agent-session","name":"gh-agent-session","description":{"en":"The gh-agent-session skill enables developers to create GitHub Copilot coding agent sessions through the command line, automating code changes based on natural language instructions.","zh":"gh-agent-session是一个GitHub CLI扩展，用于创建GitHub Copilot编码代理会话，实现自动代码更改","ja":"gh-agent-sessionはGitHub CLIの拡張機能で、GitHub Copilotを使用して自動コード変更を行う","ko":"gh-agent-session은 GitHub CLI 확장으로 GitHub Copilot을 사용하여 자동 코드 변경을 수행합니다","es":"gh-agent-session es una extensión de CLI que permite crear sesiones de agente de GitHub para automatizar cambios de código con instrucciones de lenguaje natural","fr":"gh-agent-session est une extension CLI qui permet de créer des sessions d''agent GitHub pour automatiser les modifications de code avec des instructions en langage naturel","de":"gh-agent-session ist eine CLI-Erweiterung, die die Erstellung von GitHub-Agent-Sitzungen zum Automatisieren von Codeänderungen mit natürlichen Sprachanweisungen ermöglicht","pt":"O gh-agent-session é uma extensão do GitHub CLI que permite criar sessões de agente do GitHub Copilot através da linha de comando","ru":"ИИ Агенты gh-agent-session - это расширение GitHub CLI, которое позволяет создавать сессии агента GitHub Copilot через командную строку","ar":"غ-عامل-جلسة هو امتداد غيت هاب سي ال آي يسمح بإنشاء جلسات عامل غيت هاب كوبيلوت عبر سطر الأوامر"},"seo":{"title":{"en":"gh-agent-session: Automated Code Changes Setup Guide | AI...","zh":"GitHub AIエージェント会话扩展设置指南","ja":"GitHub AIエージェントセッションのベストプラクティス","ko":"GitHub AI 에이전트 세션 확장 가이드","es":"Guía para configurar gh-agent-session con Agentes de IA","fr":"Paramétrer gh-agent-session pour les Outils d''IA","de":"Einrichten von gh-agent-session mit KI-Agenten","pt":"Guia de Configuração do gh-agent-session: Workflows de Ag...","ru":"Настройка ИИ Агентов: Руководство по gh-agent-session для...","ar":"دليل إعداد غ-عامل-جلسة: تدفقات عمل إيجنت غيت هاب"},"description":{"en":"Discover how to trigger GitHub Copilot for automated code changes with gh-agent-session. Learn to create agent sessions through the command line and optimize...","zh":"了解如何使用gh-agent-session创建GitHub Copilot编码代理会话，实现自动代码更改","ja":"GitHub Copilotを使用して自動コード変更を行うためのgh-agent-sessionの使い方","ko":"GitHub Copilot을 사용하여 자동 코드 변경을 위한 gh-agent-session 설정 방법","es":"Aprende a crear sesiones de agente de GitHub con gh-agent-session y a automatizar cambios de código con instrucciones de lenguaje natural","fr":"Découvrez comment configurer des sessions d''agent GitHub avec gh-agent-session et automatiser les modifications de code avec des instructions en langage naturel","de":"Erfahren Sie, wie Sie GitHub-Agent-Sitzungen mit gh-agent-session erstellen und Codeänderungen mit natürlichen Sprachanweisungen automatisieren","pt":"Aprenda a configurar o gh-agent-session para criar sessões de agente do GitHub Copilot através da linha de comando","ru":"Узнайте, как настроить gh-agent-session для создания сессий агента GitHub Copilot через командную строку","ar":"تعرف على كيفية إعداد غ-عامل-جلسة لإنشاء جلسات عامل غيت هاب كوبيلوت عبر سطر الأوامر"},"definition":{"en":"gh-agent-session is a GitHub CLI Agent Session Extension that creates specialized GitHub issues for automated code changes using natural language instructions.","zh":"gh-agent-session是一种GitHub问题，包含自然语言指令，触发GitHub Copilot进行自动代码更改","ja":"gh-agent-sessionは自然言語指令を含むGitHubの問題で、GitHub Copilotをトリガーして自動コード変更を行う","ko":"gh-agent-session은 자연어 지시문을 포함하는 GitHub 문제로 GitHub Copilot을 트리거하여 자동 코드 변경을 수행합니다","es":"gh-agent-session es una extensión de CLI que crea sesiones de agente de GitHub para automatizar tareas con instrucciones de lenguaje natural","fr":"gh-agent-session est une extension CLI qui crée des sessions d''agent GitHub pour automatiser les tâches avec des instructions en langage naturel","de":"gh-agent-session ist eine CLI-Erweiterung, die GitHub-Agent-Sitzungen zum Automatisieren von Aufgaben mit natürlichen Sprachanweisungen erstellt","pt":"O gh-agent-session é uma sessão de agente do GitHub que contém instruções de linguagem natural para alterações de código","ru":"ИИ Агенты gh-agent-session - это сессия агента GitHub, содержащая инструкции естественного языка для изменений кода","ar":"غ-عامل-جلسة هو جلسة عامل غيت هاب تحتوي على تعليمات لغة طبيعية لتعديلات الكود"},"features":{"en":["Creates GitHub issues that contain natural language instructions for code changes","Triggers GitHub Copilot to perform automated code changes","Uses the `gh agent-task` CLI extension for command line interaction","Supports creation of agent sessions through the command line","Integrates with GitHub Copilot for automated coding tasks"],"zh":["使用GitHub CLI创建编码代理会话","自动代码更改基于自然语言指令","集成GitHub Copilot进行代码更改","支持通过命令行创建和管理会话","扩展GitHub问题触发自动代码更改"],"ja":["GitHub CLIを使用してコードエージェントセッションを作成","自然言語指令に基づく自動コード変更","GitHub Copilotを使用してコード変更を行う","コマンドラインでセッションを作成して管理","GitHubの問題を拡張して自動コード変更をトリガー"],"ko":["GitHub CLI를 사용하여 코드 에이전트 세션を作成","자연어 지시문에 기반한 자동 코드 변경","GitHub Copilot을 사용하여 코드 변경을 수행","명령줄에서 세션을 생성하고 관리","GitHub 문제를 확장하여 자동 코드 변경을 트리거"],"es":["Crea sesiones de agente de GitHub con instrucciones de lenguaje natural","Automatiza cambios de código con la extensión de CLI gh-agent-task","Utiliza el repositorio de GitHub https://github.com/github/agent-task","Permite la creación de sesiones de agente especializadas","Soporta la automatización de tareas con instrucciones de lenguaje natural"],"fr":["Crée des sessions d''agent GitHub avec des instructions en langage naturel","Automatise les modifications de code avec l''extension CLI gh-agent-task","Utilise le réfé