INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mims-harvard/ToolUniverse/devtu-create-tool', 'devtu-create-tool', 'mims-harvard', 'ToolUniverse', 'community', 'devtu-create-tool mims-harvard ToolUniverse community The devtu-create-tool skill enables AI scientists to create new scientific tools following established patterns, helping them avoid common pitfalls and validation errors. devtu-create-tool是一个用于创建科学工具的工具，通过避免常见错误，提高开发效率 devtu-create-toolは、AIエージェントの開発を容易にするためのツールです devtu-create-tool은 도구 생성을 위한 툴로 일반적인 오류를 피하여 개발 효율성을 높입니다 El devtu-create-tool permite a los científicos crear nuevas herramientas siguiendo patrones establecidos con ToolUniverse. Evite errores comunes para una creación exitosa L''outil devtu-create-tool permet aux scientifiques de créer de nouveaux outils en suivant des modèles établis avec ToolUniverse et les Agents IA. Évitez les erreurs courantes pour une création réussie Das devtu-create-tool ermöglicht es Wissenschaftlern, neue Tools nach festen Mustern mit ToolUniverse und KI-Agenten zu erstellen. Vermeiden Sie gängige Fehler für eine erfolgreiche Erstellung O devtu-create-tool é uma ferramenta para criar novos instrumentos científicos seguindo padrões estabelecidos, ajudando a democratizar os cientistas de IA devtu-create-tool - это инструмент для создания новых научных инструментов, следующих установленным шаблонам, помогающий демократизировать ИИ Агентов أداة devtu-create-tool هي أداة لإنشاء أدوات علمية جديدة تتبع الأنماط المحددة ، مما يساعد على دمقرطة علماء الذكاء الاصطناعي how to use devtu-create-tool what is devtu-create-tool devtu-create-tool alternative devtu-create-tool vs ToolUniverse devtu-create-tool install devtu-create-tool setup guide ToolUniverse tool creator avoiding validation errors in devtu-create-tool best practices for devtu-create-tool devtu-create-tool AI工具创建 科学工具开发 避免常见错误 提高开发效率 ToolUniverse AI开发最佳实践 Creates new scientific tools following established patterns with ToolUniverse Avoids missing `default_config.py` entry to prevent silent tool loading failures Validates mutually exclusive parameters to prevent validation errors Supports multi-level testing to catch registration bugs and schema/API issues Enforces tool name length limits to prevent errors (> 55 chars) Provides test examples to ensure agents receive accurate training data devtu-create-tool is a skill that allows AI scientists to create new scientific tools using ToolUniverse, following best practices to avoid common mistakes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('K-Dense-AI/claude-scientific-writer/scientific-slides', 'community', 'K-Dense-AI', 'claude-scientific-writer', 'K-Dense-AI/claude-scientific-writer', 'scientific-slides', 0, 0, 60, '2026-03-08T01:57:15.274Z', '2026-03-08T02:00:36.080Z', '57d9e619d7aaa535b45dadeb204986c3d4bc1bb69e6eab50e83d9063aae3e2d6', '{"id":"K-Dense-AI/claude-scientific-writer/scientific-slides","name":"scientific-slides","description":{"en":"The scientific-slides skill provides comprehensive guidance for creating effective scientific presentations, from structure and content development to visual design and delivery preparation, benefiting researchers and professionals.","zh":"科学幻灯片是一种用于创建有效科学呈现的综合指南，涵盖结构、内容开发、视觉设计和演示准备等方面","ja":"科学スライドは、構造、内容開発、視覚設計、プレゼンテーションの準備など、効果的な科学プレゼンテーションを作成するための包括的なガイドです","ko":"과학 프레젠테이션은 구조, 콘텐츠 개발, 시각적 디자인, 발표 준비 등을 포함한 효과적인 과학 프레젠테이션을 생성하기 위한 포괄적인 가이드입니다","es":"Scientific Slides es una herramienta para crear presentaciones científicas efectivas, desde la estructura y el contenido hasta el diseño visual y la preparación de la presentación.","fr":"Scientific Slides est un outil pour créer des présentations scientifiques efficaces, de la structure et du contenu au design visuel et à la préparation de la présentation.","de":"Scientific Slides ist ein Tool für die Erstellung effektiver wissenschaftlicher Präsentationen, von der Struktur und dem Inhalt bis zum visuellen Design und der Vorbereitung der Präsentation.","pt":"O Scientific Slides é um escritor científico geral que fornece orientação abrangente para criar apresentações científicas eficazes","ru":"Scientific Slides - это общего назначения научный писатель, который предоставляет комплексное руководство по созданию эффективных научных презентаций","ar":"الشرائح العلمية هي أداة كتابة علمية عامة توفر إرشادات شاملة لإنشاء مقالات علمية فعالة"},"seo":{"title"