INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('K-Dense-AI/claude-scientific-writer/scientific-slides', 'scientific-slides', 'K-Dense-AI', 'claude-scientific-writer', 'community', 'scientific-slides K-Dense-AI claude-scientific-writer community The scientific-slides skill provides comprehensive guidance for creating effective scientific presentations, from structure and content development to visual design and delivery preparation, benefiting researchers and professionals. 科学幻灯片是一种用于创建有效科学呈现的综合指南，涵盖结构、内容开发、视觉设计和演示准备等方面 科学スライドは、構造、内容開発、視覚設計、プレゼンテーションの準備など、効果的な科学プレゼンテーションを作成するための包括的なガイドです 과학 프레젠테이션은 구조, 콘텐츠 개발, 시각적 디자인, 발표 준비 등을 포함한 효과적인 과학 프레젠테이션을 생성하기 위한 포괄적인 가이드입니다 Scientific Slides es una herramienta para crear presentaciones científicas efectivas, desde la estructura y el contenido hasta el diseño visual y la preparación de la presentación. Scientific Slides est un outil pour créer des présentations scientifiques efficaces, de la structure et du contenu au design visuel et à la préparation de la présentation. Scientific Slides ist ein Tool für die Erstellung effektiver wissenschaftlicher Präsentationen, von der Struktur und dem Inhalt bis zum visuellen Design und der Vorbereitung der Präsentation. O Scientific Slides é um escritor científico geral que fornece orientação abrangente para criar apresentações científicas eficazes Scientific Slides - это общего назначения научный писатель, который предоставляет комплексное руководство по созданию эффективных научных презентаций الشرائح العلمية هي أداة كتابة علمية عامة توفر إرشادات شاملة لإنشاء مقالات علمية فعالة how to use scientific-slides scientific-slides alternative scientific-slides setup guide what is scientific-slides scientific-slides for researchers creating effective scientific presentations scientific-slides vs powerpoint scientific-slides install scientific presentation design 科学幻灯片 AIエージェント工具 科学呈现 结构和内容开发 视觉设计 演示准备 口头报告 会议 研讨会 辩护 专业演讲 Provides guidance on structure and content development for scientific presentations Offers tips on visual design for engaging scientific slides Prepares users for delivery of oral presentations at conferences and seminars Focuses on key aspects of scientific presentations, including defenses and professional talks Emphasizes critical design philosophy for effective scientific communication scientific-slides is a general-purpose scientific writer skill that aids in creating effective scientific presentations for oral delivery at conferences, seminars, and professional talks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JimLiu/baoyu-skills/baoyu-xhs-images', 'community', 'JimLiu', 'baoyu-skills', 'JimLiu/baoyu-skills', 'baoyu-xhs-images', 0, 0, 60, '2026-03-08T01:57:15.275Z', '2026-03-08T02:00:38.335Z', '2d7ff522076572a6787bbd1696c46e86b49cdc38c4a47f5236157c1164cb5a0a', '{"id":"JimLiu/baoyu-skills/baoyu-xhs-images","name":"baoyu-xhs-images","description":{"en":"baoyu-xhs-images generates infographic series for Xiaohongshu, allowing developers to create visually appealing content with multiple style options. It benefits developers and content creators looking to enhance their visual storytelling.","zh":"Baoyu XHS Images 是一个 Xiaohongshu 信息图表系列生成工具，支持多种样式和布局选项，帮助开发者快速生成高质量的信息图表","ja":"Baoyu XHS Images は Xiaohongshu インフォグラフィックシリーズジェネレーターであり、複数のスタイルとレイアウトオプションをサポートしています","ko":"Baoyu XHS Images는 Xiaohongshu 정보 그래픽 시리즈 생성기로서 여러 가지 스타일과 레이아웃 옵션을 지원하여 개발자가 높은 품질의 정보 그래픽을 빠르게 생성하도록 도와줍니다","es":"baoyu-xhs-images es un generador de series de infografías para Xiaohongshu que utiliza CLI para crear contenido visual atractivo","fr":"baoyu-xhs-images est un générateur de séries d''infographies pour Xiaohongshu qui utilise CLI pour créer un contenu visuel attractif","de":"baoyu-xhs-images ist ein Generators für Infografik-Serien für Xiaohongshu, der CLI verwendet, um ansprechendes visuelles Content zu erstellen","pt":"O baoyu-xhs-images é um gerador de infográficos que transforma conteúdo complexo em séries de infográficos atraentes para Xiaohongshu com múltiplas opções de estilo","ru":"ИИ Агент baoyu-xhs-images - это генератор инфографики, который преобразует сложный контент в привлекательные инфографические серии для Xiaohongshu с несколькими стилями","ar":"وحدة baoyu-xhs-images هي مولد رسومات بيانية تحول المحتوى المعقد إلى سلسلة من الرسومات البيانية الجذابة ل Xiaohongshu مع خيارات نمط متعددة"},"seo":{"title":{"en":"baoyu-xhs-images: Infographic Series Generator for AI Age...","zh":"Baoyu XHS Images Setup Guide - Xiaohongshu Infographic Se...","ja":"Baoyu XHS Images のセットアップガイド - AIエージェントによる Xiaohongshu インフ...","ko":"Baoyu XHS Images 설정 가이드 - Xiaohongshu 인포그래픽 시리즈 생성기","es":"Generador de series de infografías para Xiaohongshu: Conf...","fr":"Guide d''installation et de meilleures pratiques pour baoy...","de":"Einrichtungsanleitung für baoyu-xhs-images: Erstellung vo...","pt":"Guia de Configuração do baoyu-xhs-images: Gerador de Info...","ru":"Настройка ИИ Агента baoyu-xhs-images: Генератор Инфографики","ar":"دليل الإعداد ل baoyu-xhs-images: مولد رسومات بيانية"},"description":{"en":"Discover how to break down complex content into eye-catching infographics with baoyu-xhs-images. Learn to auto-select styles and layouts with ease.","zh":"使用 Baoyu XHS Images 生成 Xiaohongshu 风格的信息图表系列，支持多种样式和布局选项","ja":"Baoyu XHS Images を使用して Xiaohongshu スタイルのインフォグラフィックシリーズを生成します。複数のスタイルとレイアウトオプションをサポートしています","ko":"Baoyu XHS Images를 사용하여 Xiaohongshu 스타일의 정보 그래픽 시리즈를 생성합니다. 여러 가지 스타일과 레이아웃 옵션을 지원합니다","es":"Descubre cómo utilizar baoyu-xhs-images para crear series de infografías atractivas en Xiaohongshu con opciones de estilo múltiples y CLI","fr":"Découvrez comment utiliser baoyu-xhs-images pour créer des séries d''infographies attrayantes sur Xiaohongshu avec des options de style multiples et CLI","de":"Erfahren Sie, wie Sie baoyu-xhs-images verwenden, um ansprechende Infografik-Serien für Xiaohongshu mit mehreren Stiloptionen und CLI zu erstellen","pt":"Aprenda a usar o baoyu-xhs-images para criar infográficos atraentes para Xiaohongshu com opções de estilo e layout personalizáveis","ru":"Узнайте, как использовать ИИ Агент baoyu-xhs-images для создания привлекательных инфографик для Xiaohongshu с настраиваемыми стилями и макетами","ar":"تعرف على كيفية استخدام baoyu-xhs-images لإنشاء رسومات بيانية جذابة ل Xiaohongshu بخيارات نمط وتصميم قابلة للتعديل"},"definition":{"en":"baoyu-xhs-images is a Xiaohongshu Infographic Series Generator that breaks down complex content into eye-catching infographic series with multiple style options.","zh":"Baoyu XHS Images 是一个用于生成 Xiaohongshu 风格信息图表系列的工具","ja":"Baoyu XHS Images は Xiaohongshu スタイルのインフォグラフィックシリーズを生成するためのツールです","ko":"Baoyu XHS Images는 Xiaohongshu 스타일의 정보 그래픽 시리즈를 생성하는 도구입니다","es":"baoyu-xhs-images es un agente de IA para generar series de infografías en Xiaohongshu","fr":"baoyu-xhs-images est un outil d''agent IA pour générer des séries d''infographies sur Xiaohongshu","de":"baoyu-xhs-images ist ein KI-Tool für die Erstellung von Infografik-Serien für Xiaohongshu","pt":"O baoyu-xhs-images é uma ferramenta de linha de comando que gera infográficos personalizáveis para Xiaohongshu","ru":"ИИ Агент baoyu-xhs-images - это командная утилита, которая генерирует настраиваемые инфографики для Xiaohongshu","ar":"وحدة baoyu-xhs-images هي أداة سطر الأوامر التي تولد رسومات بيانية قابلة للتعديل ل Xiaohongshu"},"features":{"en":["Auto-selects style and layout based on content using the /baoyu-xhs-images command","Supports specification of style using the --style option, such as --style notion","Allows specification of layout using the --layout option, such as --layout dense","Combines style and layout options for customized infographic generation","Generates infographic series for Xiaohongshu platform"],"zh":["支持多种样式选项","支持多种布局选项","自动选择样式和布局","命令行界面 (CLI) 支持","支持 Markdown 文件输入"],"ja":["複数のスタイルオプションをサポート","複数のレイアウトオプションをサポート","スタイルとレイアウトの自動選択","コマンドラインインターフェース (CLI) のサポート","Markdown ファイル入力のサポート"],"ko":["여러 가지 스타일 옵션을 지원","여러 가지 레이아웃 옵션을 지원","스타일과 레이아웃의 자동 선택","명령줄 인터페이스 (CLI) 지원","Markdown 파일 입력 지원"],"es":["Opciones de estilo múltiples para la creación de infografías","CLI para la creación automática de series de infografías","Compatibilidad con diferentes layouts para una mejor visualización","Generación de series de infografías para Xiaohongshu","Personalización de la apariencia de las infografías con opciones de estilo y layout"],"fr":["Options de style multiples pour la création d''infographies","CLI pour la création automatique de séries d''infographies","Compatibilité avec différents layouts pour une meilleure visualisation","Génération de séries d''infographies pour Xiaohongshu","Personnalisation de l''apparence des infographies avec des options de style et de layout"],"de":["Mehrere Stiloptionen für die Erstellung von Infografiken","CLI für die automatische Erstellung von Infografik-Serien","Kompatibilität mit verschiedenen Layouts für eine bessere Visualisierung","Erstellung von Infografik-Serien für Xiaohongshu","Anpassung des Erscheinungsbildes der Infografiken mit Stil- und Layout-Optionen"],"pt":["Geração de infográficos com estilo personalizado","Opções de layout flexíveis","Compatibilidade com Xiaohongshu","Interface de linha de comando fácil de usar","Suporte a múltiplos estilos e layouts"],"ru":["Генерация инфографики с настраиваемым стилем","Гибкие опции макета","Совместимость с Xiaohongshu","Простой и удобный интерфейс командной строки","Поддержка нескольких стилей и макетов"],"ar":["إنشاء رسومات بيانية بنمط مخصص","خيارات تصميم مرنة","التوافق مع Xiaohongshu","واجهة سطر الأوامر سهلة الاستخدام","دعم متعدد الأنماط والتصاميم"]},"keywords":{"en":["how to use baoyu-xhs-images","baoyu-xhs-images alternative","baoyu-xhs-images setup guide","what is baoyu-xhs-images","baoyu-xhs-images vs infographic generators","baoyu-xhs-images install","Xiaohongshu infographic series generator","baoyu-xhs-images command line options","generating infographics with baoyu-xhs-images"],"zh":["Baoyu XHS Images","Xiaohongshu 信息图表系列","信息图表生成工具","AI 工具","CLI 工具","Markdown 文件输入"],"ja":["Baoyu XHS Images","Xiaohongshu インフォグラフィックシリーズ","インフォグラフィック生成ツール","AIエージェント","CLI ツール","Markdown ファイル入力"],"ko":["Baoyu XHS Images","Xiaohongshu 정보 그래픽 시리즈","정보 그래픽 생성기","AI 도구","CLI 도구","Markdown 파일 입력"],"es":["baoyu-xhs-images","agente de IA","generador de infografías","Xiaohongshu","CLI","estilo múltiple","layout personalizable","infografías para redes sociales"],"fr":["baoyu-xhs-images","outil d''agent IA","générateur d''infographies","Xiaohongshu","CLI","style multiple","layout personnalisable","infographies pour réseaux sociaux"],"de":["baoyu-xhs-images","KI-Tool","Generators für Infografiken","Xiaohongshu","CLI","mehrere Stiloptionen","anpassbares Layout","Infografiken für soziale Netzwerke"],"pt":["baoyu-xhs-images","gerador de infográficos","Xiaohongshu","ferramenta de linha de comando","infográficos personalizados","estilo personalizado","layout flexível"],"ru":["ИИ Агент baoyu-xhs-images","генератор инфографики","Xiaohongshu","командная утилита","настраиваемые инфографики","настраиваемый стиль","гибкий макет"],"ar":["وحدة baoyu-xhs-images","مولد رسومات بيانية","Xiaohongshu","أداة سطر الأوامر","رسومات بيانية قابلة للتعديل","نمط مخصص","تصميم مرن"]}},"owner":"JimLiu","repo":"baoyu-skills","repoPath":"JimLiu/baoyu-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.275Z","topics":[],"category":"community","skillMd":{"name":"baoyu-xhs-images","description":"Generates Xiaohongshu (Little Red Book) infographic series with 10 visual styles and 8 layouts. Breaks content into 1-10 cartoon-style images optimized for XHS engagement. Use when user mentions 小红书图片, XHS images, RedNote infographics, 小红书种草, or wants social media infographics for Chinese platforms.","bodyPreview":"# Xiaohongshu Infographic Series Generator\n\nBreak down complex content into eye-catching infographic series for Xiaohongshu with multiple style options.\n\n## Usage\n\n```bash\n# Auto-select style and layout based on content\n/baoyu-xhs-images posts/ai-future/article.md\n\n# Specify style\n/baoyu-xhs-images posts/ai-future/article.md --style notion\n\n# Specify layout\n/baoyu-xhs-images posts/ai-future/article.md --layout dense\n\n# Combine style and layout\n/baoyu-xhs-images posts/ai-future/article.md --style","body":"# Xiaohongshu Infographic Series Generator\n\nBreak down complex content into eye-catching infographic series for Xiaohongshu with multiple style options.\n\n## Usage\n\n```bash\n# Auto-select style and layout based on content\n/baoyu-xhs-images posts/ai-future/article.md\n\n# Specify style\n/baoyu-xhs-images posts/ai-future/article.md --style notion\n\n# Specify layout\n/baoyu-xhs-images posts/ai-future/article.md --layout dense\n\n# Combine style and layout\n/baoyu-xhs-images posts/ai-future/article.md --style notion --layout list\n\n# Direct content input\n/baoyu-xhs-images\n[paste content]\n\n# Direct input with options\n/baoyu-xhs-images --style bold --layout comparison\n[paste content]\n```\n\n## Options\n\n| Option | Description |\n|--------|-------------|\n| `--style <name>` | Visual style (see Style Gallery) |\n| `--layout <name>` | Information layout (see Layout Gallery) |\n\n## Two Dimensions\n\n| Dimension | Controls | Options |\n|-----------|----------|---------|\n| **Style** | Visual aesthetics: colors, lines, decorations | cute, fresh, warm, bold, minimal, retro, pop, notion, chalkboard, study-notes |\n| **Layout** | Information structure: density, arrangement | sparse, balanced, dense, list, comparison, flow, mindmap, quadrant |\n\nStyle × Layout can be freely combined. Example: `--style notion --layout dense` creates an intellectual-looking knowledge card with high information density.\n\n## Style Gallery\n\n| Style | Description |\n|-------|-------------|\n| `cute` (Default) | Sweet, adorable, girly - classic Xiaohongshu aesthetic |\n| `fresh` | Clean, refreshing, natural |\n| `warm` | Cozy, friendly, approachable |\n| `bold` | High impact, attention-grabbing |\n| `minimal` | Ultra-clean, sophisticated |\n| `retro` | Vintage, nostalgic, trendy |\n| `pop` | Vibrant, energetic, eye-catching |\n| `notion` | Minimalist hand-drawn line art, intellectual |\n| `chalkboard` | Colorful chalk on black board, educational |\n| `study-notes` | Realistic handwritten photo style, blue pen + red annotations + yellow highlighter |\n\nDetailed style definitions: `references/presets/<style>.md`\n\n## Layout Gallery\n\n| Layout | Description |\n|--------|-------------|\n| `sparse` (Default) | Minimal information, maximum impact (1-2 points) |\n| `balanced` | Standard content layout (3-4 points) |\n| `dense` | High information density, knowledge card style (5-8 points) |\n| `list` | Enumeration and ranking format (4-7 items) |\n| `comparison` | Side-by-side contrast layout |\n| `flow` | Process and timeline layout (3-6 steps) |\n| `mindmap` | Center radial mind map layout (4-8 branches) |\n| `quadrant` | Four-quadrant / circular section layout |\n\nDetailed layout definitions: `references/elements/canvas.md`\n\n## Auto Selection\n\n| Content Signals | Style | Layout |\n|-----------------|-------|--------|\n| Beauty, fashion, cute, girl, pink | `cute` | sparse/balanced |\n| Health, nature, clean, fresh, organic | `fresh` | balanced/flow |\n| Life, story, emotion, feeling, warm | `warm` | balanced |\n| Warning, important, must, critical | `bold` | list/comparison |\n| Professional, business, elegant, simple | `minimal` | sparse/balanced |\n| Classic, vintage, old, traditional | `retro` | balanced |\n| Fun, exciting, wow, amazing | `pop` | sparse/list |\n| Knowledge, concept, productivity, SaaS | `notion` | dense/list |\n| Education, tutorial, learning, teaching, classroom | `chalkboard` | balanced/dense |\n| Notes, handwritten, study guide, knowledge, realistic, photo | `study-notes` | dense/list/mindmap |\n\n## Outline Strategies\n\nThree differentiated outline strategies for different content goals:\n\n### Strategy A: Story-Driven (故事驱动型)\n\n| Aspect | Description |\n|--------|-------------|\n| **Concept** | Personal experience as main thread, emotional resonance first |\n| **Features** | Start from pain point, show before/after change, strong authenticity |\n| **Best for** | Reviews, personal shares, transformation stories |\n| **Structure** | Hook → Problem → Discovery → Experience → Conclusion |\n\n### Strategy B: Information-Dense (信息密集型)\n\n| Aspect | Description |\n|--------|-------------|\n| **Concept** | Value-first, efficient information delivery |\n| **Features** | Clear structure, explicit points, professional credibility |\n| **Best for** | Tutorials, comparisons, product reviews, checklists |\n| **Structure** | Core conclusion → Info card → Pros/Cons → Recommendation |\n\n### Strategy C: Visual-First (视觉优先型)\n\n| Aspect | Description |\n|--------|-------------|\n| **Concept** | Visual impact as core, minimal text |\n| **Features** | Large images, atmospheric, instant appeal |\n| **Best for** | High-aesthetic products, lifestyle, mood-based content |\n| **Structure** | Hero image → Detail shots → Lifestyle scene → CTA |\n\n## File Structure\n\nEach session creates an independent directory named by content slug:\n\n```\nxhs-images/{topic-slug}/\n├── source-{slug}.{ext}             # Source files (text, images, etc.)\n├── analysis.md                     # Deep analysis + questions asked\n├── outline-strategy-a.md           # Strategy A: Story-driven\n├── outline-strategy-b.md           # Strategy B: Information-dense\n├── outline-strategy-c.md           # Strategy C: Visual-first\n├── outline.md                      # Final selected/merged outline\n├── prompts/\n│   ├── 01-cover-[slug].md\n│   ├── 02-content-[slug].md\n│   └── ...\n├── 01-cover-[slug].png\n├── 02-content-[slug].png\n└── NN-ending-[slug].png\n```\n\n**Slug Generation**:\n1. Extract main topic from content (2-4 words, kebab-case)\n2. Example: \"AI工具推荐\" → `ai-tools-recommend`\n\n**Conflict Resolution**:\nIf `xhs-images/{topic-slug}/` already exists:\n- Append timestamp: `{topic-slug}-YYYYMMDD-HHMMSS`\n- Example: `ai-tools` exists → `ai-tools-20260118-143052`\n\n**Source Files**:\nCopy all sources with naming `source-{slug}.{ext}`:\n- `source-article.md`, `source-photo.jpg`, etc.\n- Multiple sources supported: text, images, files from conversation\n\n## Workflow\n\n### Progress Checklist\n\nCopy and track progress:\n\n```\nXHS Infographic Progress:\n- [ ] Step 0: Check preferences (EXTEND.md) ⛔ BLOCKING\n  - [ ] Found → load preferences → continue\n  - [ ] Not found → run first-time setup → MUST complete before Step 1\n- [ ] Step 1: Analyze content → analysis.md\n- [ ] Step 2: Confirmation 1 - Content understanding ⚠️ REQUIRED\n- [ ] Step 3: Generate 3 outline + style variants\n- [ ] Step 4: Confirmation 2 - Outline & style & elements selection ⚠️ REQUIRED\n- [ ] Step 5: Generate images (sequential)\n- [ ] Step 6: Completion report\n```\n\n### Flow\n\n```\nInput → [Step 0: Preferences] ─┬─ Found → Continue\n                               │\n                               └─ Not found → First-Time Setup ⛔ BLOCKING\n                                              │\n                                              └─ Complete setup → Save EXTEND.md → Continue\n                                                                                      │\n        ┌───────────────────────────────────────────────────────────────────────────┘\n        ↓\nAnalyze → [Confirm 1] → 3 Outlines → [Confirm 2: Outline + Style + Elements] → Generate → Complete\n```\n\n### Step 0: Load Preferences (EXTEND.md) ⛔ BLOCKING\n\n**Purpose**: Load user preferences or run first-time setup.\n\n**CRITICAL**: If EXTEND.md not found, MUST complete first-time setup before ANY other questions or steps. Do NOT proceed to content analysis, do NOT ask about style, do NOT ask about layout — ONLY complete the preferences setup first.\n\nCheck EXTEND.md existence (priority order):\n\n```bash\n# macOS, Linux, WSL, Git Bash\ntest -f .baoyu-skills/baoyu-xhs-images/EXTEND.md && echo \"project\"\ntest -f \"$HOME/.baoyu-skills/baoyu-xhs-images/EXTEND.md\" && echo \"user\"\n```\n\n```powershell\n# PowerShell (Windows)\nif (Test-Path .baoyu-skills/baoyu-xhs-images/EXTEND.md) { \"project\" }\nif (Test-Path \"$HOME/.baoyu-skills/baoyu-xhs-images/EXTEND.md\") { \"user\" }\n```\n\n┌────────────────────────────────────────────────────┬───────────────────┐\n│                        Path                        │     Location      │\n├────────────────────────────────────────────────────┼───────────────────┤\n│ .baoyu-skills/baoyu-xhs-images/EXTEND.md           │ Project directory │\n├────────────────────────────────────────────────────┼───────────────────┤\n│ $HOME/.baoyu-skills/baoyu-xhs-images/EXTEND.md     │ User home         │\n└────────────────────────────────────────────────────┴───────────────────┘\n\n┌───────────┬─────────────────────────────────────────────────────────────────────────────────────────────────────┐\n│  Result   │                                              Action                                              │\n├───────────┼─────────────────────────────────────────────────────────────────────────────────────────────────────┤\n│ Found     │ Read, parse, display summary → Continue to Step 1                                                 │\n├───────────┼─────────────────────────────────────────────────────────────────────────────────────────────────────┤\n│ Not found │ ⛔ BLOCKING: Run first-time setup ONLY (see below) → Complete and save EXTEND.md → Then Step 1    │\n└───────────┴─────────────────────────────────────────────────────────────────────────────────────────────────────┘\n\n**First-Time Setup** (when EXTEND.md not found):\n\n**Language**: Use user''s input language or saved language preference.\n\nUse AskUserQuestion with ALL questions in ONE call. See `references/config/first-time-setup.md` for question details.\n\n**EXTEND.md Supports**: Watermark | Preferred style/layout | Custom style definitions | Language preference\n\nSchema: `references/config/preferences-schema.md`\n\n### Step 1: Analyze Content → `analysis.md`\n\nRead source content, save it if needed, and perform deep analysis.\n\n**Actions**:\n1. **Save source content** (if not already a file):\n   - If user provides a file path: use as-is\n   - If user pastes content: save to `source.md` in target directory\n   - **Backup rule**: If `source.md` exists, rename to `source-backup-YYYYMMDD-HHMMSS.md`\n2. Read source content\n3. **Deep analysis** following `references/workflows/analysis-framework.md`:\n   - Content type classification (种草/干货/测评/教程/避坑...)\n   - Hook analysis (爆款标题潜力)\n   - Target audience identification\n   - Engagement potential (收藏/分享/评论)\n   - Visual opportunity mapping\n   - Swipe flow design\n4. Detect source language\n5. Determine recommended image count (2-10)\n6. **Generate clarifying questions** (see Step 2)\n7. **Save to `analysis.md`**\n\n### Step 2: Confirmation 1 - Content Understanding ⚠️\n\n**Purpose**: Validate understanding + collect missing info. **Do NOT skip.**\n\n**Display summary**:\n- Content type + topic identified\n- Key points extracted\n- Tone detected\n- Source images count\n\n**Use AskUserQuestion** for:\n1. Core selling point (multiSelect: true)\n2. Target audience\n3. Style preference: Authentic sharing / Professional review / Aesthetic mood / Auto\n4. Additional context (optional)\n\n**After response**: Update `analysis.md` → Step 3\n\n### Step 3: Generate 3 Outline + Style Variants\n\nBased on analysis + user context, create three distinct strategy variants. Each variant includes both **outline structure** and **visual style recommendation**.\n\n**For each strategy**:\n\n| Strategy | Filename | Outline | Recommended Style |\n|----------|----------|---------|-------------------|\n| A | `outline-strategy-a.md` | Story-driven: emotional, before/after | warm, cute, fresh |\n| B | `outline-strategy-b.md` | Information-dense: structured, factual | notion, minimal, chalkboard |\n| C | `outline-strategy-c.md` | Visual-first: atmospheric, minimal text | bold, pop, retro |\n\n**Outline format** (YAML front matter + content):\n```yaml\n---\nstrategy: a  # a, b, or c\nname: Story-Driven\nstyle: warm  # recommended style for this strategy\nstyle_reason: \"Warm tones enhance emotional storytelling and personal connection\"\nelements:  # from style preset, can be customized in Step 4\n  background: solid-pastel\n  decorations: [clouds, stars-sparkles]\n  emphasis: star-burst\n  typography: highlight\nlayout: balanced  # primary layout\nimage_count: 5\n---\n\n## P1 Cover\n**Type**: cover\n**Hook**: \"入冬后脸不干了🥹终于找到对的面霜\"\n**Visual**: Product hero shot with cozy winter atmosphere\n**Layout**: sparse\n\n## P2 Problem\n**Type**: pain-point\n**Message**: Previous struggles with dry skin\n**Visual**: Before state, relatable scenario\n**Layout**: balanced\n\n...\n```\n\n**Differentiation requirements**:\n- Each strategy MUST have different outline structure AND different recommended style\n- Adapt page count: A typically 4-6, B typically 3-5, C typically 3-4\n- Include `style_reason` explaining why this style fits the strategy\n- Consider user''s style preference from Step 2\n\nReference: `references/workflows/outline-template.md`\n\n### Step 4: Confirmation 2 - Outline & Style & Elements Selection ⚠️\n\n**Purpose**: User chooses outline strategy, confirms visual style, and customizes elements. **Do NOT skip.**\n\n**Display each strategy**:\n- Strategy name + page count + recommended style\n- Page-by-page summary (P1 → P2 → P3...)\n\n**Use AskUserQuestion** with three questions:\n\n**Question 1: Outline Strategy**\n- Strategy A (Recommended if \"authentic sharing\")\n- Strategy B (Recommended if \"professional review\")\n- Strategy C (Recommended if \"aesthetic mood\")\n- Combine: specify pages from each\n\n**Question 2: Visual Style**\n- Use strategy''s recommended style (show which style)\n- Or select from: cute / fresh / warm / bold / minimal / retro / pop / notion / chalkboard\n- Or type custom style description\n\n**Question 3: Visual Elements** (show after style selection)\nDisplay the selected style''s default elements from preset, then ask:\n- Use style defaults (Recommended) - show preview: background, decorations, emphasis\n- Adjust background - options: solid-pastel / solid-saturated / gradient-linear / gradient-radial / paper-texture / grid\n- Adjust decorations - options: hearts / stars-sparkles / flowers / clouds / leaves / confetti\n- Type custom element preferences\n\n**After response**:\n- Single strategy → copy to `outline.md` with confirmed style\n- Combination → merge specified pages with confirmed style\n- Custom request → regenerate based on feedback\n- Style defaults → use preset''s Element Combination as-is\n- Background adjustment → update elements.background with user choice\n- Decorations adjustment → update elements.decorations with user choice\n- Custom elements → parse user''s preferences into elements fields\n- Update `outline.md` frontmatter with final style and elements\n\n### Step 5: Generate Images\n\nWith confirmed outline + style + layout:\n\n**Visual Consistency — Reference Image Chain**:\nTo ensure character/style consistency across all images in a series:\n1. **Generate image 1 (cover) FIRST** — without `--ref`\n2. **Use image 1 as `--ref` for ALL remaining images** (2, 3, ..., N)\n   - This anchors the character design, color rendering, and illustration style\n   - Command pattern: `--ref <path-to-image-01.png>` added to every subsequent generation\n\nThis is critical for styles that use recurring characters, mascots, or illustration elements. Image 1 becomes the visual anchor for the entire series.\n\n**For each image (cover + content + ending)**:\n1. Save prompt to `prompts/NN-{type}-[slug].md` (in user''s preferred language)\n   - **Backup rule**: If prompt file exists, rename to `prompts/NN-{type}-[slug]-backup-YYYYMMDD-HHMMSS.md`\n2. Generate image:\n   - **Image 1**: Generate without `--ref` (this establishes the visual anchor)\n   - **Images 2+**: Generate with `--ref <image-01-path>` for consistency\n   - **Backup rule**: If image file exists, rename to `NN-{type}-[slug]-backup-YYYYMMDD-HHMMSS.png`\n3. Report progress after each generation\n\n**Watermark Application** (if enabled in preferences):\nAdd to each image generation prompt:\n```\nInclude a subtle watermark \"[content]\" positioned at [position].\nThe watermark should be legible but not distracting from the main content.\n```\nReference: `references/config/watermark-guide.md`\n\n**Image Generation Skill Selection**:\n- Check available image generation skills\n- If multiple skills available, ask user preference\n\n**Session Management**:\nIf image generation skill supports `--sessionId`:\n1. Generate unique session ID: `xhs-{topic-slug}-{timestamp}`\n2. Use same session ID for all images\n3. Combined with reference image chain, ensures maximum visual consistency\n\n### Step 6: Completion Report\n\n```\nXiaohongshu Infographic Series Complete!\n\nTopic: [topic]\nStrategy: [A/B/C/Combined]\nStyle: [style name]\nLayout: [layout name or \"varies\"]\nLocation: [directory path]\nImages: N total\n\n✓ analysis.md\n✓ outline-strategy-a.md\n✓ outline-strategy-b.md\n✓ outline-strategy-c.md\n✓ outline.md (selected: [strategy])\n\nFiles:\n- 01-cover-[slug].png ✓ Cover (sparse)\n- 02-content-[slug].png ✓ Content (balanced)\n- 03-content-[slug].png ✓ Content (dense)\n- 04-ending-[slug].png ✓ Ending (sparse)\n```\n\n## Image Modification\n\n| Action | Steps |\n|--------|-------|\n| **Edit** | **Update prompt file FIRST** → Regenerate with same session ID |\n| **Add** | Specify position → Create prompt → Generate → Renumber subsequent files (NN+1) → Update outline |\n| **Delete** | Remove files → Renumber subsequent (NN-1) → Update outline |\n\n**IMPORTANT**: When updating images, ALWAYS update the prompt file (`prompts/NN-{type}-[slug].md`) FIRST before regenerating. This ensures changes are documented and reproducible.\n\n## Content Breakdown Principles\n\n1. **Cover (Image 1)**: Hook + visual impact → `sparse` layout\n2. **Content (Middle)**: Core value per image → `balanced`/`dense`/`list`/`comparison`/`flow`\n3. **Ending (Last)**: CTA / summary → `sparse` or `balanced`\n\n**Style × Layout Matrix** (✓✓ = highly recommended, ✓ = works well):\n\n| | sparse | balanced | dense | list | comparison | flow | mindmap | quadrant |\n|---|:---:|:---:|:---:|:---:|:---:|:---:|:---:|:---:|\n| cute | ✓✓ | ✓✓ | ✓ | ✓✓ | ✓ | ✓ | ✓ | ✓ |\n| fresh | ✓✓ | ✓✓ | ✓ | ✓ | ✓ | ✓✓ | ✓ | ✓ |\n| warm | ✓✓ | ✓✓ | ✓ | ✓ | ✓✓ | ✓ | ✓ | ✓ |\n| bold | ✓✓ | ✓ | ✓ | ✓✓ | ✓✓ | ✓ | ✓ | ✓✓ |\n| minimal | ✓✓ | ✓✓ | ✓✓ | ✓ | ✓ | ✓ | ✓ | ✓ |\n| retro | ✓✓ | ✓✓ | ✓ | ✓✓ | ✓ | ✓ | ✓ | ✓ |\n| pop | ✓✓ | ✓✓ | ✓ | ✓✓ | ✓✓ | ✓ | ✓ | ✓ |\n| notion | ✓✓ | ✓✓ | ✓✓ | ✓✓ | ✓✓ | ✓✓ | ✓✓ | ✓✓ |\n| chalkboard | ✓✓ | ✓✓ | ✓✓ | ✓✓ | ✓ | ✓✓ | ✓✓ | ✓ |\n| study-notes | ✗ | ✓ | ✓✓ | ✓✓ | ✓ | ✓ | ✓✓ | ✓ |\n\n## References\n\nDetailed templates in `references/` directory:\n\n**Elements** (Visual building blocks):\n- `elements/canvas.md` - Aspect ratios, safe zones, grid layouts\n- `elements/image-effects.md` - Cutout, stroke, filters\n- `elements/typography.md` - Decorated text (花字), tags, text direction\n- `elements/decorations.md` - Emphasis marks, backgrounds, doodles, frames\n\n**Presets** (Style presets):\n- `presets/<name>.md` - Element combination definitions (cute, notion, warm...)\n\n**Workflows** (Process guides):\n- `workflows/analysis-framework.md` - Content analysis framework\n- `workflows/outline-template.md` - Outline template with layout guide\n- `workflows/prompt-assembly.md` - Prompt assembly guide\n\n**Config** (Settings):\n- `config/preferences-schema.md` - EXTEND.md schema\n- `config/first-time-setup.md` - First-time setup flow\n- `config/watermark-guide.md` - Watermark configuration\n\n## Notes\n\n- Auto-retry once on failure | Cartoon alternatives for sensitive figures\n- Use confirmed language preference | Maintain style consistency\n- **Two confirmation points required** (Steps 2 & 4) - do not skip\n\n## Extension Support\n\nCustom configurations via EXTEND.md. See **Step 0** for paths and supported options.\n"},"lastSynced":"2026-03-08T02:00:38.335Z","agentAnalysis":{"suitability":{"en":"Perfect for Visual Content Agents needing advanced infographic generation capabilities for Xiaohongshu","zh":"非常适合需要高级信息图表生成功能的视觉内容代理，用于 Xiaohongshu","ja":"Xiaohongshu 向けの高度なインフォグラフィック生成機能を必要とするビジュアルコンテンツエージェントに最適","ko":"Xiaohongshu를 위한 고급 정보 그래픽 생성 기능이 필요한 시각적 콘텐츠 에이전트에 적합","es":"Perfecto para agentes de contenido visual que necesitan capacidades de generación de infografías avanzadas para Xiaohongshu","fr":"Parfait pour les agents de contenu visuel ayant besoin de capacités de génération d''infographies avancées pour Xiaohongshu","de":"Perfekt für visuelle Inhaltsagenten, die erweiterte Infografik-Generierungsfunktionen für Xiaohongshu benötigen","pt":"Perfeito para Agentes de Conteúdo Visual que precisam de capacidades avançadas de geração de infográficos para Xiaohongshu","ru":"Идеально подходит для Визуальных Контент Агентов, которым необходимы продвинутые возможности генерации инфографики для Xiaohongshu","ar":"مثالي للوكلاء المحتوى المرئي الذين يحتاجون إلى قدرات متقدمة لإنشاء رسومات توضيحية لموقع Xiaohongshu"},"recommendation":{"en":"Empowers agents to generate visually appealing infographic series with multiple style options, utilizing markdown files like article.md and providing customizable layouts and styles, such as notion and dense","zh":"使代理能够生成视觉上吸引人的信息图表系列，具有多种样式选项，利用 article.md 等 markdown 文件，并提供可自定义的布局和样式，如 notion 和 dense","ja":"エージェントが視覚的に魅力的なインフォグラフィックシリーズを生成できるようにし、スタイルのオプションが複数あり、article.md などのマークダウンファイルを利用し、notion や dense などのカスタマイズ可能なレイアウトやスタイルを提供","ko":"에이전트가 시각적으로 매력적인 정보 그래픽 시리즈를 생성할 수 있도록 하며, 여러 가지 스타일 옵션이 있으며, article.md와 같은 마크다운 파일을 사용하며, notion 또는 dense와 같은 사용자 정의 가능한 레이아웃 및 스타일을 제공","es":"Habilita a los agentes para generar series de infografías visualmente atractivas con varias opciones de estilo, utilizando archivos markdown como article.md y proporcionando diseños y estilos personalizables, como notion y dense","fr":"Permet aux agents de générer des séries d''infographies visuellement attrayantes avec plusieurs options de style, en utilisant des fichiers markdown comme article.md et en fournissant des mises en page et des styles personnalisables, tels que notion et dense","de":"Ermächtigt Agenten, visuell ansprechende Infografik-Reihen mit mehreren Stiloptionen zu generieren, indem sie Markdown-Dateien wie article.md verwenden und anpassbare Layouts und Stile wie notion und dense bereitstellen","pt":"Habilita os agentes a gerar séries de infográficos visualmente atraentes com múltiplas opções de estilo, utilizando arquivos markdown como article.md e fornecendo layouts e estilos personalizáveis, como notion e dense","ru":"Наделяет агентов возможностью генерировать визуально привлекательные серии инфографики с несколькими вариантами стилей, используя файлы markdown, такие как article.md, и предоставляя настраиваемые макеты и стили, такие как notion и dense","ar":"تمكين الوكلاء من إنشاء سلسلة من الرسومات التوضيحية المرئية بشكل جذاب مع خيارات أسلوب متعددة، باستخدام ملفات markdown مثل article.md و 提供 تخطيطات وأساليب قابلة للتعديل، مثل notion و dense"},"useCases":{"en":["Automating infographic series creation for Xiaohongshu posts","Generating customizable visual content with multiple style options","Enhancing visual storytelling for developers and content creators"],"zh":["为 Xiaohongshu帖子自动创建信息图表系列","使用多种样式选项生成可自定义的视觉内容","为开发人员和内容创作者增强视觉故事讲述"],"ja":["Xiaohongshu投稿のインフォグラフィックシリーズの自動作成","複数のスタイルオプションを使用してカスタマイズ可能なビジュアルコンテンツを生成","開発者とコンテンツクリエイターのための視覚的なストーリーテリングの強化"],"ko":["Xiaohongshu 게시물에 대한 정보 그래픽 시리즈 자동 생성","여러 가지 스타일 옵션을 사용하여 사용자 정의 가능한 시각적 콘텐츠 생성","개발자 및 콘텐츠 제작자를 위한 시각적 스토리 텔링 강화"],"es":["Automatizar la creación de series de infografías para publicaciones de Xiaohongshu","Generar contenido visual personalizable con varias opciones de estilo","Mejorar la narrativa visual para desarrolladores y creadores de contenido"],"fr":["Automatiser la création de séries d''infographies pour les publications Xiaohongshu","Générer du contenu visuel personnalisable avec plusieurs options de style","Améliorer la narration visuelle pour les développeurs et les créate