INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('JimLiu/baoyu-skills/baoyu-xhs-images', 'baoyu-xhs-images', 'JimLiu', 'baoyu-skills', 'community', 'baoyu-xhs-images JimLiu baoyu-skills community baoyu-xhs-images generates infographic series for Xiaohongshu, allowing developers to create visually appealing content with multiple style options. It benefits developers and content creators looking to enhance their visual storytelling. Baoyu XHS Images 是一个 Xiaohongshu 信息图表系列生成工具，支持多种样式和布局选项，帮助开发者快速生成高质量的信息图表 Baoyu XHS Images は Xiaohongshu インフォグラフィックシリーズジェネレーターであり、複数のスタイルとレイアウトオプションをサポートしています Baoyu XHS Images는 Xiaohongshu 정보 그래픽 시리즈 생성기로서 여러 가지 스타일과 레이아웃 옵션을 지원하여 개발자가 높은 품질의 정보 그래픽을 빠르게 생성하도록 도와줍니다 baoyu-xhs-images es un generador de series de infografías para Xiaohongshu que utiliza CLI para crear contenido visual atractivo baoyu-xhs-images est un générateur de séries d''infographies pour Xiaohongshu qui utilise CLI pour créer un contenu visuel attractif baoyu-xhs-images ist ein Generators für Infografik-Serien für Xiaohongshu, der CLI verwendet, um ansprechendes visuelles Content zu erstellen O baoyu-xhs-images é um gerador de infográficos que transforma conteúdo complexo em séries de infográficos atraentes para Xiaohongshu com múltiplas opções de estilo ИИ Агент baoyu-xhs-images - это генератор инфографики, который преобразует сложный контент в привлекательные инфографические серии для Xiaohongshu с несколькими стилями وحدة baoyu-xhs-images هي مولد رسومات بيانية تحول المحتوى المعقد إلى سلسلة من الرسومات البيانية الجذابة ل Xiaohongshu مع خيارات نمط متعددة how to use baoyu-xhs-images baoyu-xhs-images alternative baoyu-xhs-images setup guide what is baoyu-xhs-images baoyu-xhs-images vs infographic generators baoyu-xhs-images install Xiaohongshu infographic series generator baoyu-xhs-images command line options generating infographics with baoyu-xhs-images Baoyu XHS Images Xiaohongshu 信息图表系列 信息图表生成工具 AI 工具 CLI 工具 Markdown 文件输入 Auto-selects style and layout based on content using the /baoyu-xhs-images command Supports specification of style using the --style option, such as --style notion Allows specification of layout using the --layout option, such as --layout dense Combines style and layout options for customized infographic generation Generates infographic series for Xiaohongshu platform baoyu-xhs-images is a Xiaohongshu Infographic Series Generator that breaks down complex content into eye-catching infographic series with multiple style options.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rmyndharis/antigravity-skills/prompt-engineer', 'community', 'rmyndharis', 'antigravity-skills', 'rmyndharis/antigravity-skills', 'prompt-engineer', 0, 0, 60, '2026-03-08T01:57:15.276Z', '2026-03-08T02:00:43.014Z', 'd4e4e7ba871b10b8bb68f303d0e76c3bd754ec52721b7aab1c6585658afff1b1', '{"id":"rmyndharis/antigravity-skills/prompt-engineer","name":"prompt-engineer","description":{"en":"The prompt-engineer skill provides a curated collection of agent skills for Google Antigravity, offering guidance and checklists for prompt engineer tasks and workflows. It benefits developers working on prompt engineer projects.","zh":"Prompt Engineer 是一个用于 Google Antigravity 的 Agent Skills 集合，提供最佳实践和工作流设置指南","ja":"Prompt Engineer は Google Antigravity 用の Agent Skills コレクションであり、ベストプラクティスとワークフローセットアップガイドを提供する","ko":"Prompt Engineer는 Google Antigravity 용 Agent Skills 모음으로, 최적의實踐과 워크플로우 설정 가이드를 제공합니다","es":"El skill prompt-engineer es una colección curada de habilidades para ingenieros de prompts que necesitan orientación y mejores prácticas para sus tareas y flujos de trabajo","fr":"Le skill prompt-engineer est une collection soigneusement sélectionnée de compétences pour les ingénieurs de prompts qui ont besoin de conseils et de meilleures pratiques pour leurs tâches et flux de travail","de":"Das prompt-engineer-Skill ist eine sorgfältig ausgewählte Sammlung von Fähigkeiten für Prompt-Ingenieure, die Anleitung und Best Practices für ihre Aufgaben und Arbeitsabläufe benötigen","pt":"O Prompt Engineer é uma coleção de habilidades de agente para Google Antigravity, projetada para fornecer orientação e melhores práticas para tarefas de desenvolvimento","ru":"Prompt Engineer - это подборка навыков агентов для Google Antigravity, предназначенная для предоставления рекомендаций и лучших практик для задач разработки","ar":"مهندس الترويج ه