INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rmyndharis/antigravity-skills/prompt-engineer', 'prompt-engineer', 'rmyndharis', 'antigravity-skills', 'community', 'prompt-engineer rmyndharis antigravity-skills community The prompt-engineer skill provides a curated collection of agent skills for Google Antigravity, offering guidance and checklists for prompt engineer tasks and workflows. It benefits developers working on prompt engineer projects. Prompt Engineer 是一个用于 Google Antigravity 的 Agent Skills 集合，提供最佳实践和工作流设置指南 Prompt Engineer は Google Antigravity 用の Agent Skills コレクションであり、ベストプラクティスとワークフローセットアップガイドを提供する Prompt Engineer는 Google Antigravity 용 Agent Skills 모음으로, 최적의實踐과 워크플로우 설정 가이드를 제공합니다 El skill prompt-engineer es una colección curada de habilidades para ingenieros de prompts que necesitan orientación y mejores prácticas para sus tareas y flujos de trabajo Le skill prompt-engineer est une collection soigneusement sélectionnée de compétences pour les ingénieurs de prompts qui ont besoin de conseils et de meilleures pratiques pour leurs tâches et flux de travail Das prompt-engineer-Skill ist eine sorgfältig ausgewählte Sammlung von Fähigkeiten für Prompt-Ingenieure, die Anleitung und Best Practices für ihre Aufgaben und Arbeitsabläufe benötigen O Prompt Engineer é uma coleção de habilidades de agente para Google Antigravity, projetada para fornecer orientação e melhores práticas para tarefas de desenvolvimento Prompt Engineer - это подборка навыков агентов для Google Antigravity, предназначенная для предоставления рекомендаций и лучших практик для задач разработки مهندس الترويج هو مجموعة من مهارات الوكيل لجوجل أنتي جرافيتي، مصممة لتوفير الإرشاد وأفضل الممارسات للعمل التطويري how to use prompt-engineer what is prompt-engineer prompt-engineer setup guide prompt-engineer best practices prompt-engineer alternative prompt-engineer vs Google Antigravity prompt-engineer install prompt-engineer workflow management prompt-engineer task optimization prompt-engineer skill for AI agents Prompt Engineer Google Antigravity Agent Skills 工作流设置 最佳实践 开发任务优化 AIエージェント工具 Python CLI Clarifies goals, constraints, and required inputs for prompt engineer tasks Applies relevant best practices and validates outcomes for optimal results Provides actionable steps and verification for prompt engineer workflows Offers detailed examples and resources via the `resources/impl` directory Supports prompt engineer tasks and workflows with curated agent skills Validates outcomes and provides guidance for efficient prompt engineering prompt-engineer is a specialized AI agent skill for working on prompt engineer tasks, providing best practices and validation for efficient workflow management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rohunj/claude-build-workflow/ralph', 'community', 'rohunj', 'claude-build-workflow', 'rohunj/claude-build-workflow', 'ralph', 0, 0, 60, '2026-03-08T01:57:15.276Z', '2026-03-08T02:00:43.166Z', 'a6a8733abaee5b370957ebd6745a56db88712697fc1262f388d2438b6bbcc021', '{"id":"rohunj/claude-build-workflow/ralph","name":"ralph","description":{"en":"Ralph automates workflow for building apps with Claude Code, converting PRDs to prd.json for autonomous execution, benefiting developers and development teams.","zh":"Ralph 是一个自动化工作流工具，用于构建应用程序，通过描述和回答问题来实现自动化构建","ja":"Ralph は、説明と質問に答えることで自動的にアプリケーションを構築する自動化ワークフロー ツールです","ko":"Ralph 는 자동화 워크플로우 도구로, 설명과 질문에 답함으로써 애플리케이션을 자동으로 빌드합니다","es":"Ralph es una herramienta que permite la creación de aplicaciones con Claude Code de manera autónoma, mediante la conversión de PRDs a formato prd.json","fr":"Ralph est un outil qui permet la création d''applications avec Claude Code de manière autonome, via la conversion de PRDs au format prd.json","de":"Ralph ist ein Tool, das die Erstellung von Anwendungen mit Claude Code auf autonome Weise ermöglicht, indem PRDs in das prd.json-Format konvertiert werden","pt":"O Ralph é uma ferramenta de automação de workflows para desenvolvimento de aplicativos com Claude Code. Ele converte PRDs para o formato prd.json","ru":"Ralph - это инструмент для автономной разработки приложений с ИИ Агентами и Claude Code. Он преобразует PRD в формат prd.json","ar":"Ralph هو أداة لتحسين العمليات التشغيلية لتطوير التطبيقات باستخدام Claude Code وأدوات الذكاء الاصطناعي. يقوم بتحويل PRD إلى تنسيق prd.json"},"seo":{"title":{"en":"Ralph: Automated App Building Setup Guide | AI Agent Skill","zh":"Ralph 自动化工作流设置指南","ja":"Ralph AIエージェントの自動化ワークフロー設定","ko":"Ralph 자동화 워크플로우 설정 가이드","es":"Guía de configuración de Ralph para flujos de trabajo aut...","fr":"Guide de mise en 