INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rohunj/claude-build-workflow/ralph', 'ralph', 'rohunj', 'claude-build-workflow', 'community', 'ralph rohunj claude-build-workflow community Ralph automates workflow for building apps with Claude Code, converting PRDs to prd.json for autonomous execution, benefiting developers and development teams. Ralph 是一个自动化工作流工具，用于构建应用程序，通过描述和回答问题来实现自动化构建 Ralph は、説明と質問に答えることで自動的にアプリケーションを構築する自動化ワークフロー ツールです Ralph 는 자동화 워크플로우 도구로, 설명과 질문에 답함으로써 애플리케이션을 자동으로 빌드합니다 Ralph es una herramienta que permite la creación de aplicaciones con Claude Code de manera autónoma, mediante la conversión de PRDs a formato prd.json Ralph est un outil qui permet la création d''applications avec Claude Code de manière autonome, via la conversion de PRDs au format prd.json Ralph ist ein Tool, das die Erstellung von Anwendungen mit Claude Code auf autonome Weise ermöglicht, indem PRDs in das prd.json-Format konvertiert werden O Ralph é uma ferramenta de automação de workflows para desenvolvimento de aplicativos com Claude Code. Ele converte PRDs para o formato prd.json Ralph - это инструмент для автономной разработки приложений с ИИ Агентами и Claude Code. Он преобразует PRD в формат prd.json Ralph هو أداة لتحسين العمليات التشغيلية لتطوير التطبيقات باستخدام Claude Code وأدوات الذكاء الاصطناعي. يقوم بتحويل PRD إلى تنسيق prd.json how to use ralph what is ralph ralph alternative ralph vs claude code ralph install ralph setup guide automated app building prd.json format claude code integration Ralph 自动化工作流 PRD 转换 JSON 格式 Claude Code 自动化构建 应用程序开发 Markdown 文件 自动化工具 Converts existing PRDs to prd.json format Supports autonomous execution using Claude Code Generates project structure with branchName and description Creates userStories in prd.json with id, title, and description Takes markdown files or text as input for PRD conversion Outputs prd.json in the ralph directory Ralph is an automated workflow tool for building apps with Claude Code, utilizing prd.json format for autonomous execution.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ancoleman/ai-design-components/evaluating-llms', 'community', 'ancoleman', 'ai-design-components', 'ancoleman/ai-design-components', 'evaluating-llms', 0, 0, 60, '2026-03-08T01:57:15.277Z', '2026-03-08T02:00:44.041Z', '55f8ebd7adde6b6befaa8f89b1d9e95a6790d3f026a448dfe03ab58caea7522a', '{"id":"ancoleman/ai-design-components/evaluating-llms","name":"evaluating-llms","description":{"en":"The evaluating-llms skill enables developers to assess Large Language Model systems using automated metrics and standardized benchmarks, ensuring production quality and safety for AI-assisted development with Claude.","zh":"评估大型语言模型（LLM）系统，使用自动化指标、LLM-as-judge模式和标准基准来确保生产质量和安全性","ja":"LLM評価では、自動化メトリック、LLM-as-judgeパターン、標準ベンチマークを使用して、生成の品質と安全性を確保します","ko":"LLM 평가를 통해 자동화된 메트릭, LLM-as-judge 패턴, 표준 벤치마크를 사용하여 생산 품질과 안전성을 보장합니다","es":"La evaluación de LLM implica el uso de métricas automatizadas y estándares de calidad para garantizar la producción y seguridad de AI Agents","fr":"L''évaluation de LLM consiste à utiliser des métriques automatisées et des normes de qualité pour assurer la production et la sécurité des outils d''IA","de":"Die LLM-Evaluierung beinhaltet die Verwendung von automatisierten Metriken und Qualitätsstandards, um die Produktion und Sicherheit von KI-Tools zu gewährleisten","pt":"Avalie modelos de linguagem grande com eficácia, utilizando métricas automatizadas e padrões de julgamento para garantir a qualidade e segurança","ru":"Оцените модели крупномасштабного языка эффективно, используя автоматизированные метрики и шаблоны судейства для обеспечения качества и безопасности","ar":"قيم نماذج اللغة الكبيرة بفعالية، باستخدام معايير آلية ونماذج الحكم لتأمين الجودة والسلامة"},"seo":{"title":{"en":"Evaluating-LLMs: LLM Evaluation Setup Guide | AI Agent Skill","zh":"评估大型语言模型（LLM）系统的最佳实践","ja":"LLM評価のセットアップガイド - AIエージェント","ko":"LLM 평가를 위한 기술 가이드 - AI 도구","es":"Guía de evaluación de LLM: Mejores prácticas para AI Agents","fr":"Évaluation de LLM: Guide de configuration pour les outils...","de":"LLM-Evaluierung: Leitfaden für die Entwicklung von KI-Tools","pt":"Guia de Avaliação de LLMs: Melhores Práticas para Desenvo...","ru":"Оценка ИИ Агентов: Руководство по оценке моделей LLM","ar":"دليل تقييم LLM: إرشادات لتقيم أداء الوكلاء الذكاء الاصطناعي"},"description":{"en":"Discover how to evaluate Large Language Model systems with automated metrics and benchmarks. Learn to ensure production quality and safety with evaluating-ll...","zh":"了解如何使用自动化指标和标准基准来评估LLM系统，确保生产质量和安全性","ja":"LLM評価では、自動化メトリックと標準ベンチマークを使用して、生成の品質と安全性を確保します","ko":"LLM 평가를 통해 자동화된 메트릭과 표준 벤치마크를 사용하여 생산 품질과 안전성을 보장합니다","es":"Aprende a evaluar sistemas de LLM con métricas automatizadas y estándares de calidad para garantizar la seguridad y producción de AI Agents","fr":"Découvrez comment évaluer les systèmes de LLM avec des métriques automatisées et des normes de qualité pour assurer la sécurité et la production des outils d''IA","de":"Erfahren Sie, wie Sie LLM-Systeme mit automatisierten Metriken und Qualitätsstandards bewerten, um die Sicherheit und Produktion von KI-Tools zu gewährleisten","pt":"Aprenda a avaliar modelos de linguagem grande com métricas automatizadas e padrões de julgamento para garantir a qualidade e segurança em produção","ru":"Узнайте, как оценивать модели крупномасштабного языка с помощью автоматизированных метрик и шаблонов судейства для обеспечения качества и безопасности в прои...","ar":"تعرف على كيفية تقييم نماذج اللغة الكبيرة باستخدام معايير آلية ونماذج الحكم لتأمين الجودة والسلامة في الإنتاج"},"definition":{"en":"Evaluating-llms is a skill that evaluates Large Language Model systems using automated metrics, LLM-as-judge patterns, and standardized benchmarks","zh":"LLM评估是指使用自动化指标和标准基准来评估大型语言模型系统的过程","ja":"LLM評価とは、自動化メトリックと標準ベンチマークを使用して、LLMシステムを評価するプロセスです","ko":"LLM 평가란 자동화된 메트릭과 표준 벤치마크를 사용하여 LLM 시스템을 평가하는 과정입니다","es":"La evaluación de LLM es el proceso de análisis de sistemas de lenguaje para garantizar su calidad y seguridad","fr":"L''évaluation de LLM est le processus d''analyse de systèmes de langage pour assurer leur qualité et sécurité","de":"Die LLM-Evaluierung ist der Prozess der Analyse von Sprachsystemen, um ihre Qualität und Sicherheit zu gewährleisten","pt":"Avaliação de LLMs é o processo de avaliar modelos de linguagem grande para garantir a qualidade e segurança","ru":"Оценка ИИ Агентов - это процесс оценки моделей крупномасштабного языка для обеспечения качества и безопасности","ar":"تقييم LLM هو عملية تقييم نماذج اللغة الكبيرة لتأمين الجودة والسلامة"},"features":{"en":["Evaluate LLM systems using automated metrics","Apply LLM-as-judge patterns for quality assessment","Utilize standardized benchmarks for production quality","Test individual prompts for correctness and formatting","Validate RAG pipeline quality and measure hallucinations, bias, or toxicity in LLM outputs"],"zh":["使用自动化指标评估LLM系统","应用LLM-as-judge模式验证生成质量","使用标准基准确保生产质量和安全性","支持测试个别提示的正确性和格式","支持验证RAG（检索增强生成）管道质量","支持比较不同模型或提示配置"],"ja":["自動化メトリックを使用したLLMシステムの評価","LLM-as-judgeパターンを適用した生成品質の検証","標準ベンチマークを使用した生成品質の確保","個別のプロンプトの正しさとフォーマットのテストをサポート","RAG（リトリーバル・オーグメンテーション・ジェネレーション）パイプラインの品質の検証をサポート","異なるモデルまたはプロンプト構成の比較をサポート"],"ko":["자동화된 메트릭을 사용하여 LLM 시스템을 평가","LLM-as-judge 패턴을 적용하여 생성 품질을 검증","표준 벤치마크를 사용하여 생산 품질과 안전성을 보장","개별 프로ンプ트의 올바름과 형식을 테스트하는 것을 지원","RAG（검색 증강 생성）파이프라인의 품질을 검증하는 것을 지원","다른 모델 또는 프로ンプ트 구성의 비교를 지원"],"es":["Uso de métricas automatizadas para evaluar la calidad de los LLM","Implementación de estándares de calidad para garantizar la seguridad","Análisis de patrones de LLM-as-juez para evaluar la producción","Uso de benchmarks estandarizados para comparar modelos","Evaluación de hallucinaciones, sesgos y toxicidad en los resultados de LLM","Comparación de diferentes modelos y configuraciones de prompts"],"fr":["Utilisation de métriques automatisées pour évaluer la qualité des LLM","Mise en œuvre de normes de qualité pour assurer la sécurité","Analyse de modèles de LLM-as-juge pour évaluer la production","Utilisation de benchmarks standardisés pour comparer les modèles","Évaluation des hallucinations, des biais et de la toxicité dans les résultats de LLM","Comparaison de différents modèles et configurations de prompts"],"de":["Verwendung von automatisierten Metriken zur Bewertung der LLM-Qualität","Implementierung von Qualitätsstandards zur Gewährleistung der Sicherheit","Analyse von LLM-as-Richter-Mustern zur Bewertung der Produktion","Verwendung von standardisierten Benchmarks zum Vergleich von Modellen","Bewertung von Halluzinationen, Voreingenommenheit und Toxizität in LLM-Ergebnissen","Vergleich von verschiedenen Modellen und Prompt-Konfigurationen"],"pt":["Utilização de métricas automatizadas para avaliar a qualidade dos modelos","Padrões de julgamento para garantir a segurança e precisão","Avaliação de pipelines de geração de linguagem","Detecção de alucinações, viés e toxicidade nos outputs dos modelos","Comparação de diferentes modelos e configurações de prompts"],"ru":["Использование автоматизированных метрик для оценки качества моделей","Шаблоны судейства для обеспечения безопасности и точности","Оценка管道 генерации языка","Обнаружение галлюцинаций, предвзятости и токсичности в выходных данных моделей","Сравнение разных моделей и конфигураций промптов"],"ar":["استخدام معايير آلية لتقييم جودة النماذج","نماذج الحكم لتأمين السلامة والدقة","تقييم أنابيب توليد اللغة","كشف الخيالات والتحيز والسمية في مخرجات النماذج","مقارنة نماذج وتهيئة مختلفة للبرومت"]},"keywords":{"en":["how to use evaluating-llms","evaluating-llms alternative","evaluating-llms setup guide","what is evaluating-llms","evaluating-llms vs language model evaluators","evaluating-llms install","Large Language Model evaluation","LLM quality assessment","automated metrics for LLMs"],"zh":["LLM评估","自动化指标","LLM-as-judge模式","标准基准","生成质量","生产质量","安全性","AI工具","自然语言处理"],"ja":["LLM評価","自動化メトリック","LLM-as-judgeパターン","標準ベンチマーク","生成品質","生成安全性","AIエージェント","自然言語処理"],"ko":["LLM 평가","자동화된 메트릭","LLM-as-judge 패턴","표준 벤치마크","생성 품질","생산 품질","안전성","AI 도구","자연어 처리"],"es":["evaluación de LLM","AI Agents","métricas automatizadas","estándares de calidad","LLM-as-juez","benchmarks estandarizados","hallucinaciones en LLM","sesgos en LLM","toxicidad en LLM"],"fr":["évaluation de LLM","outils d''IA","métriques automatisées","normes de qualité","LLM-as-juge","benchmarks standardisés","hallucinations dans LLM","biais dans LLM","toxicité dans LLM"],"de":["LLM-Evaluierung","KI-Tools","automatisierte Metriken","Qualitätsstandards","LLM-as-Richter","standardisierte Benchmarks","Halluzinationen in LLM","Voreingenommenheit in LLM","Toxizität in LLM"],"pt":["avaliação de LLMs","desenvolvimento de IA","métricas automatizadas","padrões de julgamento","qualidade e segurança","pipelines de geração de linguagem","detecção de alucinações","comparação de modelos"],"ru":["оценка ИИ Агентов","разработка ИИ","автоматизированные метрики","шаблоны судейства","качество и безопасность","管道 генерации языка","обнаружение галлюцинаций","сравнение моделей"],"ar":["تقييم LLM","تطوير الذكاء الاصطناعي","معايير آلية","نماذج الحكم","الجودة والسلامة","أنابيب توليد اللغة","كشف الخيالات","مقارنة النماذج"]}},"owner":"ancoleman","repo":"ai-design-components","repoPath":"ancoleman/ai-design-components","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.277Z","topics":[],"category":"community","skillMd":{"name":"evaluating-llms","description":"Evaluate LLM systems using automated metrics, LLM-as-judge, and benchmarks. Use when testing prompt quality, validating RAG pipelines, measuring safety (hallucinations, bias), or comparing models for production deployment.","bodyPreview":"# LLM Evaluation\n\nEvaluate Large Language Model (LLM) systems using automated metrics, LLM-as-judge patterns, and standardized benchmarks to ensure production quality and safety.\n\n## When to Use This Skill\n\nApply this skill when:\n\n- Testing individual prompts for correctness and formatting\n- Validating RAG (Retrieval-Augmented Generation) pipeline quality\n- Measuring hallucinations, bias, or toxicity in LLM outputs\n- Comparing different models or prompt configurations (A/B testing)\n- Running ben","body":"# LLM Evaluation\n\nEvaluate Large Language Model (LLM) systems using automated metrics, LLM-as-judge patterns, and standardized benchmarks to ensure production quality and safety.\n\n## When to Use This Skill\n\nApply this skill when:\n\n- Testing individual prompts for correctness and formatting\n- Validating RAG (Retrieval-Augmented Generation) pipeline quality\n- Measuring hallucinations, bias, or toxicity in LLM outputs\n- Comparing different models or prompt configurations (A/B testing)\n- Running benchmark tests (MMLU, HumanEval) to assess model capabilities\n- Setting up production monitoring for LLM applications\n- Integrating LLM quality checks into CI/CD pipelines\n\nCommon triggers:\n- \"How do I test if my RAG system is working correctly?\"\n- \"How can I measure hallucinations in LLM outputs?\"\n- \"What metrics should I use to evaluate generation quality?\"\n- \"How do I compare GPT-4 vs Claude for my use case?\"\n- \"How do I detect bias in LLM responses?\"\n\n## Evaluation Strategy Selection\n\n### Decision Framework: Which Evaluation Approach?\n\n**By Task Type:**\n\n| Task Type | Primary Approach | Metrics | Tools |\n|-----------|------------------|---------|-------|\n| **Classification** (sentiment, intent) | Automated metrics | Accuracy, Precision, Recall, F1 | scikit-learn |\n| **Generation** (summaries, creative text) | LLM-as-judge + automated | BLEU, ROUGE, BERTScore, Quality rubric | GPT-4/Claude for judging |\n| **Question Answering** | Exact match + semantic similarity | EM, F1, Cosine similarity | Custom evaluators |\n| **RAG Systems** | RAGAS framework | Faithfulness, Answer/Context relevance | RAGAS library |\n| **Code Generation** | Unit tests + execution | Pass@K, Test pass rate | HumanEval, pytest |\n| **Multi-step Agents** | Task completion + tool accuracy | Success rate, Efficiency | Custom evaluators |\n\n**By Volume and Cost:**\n\n| Samples | Speed | Cost | Recommended Approach |\n|---------|-------|------|---------------------|\n| 1,000+ | Immediate | $0 | Automated metrics (regex, JSON validation) |\n| 100-1,000 | Minutes | $0.01-0.10 each | LLM-as-judge (GPT-4, Claude) |\n| < 100 | Hours | $1-10 each | Human evaluation (pairwise comparison) |\n\n**Layered Approach (Recommended for Production):**\n1. **Layer 1:** Automated metrics for all outputs (fast, cheap)\n2. **Layer 2:** LLM-as-judge for 10% sample (nuanced quality)\n3. **Layer 3:** Human review for 1% edge cases (validation)\n\n## Core Evaluation Patterns\n\n### Unit Evaluation (Individual Prompts)\n\nTest single prompt-response pairs for correctness.\n\n**Methods:**\n- **Exact Match:** Response exactly matches expected output\n- **Regex Matching:** Response follows expected pattern\n- **JSON Schema Validation:** Structured output validation\n- **Keyword Presence:** Required terms appear in response\n- **LLM-as-Judge:** Binary pass/fail using evaluation prompt\n\n**Example Use Cases:**\n- Email classification (spam/not spam)\n- Entity extraction (dates, names, locations)\n- JSON output formatting validation\n- Sentiment analysis (positive/negative/neutral)\n\n**Quick Start (Python):**\n```python\nimport pytest\nfrom openai import OpenAI\n\nclient = OpenAI()\n\ndef classify_sentiment(text: str) -> str:\n    response = client.chat.completions.create(\n        model=\"gpt-3.5-turbo\",\n        messages=[\n            {\"role\": \"system\", \"content\": \"Classify sentiment as positive, negative, or neutral. Return only the label.\"},\n            {\"role\": \"user\", \"content\": text}\n        ],\n        temperature=0\n    )\n    return response.choices[0].message.content.strip().lower()\n\ndef test_positive_sentiment():\n    result = classify_sentiment(\"I love this product!\")\n    assert result == \"positive\"\n```\n\nFor complete unit evaluation examples, see `examples/python/unit_evaluation.py` and `examples/typescript/unit-evaluation.ts`.\n\n### RAG (Retrieval-Augmented Generation) Evaluation\n\nEvaluate RAG systems using RAGAS framework metrics.\n\n**Critical Metrics (Priority Order):**\n\n1. **Faithfulness** (Target: > 0.8) - **MOST CRITICAL**\n   - Measures: Is the answer grounded in retrieved context?\n   - Prevents hallucinations\n   - If failing: Adjust prompt to emphasize grounding, require citations\n\n2. **Answer Relevance** (Target: > 0.7)\n   - Measures: How well does the answer address the query?\n   - If failing: Improve prompt instructions, add few-shot examples\n\n3. **Context Relevance** (Target: > 0.7)\n   - Measures: Are retrieved chunks relevant to the query?\n   - If failing: Improve retrieval (better embeddings, hybrid search)\n\n4. **Context Precision** (Target: > 0.5)\n   - Measures: Are relevant chunks ranked higher than irrelevant?\n   - If failing: Add re-ranking step to retrieval pipeline\n\n5. **Context Recall** (Target: > 0.8)\n   - Measures: Are all relevant chunks retrieved?\n   - If failing: Increase retrieval count, improve chunking strategy\n\n**Quick Start (Python with RAGAS):**\n```python\nfrom ragas import evaluate\nfrom ragas.metrics import faithfulness, answer_relevancy, context_relevancy\nfrom datasets import Dataset\n\ndata = {\n    \"question\": [\"What is the capital of France?\"],\n    \"answer\": [\"The capital of France is Paris.\"],\n    \"contexts\": [[\"Paris is the capital of France.\"]],\n    \"ground_truth\": [\"Paris\"]\n}\n\ndataset = Dataset.from_dict(data)\nresults = evaluate(dataset, metrics=[faithfulness, answer_relevancy, context_relevancy])\nprint(f\"Faithfulness: {results[''faithfulness'']:.2f}\")\n```\n\nFor comprehensive RAG evaluation patterns, see `references/rag-evaluation.md` and `examples/python/ragas_example.py`.\n\n### LLM-as-Judge Evaluation\n\nUse powerful LLMs (GPT-4, Claude Opus) to evaluate other LLM outputs.\n\n**When to Use:**\n- Generation quality assessment (summaries, creative writing)\n- Nuanced evaluation criteria (tone, clarity, helpfulness)\n- Custom rubrics for domain-specific tasks\n- Medium-volume evaluation (100-1,000 samples)\n\n**Correlation with Human Judgment:** 0.75-0.85 for well-designed rubrics\n\n**Best Practices:**\n- Use clear, specific rubrics (1-5 scale with detailed criteria)\n- Include few-shot examples in evaluation prompt\n- Average multiple evaluations to reduce variance\n- Be aware of biases (position bias, verbosity bias, self-preference)\n\n**Quick Start (Python):**\n```python\nfrom openai import OpenAI\n\nclient = OpenAI()\n\ndef evaluate_quality(prompt: str, response: str) -> tuple[int, str]:\n    \"\"\"Returns (score 1-5, reasoning)\"\"\"\n    eval_prompt = f\"\"\"\nRate the following LLM response on relevance and helpfulness.\n\nUSER PROMPT: {prompt}\nLLM RESPONSE: {response}\n\nProvide:\nScore: [1-5, where 5 is best]\nReasoning: [1-2 sentences]\n\"\"\"\n    result = client.chat.completions.create(\n        model=\"gpt-4\",\n        messages=[{\"role\": \"user\", \"content\": eval_prompt}],\n        temperature=0.3\n    )\n    content = result.choices[0].message.content\n    lines = content.strip().split(''\\n'')\n    score = int(lines[0].split('':'')[1].strip())\n    reasoning = lines[1].split('':'', 1)[1].strip()\n    return score, reasoning\n```\n\nFor detailed LLM-as-judge patterns and prompt templates, see `references/llm-as-judge.md` and `examples/python/llm_as_judge.py`.\n\n### Safety and Alignment Evaluation\n\nMeasure hallucinations, bias, and toxicity in LLM outputs.\n\n#### Hallucination Detection\n\n**Methods:**\n\n1. **Faithfulness to Context (RAG):**\n   - Use RAGAS faithfulness metric\n   - LLM checks if claims are supported by context\n   - Score: Supported claims / Total claims\n\n2. **Factual Accuracy (Closed-Book):**\n   - LLM-as-judge with access to reliable sources\n   - Fact-checking APIs (Google Fact Check)\n   - Entity-level verification (dates, names, statistics)\n\n3. **Self-Consistency:**\n   - Generate multiple responses to same question\n   - Measure agreement between responses\n   - Low consistency suggests hallucination\n\n#### Bias Evaluation\n\n**Types of Bias:**\n- Gender bias (stereotypical associations)\n- Racial/ethnic bias (discriminatory outputs)\n- Cultural bias (Western-centric assumptions)\n- Age/disability bias (ableist or ageist language)\n\n**Evaluation Methods:**\n\n1. **Stereotype Tests:**\n   - BBQ (Bias Benchmark for QA): 58,000 question-answer pairs\n   - BOLD (Bias in Open-Ended Language Generation)\n\n2. **Counterfactual Evaluation:**\n   - Generate responses with demographic swaps\n   - Example: \"Dr. Smith (he/she) recommended...\" → compare outputs\n   - Measure consistency across variations\n\n#### Toxicity Detection\n\n**Tools:**\n- **Perspective API (Google):** Toxicity, threat, insult scores\n- **Detoxify (HuggingFace):** Open-source toxicity classifier\n- **OpenAI Moderation API:** Hate, harassment, violence detection\n\nFor comprehensive safety evaluation patterns, see `references/safety-evaluation.md`.\n\n### Benchmark Testing\n\nAssess model capabilities using standardized benchmarks.\n\n**Standard Benchmarks:**\n\n| Benchmark | Coverage | Format | Difficulty | Use Case |\n|-----------|----------|--------|------------|----------|\n| **MMLU** | 57 subjects (STEM, humanities) | Multiple choice | High school - professional | General intelligence |\n| **HellaSwag** | Sentence completion | Multiple choice | Common sense | Reasoning validation |\n| **GPQA** | PhD-level science | Multiple choice | Very high (expert-level) | Frontier model testing |\n| **HumanEval** | 164 Python problems | Code generation | Medium | Code capability |\n| **MATH** | 12,500 competition problems | Math solving | High school competitions | Math reasoning |\n\n**Domain-Specific Benchmarks:**\n- **Medical:** MedQA (USMLE), PubMedQA\n- **Legal:** LegalBench\n- **Finance:** FinQA, ConvFinQA\n\n**When to Use Benchmarks:**\n- Comparing multiple models (GPT-4 vs Claude vs Llama)\n- Model selection for specific domains\n- Baseline capability assessment\n- Academic research and publication\n\n**Quick Start (lm-evaluation-harness):**\n```bash\npip install lm-eval\n\n# Evaluate GPT-4 on MMLU\nlm_eval --model openai-chat --model_args model=gpt-4 --tasks mmlu --num_fewshot 5\n```\n\nFor detailed benchmark testing patterns, see `references/benchmarks.md` and `scripts/benchmark_runner.py`.\n\n### Production Evaluation\n\nMonitor and optimize LLM quality in production environments.\n\n#### A/B Testing\n\nCompare two LLM configurations:\n- **Variant A:** GPT-4 (expensive, high quality)\n- **Variant B:** Claude Sonnet (cheaper, fast)\n\n**Metrics:**\n- User satisfaction scores (thumbs up/down)\n- Task completion rates\n- Response time and latency\n- Cost per successful interaction\n\n#### Online Evaluation\n\nReal-time quality monitoring:\n- **Response Quality:** LLM-as-judge scoring every Nth response\n- **User Feedback:** Explicit ratings, thumbs up/down\n- **Business Metrics:** Conversion rates, support ticket resolution\n- **Cost Tracking:** Tokens used, inference costs\n\n#### Human-in-the-Loop\n\nSample-based human evaluation:\n- **Random Sampling:** Evaluate 10% of responses\n- **Confidence-Based:** Evaluate low-confidence outputs\n- **Error-Triggered:** Flag suspicious responses for review\n\nFor production evaluation patterns and monitoring strategies, see `references/production-evaluation.md`.\n\n## Classification Task Evaluation\n\nFor tasks with discrete outputs (sentiment, intent, category).\n\n**Metrics:**\n- **Accuracy:** Correct predictions / Total predictions\n- **Precision:** True positives / (True positives + False positives)\n- **Recall:** True positives / (True positives + False negatives)\n- **F1 Score:** Harmonic mean of precision and recall\n- **Confusion Matrix:** Detailed breakdown of prediction errors\n\n**Quick Start (Python):**\n```python\nfrom sklearn.metrics import accuracy_score, precision_recall_fscore_support\n\ny_true = [\"positive\", \"negative\", \"neutral\", \"positive\", \"negative\"]\ny_pred = [\"positive\", \"negative\", \"neutral\", \"neutral\", \"negative\"]\n\naccuracy = accuracy_score(y_true, y_pred)\nprecision, recall, f1, _ = precision_recall_fscore_support(y_true, y_pred, average=''weighted'')\n\nprint(f\"Accuracy: {accuracy:.2f}\")\nprint(f\"Precision: {precision:.2f}\")\nprint(f\"Recall: {recall:.2f}\")\nprint(f\"F1 Score: {f1:.2f}\")\n```\n\nFor complete classification evaluation examples, see `examples/python/classification_metrics.py`.\n\n## Generation Task Evaluation\n\nFor open-ended text generation (summaries, creative writing, responses).\n\n**Automated Metrics (Use with Caution):**\n- **BLEU:** N-gram overlap with reference text (0-1 score)\n- **ROUGE:** Recall-oriented overlap (ROUGE-1, ROUGE-L)\n- **METEOR:** Semantic similarity with stemming\n- **BERTScore:** Contextual embedding similarity (0-1 score)\n\n**Limitation:** Automated metrics correlate weakly with human judgment for creative/subjective generation.\n\n**Recommended Approach:**\n1. **Automated metrics:** Fast feedback for objective aspects (length, format)\n2. **LLM-as-judge:** Nuanced quality assessment (relevance, coherence, helpfulness)\n3. **Human evaluation:** Final validation for subjective criteria (preference, creativity)\n\nFor detailed generation evaluation patterns, see `references/evaluation-types.md`.\n\n## Quick Reference Tables\n\n### Evaluation Framework Selection\n\n| If Task Is... | Use This Framework | Primary Metric |\n|---------------|-------------------|----------------|\n| RAG system | RAGAS | Faithfulness > 0.8 |\n| Classification | scikit-learn metrics | Accuracy, F1 |\n| Generation quality | LLM-as-judge | Quality rubric (1-5) |\n| Code generation | HumanEval | Pass@1, Test pass rate |\n| Model comparison | Benchmark testing | MMLU, HellaSwag scores |\n| Safety validation | Hallucination detection | Faithfulness, Fact-check |\n| Production monitoring | Online evaluation | User feedback, Business KPIs |\n\n### Python Library Recommendations\n\n| Library | Use Case | Installation |\n|---------|----------|--------------|\n| **RAGAS** | RAG evaluation | `pip install ragas` |\n| **DeepEval** | General LLM evaluation, pytest integration | `pip install deepeval` |\n| **LangSmith** | Production monitoring, A/B testing | `pip install langsmith` |\n| **lm-eval** | Benchmark testing (MMLU, HumanEval) | `pip install lm-eval` |\n| **scikit-learn** | Classification metrics | `pip install scikit-learn` |\n\n### Safety Evaluation Priority Matrix\n\n| Application | Hallucination Risk | Bias Risk | Toxicity Risk | Evaluation Priority |\n|-------------|-------------------|-----------|---------------|---------------------|\n| Customer Support | High | Medium | High | 1. Faithfulness, 2. Toxicity, 3. Bias |\n| Medical Diagnosis | Critical | High | Low | 1. Factual Accuracy, 2. Hallucination, 3. Bias |\n| Creative Writing | Low | Medium | Medium | 1. Quality/Fluency, 2. Content Policy |\n| Code Generation | Medium | Low | Low | 1. Functional Correctness, 2. Security |\n| Content Moderation | Low | Critical | Critical | 1. Bias, 2. False Positives/Negatives |\n\n## Detailed References\n\nFor comprehensive documentation on specific topics:\n\n- **Evaluation types (classification, generation, QA, code):** `references/evaluation-types.md`\n- **RAG evaluation deep dive (RAGAS framework):** `references/rag-evaluation.md`\n- **Safety evaluation (hallucination, bias, toxicity):** `references/safety-evaluation.md`\n- **Benchmark testing (MMLU, HumanEval, domain benchmarks):** `references/benchmarks.md`\n- **LLM-as-judge best practices and prompts:** `references/llm-as-judge.md`\n- **Production evaluation (A/B testing, monitoring):** `references/production-evaluation.md`\n- **All metrics definitions and formulas:** `references/metrics-reference.md`\n\n## Working Examples\n\n**Python Examples:**\n- `examples/python/unit_evaluation.py` - Basic prompt testing with pytest\n- `examples/python/ragas_example.py` - RAGAS RAG evaluation\n- `examples/python/deepeval_example.py` - DeepEval framework usage\n- `examples/python/llm_as_judge.py` - GPT-4 as evaluator\n- `examples/python/classification_metrics.py` - Accuracy, precision, recall\n- `examples/python/benchmark_testing.py` - HumanEval example\n\n**TypeScript Examples:**\n- `examples/typescript/unit-evaluation.ts` - Vitest + OpenAI\n- `examples/typescript/llm-as-judge.ts` - GPT-4 evaluation\n- `examples/typescript/langsmith-integration.ts` - Production monitoring\n\n## Executable Scripts\n\nRun evaluations without loading code into context (token-free):\n\n- `scripts/run_ragas_eval.py` - Run RAGAS evaluation on dataset\n- `scripts/compare_models.py` - A/B test two models\n- `scripts/benchmark_runner.py` - Run MMLU/HumanEval benchmarks\n- `scripts/hallucination_checker.py` - Detect hallucinations in outputs\n\n**Example usage:**\n```bash\n# Run RAGAS evaluation on custom dataset\npython scripts/run_ragas_eval.py --dataset data/qa_dataset.json --output results.json\n\n# Compare GPT-4 vs Claude on benchmark\npython scripts/compare_models.py --model-a gpt-4 --model-b claude-3-opus --tasks mmlu,humaneval\n```\n\n## Integration with Other Skills\n\n**Related Skills:**\n- **`building-ai-chat`:** Evaluate AI chat applications (this skill tests what that skill builds)\n- **`prompt-engineering`:** Test prompt quality and effectiveness\n- **`testing-strategies`:** Apply testing pyramid to LLM evaluation (unit → integration → E2E)\n- **`observability`:** Production monitoring and alerting for LLM quality\n- **`building-ci-pipelines`:** Integrate LLM evaluation into CI/CD\n\n**Workflow Integration:**\n1. Write prompt (use `prompt-engineering` skill)\n2. Unit test prompt (use `llm-evaluation` skill)\n3. Build AI feature (use `building-ai-chat` skill)\n4. Integration test RAG pipeline (use `llm-evaluation` skill)\n5. Deploy to production (use `deploying-applications` skill)\n6. Monitor quality (use `llm-evaluation` + `observability` skills)\n\n## Common Pitfalls\n\n**1. Over-reliance on Automated Metrics for Generation**\n- BLEU/ROUGE correlate weakly with human judgment for creative text\n- Solution: Layer LLM-as-judge or human evaluation\n\n**2. Ignoring Faithfulness in RAG Systems**\n- Hallucinations are the #1 RAG failure mode\n- Solution: Prioritize faithfulness metric (target > 0.8)\n\n**3. No Production Monitoring**\n- Models can degrade over time, prompts can break with updates\n- Solution: Set up continuous evaluation (LangSmith, custom monitoring)\n\n**4. Biased LLM-as-Judge Evaluation**\n- Evaluator LLMs have biases (position bias, verbosity bias)\n- Solution: Average multiple evaluations, use diverse evaluation prompts\n\n**5. Insufficient Benchmark Coverage**\n- Single benchmark doesn''t capture full model capability\n- Solution: Use 3-5 benchmarks across different domains\n\n**6. Missing Safety Evaluation**\n- Production LLMs can generate harmful content\n- Solution: Add toxicity, bias, and hallucination checks to evaluation pipeline\n"},"lastSynced":"2026-03-08T02:00:44.041Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude, AutoGPT, and LangChain that require rigorous Large Language Model evaluation and testing for production quality and safety","zh":"适合于Claude、AutoGPT和LangChain等需要严格的大型语言模型评估和测试以达到生产质量和安全性的AI代理","ja":"Claude、AutoGPT、LangChainなどの、大規模な言語モデルを徹底的に評価およびテストし、生産品質および安全性を確保する必要があるAIエージェントに適している","ko":"Claude, AutoGPT, LangChain 등의 엄격한 대규모 언어 모델 평가 및 테스트가 생산품질 및 안전성을 위해서 필요한 AI 에이전트에게 적합","es":"Ideal para agentes de IA como Claude, AutoGPT y LangChain que requieren una evaluación y prueba rigurosa del modelo de lenguaje grande para la calidad y seguridad de producción","fr":"Idéal pour les agents IA comme Claude, AutoGPT et LangChain qui nécessitent une évaluation et des tests rigoureux du modèle de langage grand pour la qualité et la sécurité de production","de":"Ideal für KI-Agents wie Claude, AutoGPT und LangChain, die eine strenge Bewertung und Überprüfung des großen Sprachmodells für die Produktionsqualität und -sicherheit erfordern","pt":"Ideal para Agentes de IA como Claude, AutoGPT e LangChain que exigem uma avaliação e teste rigorosos de grandes modelos de linguagem para garantir a qualidade e segurança de produção","ru":"Идеально подходит для агентов ИИ, таких как Claude, AutoGPT и LangChain, которые требуют строгой оценки и тестирования больших языковых моделей для обеспечения качества и безопасности производства","ar":"مثالي للوكلاء الذكاء الاصطناعي مثل Claude و AutoGPT و LangChain التي تتطلب تقييمًا وتجربة صارمة للنماذج اللغوية الكبيرة لضمان جودة وأمان الإنتاج"},"recommendation":{"en":"Empowers agents to assess LLM systems using automated metrics, LLM-as-judge patterns, and standardized benchmarks, ensuring accurate measurement of hallucinations, bias, or toxicity in LLM outputs via protocols like Retrieval-Augmented Generation (RAG) pipeline quality validation","zh":"赋予代理评估LLM系统的能力，使用自动化指标、LLM作为法官的模式和标准化基准，确保通过像检索增强生成（RAG）管道质量验证这样的协议准确测量LLM输出中的幻觉、偏见或有毒性","ja":"エージェントがLLMシステムを評価する能力を付与し、自動化された指標、LLMをジャッジとして使用するパターン、および標準化されたベンチマークを使用して、Retrieval-Augmented Generation（RAG）パイプラインの品質検証などのプロトコルを介して、LLMの出力におけるホールシネーション、バイアス、または有毒性を正確に測定することを保証する","ko":"에이전트가 LLM 시스템을 평가할 수 있는 능력을 부여하며, 자동화된 지표, LLM을 판단자로 사용하는 패턴 및 표준화된 벤치마크를 사용하여,检索增强生成(RAG) 파이프라인 품질 검증과 같은 프로토콜을 통해 LLM 출력에서 환각, 편향 또는 유독성의 정확한 측정을 보장","es":"Habilita a los agentes a evaluar sistemas LLM utilizando métricas automatizadas, patrones de LLM como juez y benchmarks estandarizados, garantizando la medición precisa de alucinaciones, sesgo o toxicidad en las salidas de LLM a través de protocolos como la validación de calidad de la canalización de generación aumentada con recuperación (RAG)","fr":"Permet aux agents d''évaluer les systèmes LLM en utilisant des métriques automatisées, des modèles de LLM en tant que juge et des benchmarks standardisés, garantissant ainsi une mesure précise des hallucinations, des biais ou de la toxicité dans les sorties LLM via des protocoles tels que la validation de la qualité du pipeline de génération augmentée avec récupération (RAG)","de":"Ermöglicht es den Agenten, LLM-Systeme unter Verwendung automatisierter Metriken, LLM-als-Richter-Muster und standardisierter Benchmarks zu bewerten, wodurch eine genaue Messung von Halluzinationen, Voreingenommenheit oder Toxizität in LLM-Ausgaben über Protokolle wie die Qualitätssicherung der Retrieval-Augmented-Generation-(RAG)-Pipeline gewährleistet wird","pt":"Habilita os agentes a avaliar sistemas LLM usando métricas automatizadas, padrões LLM-juiz e benchmarks padronizados, garantindo medição precisa de alucinações, viés ou toxicidade nos resultados LLM via protocolos como validação de qualidade do pipeline RAG","ru":"Позволяет агентам оценивать системы LLM с помощью автоматизированных метрик, шаблонов LLM-судьи и стандартизированных тестов, обеспечивая точное измерение галлюцинаций, предвзятости или токсичности в выходных данных LLM через протоколы, такие как валидация качества конвейера RAG","ar":"تمكين الوكلاء من تقييم أنظمة LLM باستخدام معايير تلقائية ونمط LLM-القاضي والمقاييس الموحدة، لضمان القياس الدقيق للهلوسة أو الانحياز أو السُمية في مخرجات LLM من خلال بروتوكولات مثل التحقق من جودة خط أنابيب RAG"},"useCases":{"en":["Testing individual prompts for correctness and formatting","Validating RAG pipeline quality for optimal performance","Measuring hallucinations, bias, or toxicity in LLM outputs for safety","Comparing different models or prompt configurations through A/B testing"],"zh":["测试单个提示的正确性和格式","验证RAG管道质量以实现最佳性能","测量LLM输出中的幻觉、偏见或有毒性以确保安全","通过A/B测试比较不同的模型或提示配置"],"ja":["個々のプロンプトの正確性と書式をテストする","RAGパイプラインの品質を検証して最適なパフォーマンスを実現する","LLMの出力におけるホールシネーション、バイアス、または有毒性を測定して安全性を確保する","A/Bテストを通じて異なるモデルまたはプロンプト構成を比較する"],"ko":["개별 프롬프트의 정확성과 형식을 테스트","RAG 파이프라인의 품질을 검증하여 최적의 성능을 달성","LLM 출력에서의 환각, 편향 또는 유독성을 측정하여 안전을 확보","A/B 테스트를 통해 다른 모델이나 프롬프트 구성 비교"],"es":["Prueba de instrucciones individuales para la corrección y el formato","Validación de la calidad de la canalización RAG para un rendimiento óptimo","Medición de alucinaciones, sesgo o toxicidad en las salidas de LLM para la seguridad","Comparación de diferentes modelos o configuraciones de instrucciones a través de pruebas A/B"],"fr":["Test de prompts individuels pour la correction et le format","Validation de la qualité du pipeline RAG pour des performances optimales","Mesure des hallucinations, des biais ou de la toxicité dans les sorties LLM pour la sécurité","Comparaison de différents modèles ou configurations de prompts via des tests A/B"],"de":["Testen einzelner Anweisungen auf Korrektheit und Format","Validierung der Qualität der RAG-Pipeline für optimale Leistung","Messung von Halluzinationen, Voreingenommenheit oder Toxizität in LLM-Ausgaben für die Sicherheit","Vergleich verschiedener Modelle oder Prompt-Konfigurationen durch A/B-Testing"],"pt":["Testar prompts individuais para correção e formatação","Validar a qualidade do pipeline RAG para desempenho ótimo","Medir alucinações, viés ou toxicidade nos resultados LLM para segurança","Comparar diferentes modelos ou configurações de prompts por meio de testes A/B"],"ru":["Тестировать отдельные промпты на правильность и форматирование","Проверять качество конвейера RAG для оптимальной производительности","Измерять галлюцинации, предвзятость или токсичность в выходных данных LLM для безопасности","Сравнивать разные модели или конфигурации промптов с помощью тестов A/B"],"ar":["اختبار الدفعات الفردية للصحة والتنسيق","التحقق من جودة خط أنابيب RAG لأداء مثالي","قياس الهلوسة أو الانحياز أو السُمية في مخرجات LLM للسلامة","مقارنة نماذج أو تكوينات مختلفة للدفعات من خلال اختبارات A/B"]},"limitations":{"en":["Requires access to Large Language Model systems","Standardized benchmarks and automated metrics must be predefined","Limited to evaluating LLM systems, not other types of AI models"],"zh":["需要访问大型语言模型系统","标准化基准和自动化指标必须预定义","仅限于评估LLM系统，不适用于其他类型的AI模型"],"ja":["大規模な言語モデルシステムへのアクセスが必要","標準化されたベンチマークおよび自動化された指標は事前に定義する必要がある","LLMシステムの評価に限定され、他のタイプのAIモデルには対象外"],"ko":["대규모 언어 모델 시스템에 대한 액세스가 필요","표준화된 벤치마크 및 자동화된 지표는事前に 정의되어야 함","LLM 시스템의 평가에만 한정되어 있으며, 다른 유형의 AI 모델에는 적용되지 않음"],"es":["Requiere acceso a sistemas de modelo de lenguaje grande","Las métricas automatizadas y los benchmarks estandarizados deben estar predefinidos","Limitado a la evaluación de sistemas LLM, no otros tipos de modelos de IA"],"fr":["Nécessite un accès aux systèmes de modèle de langage grand","Les métriques automatisées et les benchmarks standardisés doivent être préétablis","Limité à l''évaluation des systèmes LLM, et non d''autres types de modèles d''IA"],"de":["Erfordert Zugriff auf große Sprachmodell-Systeme","Automatisierte Metriken und standardisierte Benchmarks müssen vordefiniert sein","Begrenzt auf die Bewertung von LLM-Systemen, nicht auf andere Arten von KI-Modellen"],"pt":["Exige acesso a sistemas de grandes modelos de linguagem","As benchmarks padronizadas e as métricas automatizadas devem ser pré-definidas","Limitado à avaliação de sistemas LLM, não a outros tipos de modelos de IA"],"ru":["Требует доступа к системам больших языковых моделей","Стандартизированные тесты и автоматизированные метрики должны быть предварительно определены","Ограничен оценкой систем LLM, а не других типов моделей ИИ"],"ar":["يتطلب الوصول إلى أنظمة النماذج اللغوية الكبيرة","يجب أن تكون المقاييس الموحدة والمعايير التلقائية محددة مسبقًا","محدود بالتقييم لأنظمة LLM، وليس لأنواع أخرى من نماذج الذكاء الاصطناعي"]},"version":4},"contentHash":"55f8ebd7adde6b6befaa8f89b1d9e95a6790d3f026a448dfe03ab58caea7522a","qualityScore":60}');
