INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ancoleman/ai-design-components/evaluating-llms', 'evaluating-llms', 'ancoleman', 'ai-design-components', 'community', 'evaluating-llms ancoleman ai-design-components community The evaluating-llms skill enables developers to assess Large Language Model systems using automated metrics and standardized benchmarks, ensuring production quality and safety for AI-assisted development with Claude. 评估大型语言模型（LLM）系统，使用自动化指标、LLM-as-judge模式和标准基准来确保生产质量和安全性 LLM評価では、自動化メトリック、LLM-as-judgeパターン、標準ベンチマークを使用して、生成の品質と安全性を確保します LLM 평가를 통해 자동화된 메트릭, LLM-as-judge 패턴, 표준 벤치마크를 사용하여 생산 품질과 안전성을 보장합니다 La evaluación de LLM implica el uso de métricas automatizadas y estándares de calidad para garantizar la producción y seguridad de AI Agents L''évaluation de LLM consiste à utiliser des métriques automatisées et des normes de qualité pour assurer la production et la sécurité des outils d''IA Die LLM-Evaluierung beinhaltet die Verwendung von automatisierten Metriken und Qualitätsstandards, um die Produktion und Sicherheit von KI-Tools zu gewährleisten Avalie modelos de linguagem grande com eficácia, utilizando métricas automatizadas e padrões de julgamento para garantir a qualidade e segurança Оцените модели крупномасштабного языка эффективно, используя автоматизированные метрики и шаблоны судейства для обеспечения качества и безопасности قيم نماذج اللغة الكبيرة بفعالية، باستخدام معايير آلية ونماذج الحكم لتأمين الجودة والسلامة how to use evaluating-llms evaluating-llms alternative evaluating-llms setup guide what is evaluating-llms evaluating-llms vs language model evaluators evaluating-llms install Large Language Model evaluation LLM quality assessment automated metrics for LLMs LLM评估 自动化指标 LLM-as-judge模式 标准基准 生成质量 生产质量 安全性 AI工具 自然语言处理 Evaluate LLM systems using automated metrics Apply LLM-as-judge patterns for quality assessment Utilize standardized benchmarks for production quality Test individual prompts for correctness and formatting Validate RAG pipeline quality and measure hallucinations, bias, or toxicity in LLM outputs Evaluating-llms is a skill that evaluates Large Language Model systems using automated metrics, LLM-as-judge patterns, and standardized benchmarks');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('evolv3ai/claude-skills-archive/project-planning', 'community', 'evolv3ai', 'claude-skills-archive', 'evolv3ai/claude-skills-archive', 'project-planning', 0, 0, 60, '2026-03-08T01:57:15.279Z', '2026-03-08T02:00:48.238Z', '08d84649dc9fe7ed788c22fc563a00ae2f151d3a7b1476cad373d75f2d2d0b6b', '{"id":"evolv3ai/claude-skills-archive/project-planning","name":"project-planning","description":{"en":"The project-planning skill generates context-safe phases with comprehensive planning documentation for web application projects, benefiting developers and project managers. It integrates with Claude Code CLI, Cloudflare, React, and Tailwind v4.","zh":"项目规划技能是Claude Code CLI的生产就绪技能，支持Cloudflare、React、Tailwind v4和AI集成，生成上下文安全的项目阶段和综合规划文档","ja":"プロジェクト計画スキルは、Cloudflare、React、Tailwind v4、AIエージェントとの統合をサポートするClaude Code CLIの生産就緒スキルです。コンテキストセーフなプロジェクト段階と包括的な計画文書を生成します","ko":"프로젝트 계획 스킬은 Cloudflare, React, Tailwind v4, AI 도구와의 통합을 지원하는 Claude Code CLI의 생산 준비 스킬입니다. 컨텍스트 안전 프로젝트 단계와 포괄적인 계획 문서를 생성합니다","es":"La habilidad de planificación de proyectos es una herramienta especializada para proyectos de aplicaciones web que genera fases de planificación seguras y documentación completa","fr":"La compétence de planification de projets est un outil spécialisé pour les projets d''applications web qui génère des phases de planification sécurisées et une documentation complète","de":"Die Fähigkeit zur Projektplanung ist ein spezialisiertes Tool für Webanwendungsprojekte, das sichere Planungsphasen und umfassende Dokumentation generiert","pt":"O skill de planejamento de projetos é uma ferramenta especializada para criar documentação de planejamento personalizada para aplicações web com Claude Code CLI, React, Tailwind v4 e integrações de IA","ru":"Навык планирования проектов - это специализированный инструмент для создания индивидуальной до