INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mshraditya/SkillsForAgentRegistry/evaluation', 'evaluation', 'mshraditya', 'SkillsForAgentRegistry', 'community', 'evaluation mshraditya SkillsForAgentRegistry community The evaluation skill enables developers to build frameworks for agent systems, accounting for dynamic decisions and non-deterministic behavior. This skill benefits developers working with AI agents. 评估AI系统需要特殊的方法，考虑动态决策和非确定性运行。该技能提供评估框架的构建指南 AIエージェントシステムの評価には、動的決定と非決定性実行を考慮した特殊な方法が必要です。このスキルでは、評価フレームワークの構築ガイドを提供します AI 에이전트 시스템의 평가에는 동적 결정과 비결정적 실행을 고려한 특별한 방법이 필요합니다. 이 스킬은 평가 프레임워크 구축 가이드를 제공합니다 La evaluación de sistemas de Agentes de IA requiere enfoques diferentes a los de software tradicional. Conoce las mejores prácticas. L''évaluation des systèmes d''Agents d''IA nécessite des approches différentes de celles du logiciel traditionnel. Découvrez les meilleures pratiques. Die Bewertung von KI-Agents-Systemen erfordert andere Ansätze als die traditionelle Software. Erfahren Sie die besten Praktiken. A avaliação de sistemas de agentes requer abordagens específicas devido às suas características dinâmicas e não determinísticas. Оценка ИИ Агентов требует特殊ных подходов из-за их динамических и неопределенных характеристик. ت đòi التقييم لأنظمة الوكلاء الذكية نهجًا خاصًا بسببخصائصها الديناميكية واللامعينانية. evaluation for AI agents how to build evaluation frameworks evaluation methods for agent systems evaluation vs assessment evaluation setup guide evaluation install for AI agents AI评估框架 动态决策评估 非确定性运行评估 AI系统评估 评估方法 评估框架构建 AI工具 AIエージェント Builds evaluation frameworks for agent systems Accounts for dynamic decision-making and non-deterministic behavior Supports effective evaluation of agent systems with multiple possible answers Enables developers to create customized evaluation methods for AI agents Facilitates the assessment of agent systems with complex decision-making processes Evaluation is a process for assessing agent systems, requiring approaches that account for dynamic decision-making and non-deterministic behavior.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Timmy6942025/bob-workspace/web-perf', 'community', 'Timmy6942025', 'bob-workspace', 'Timmy6942025/bob-workspace', 'web-perf', 0, 0, 60, '2026-03-08T01:57:15.280Z', '2026-03-08T02:00:50.846Z', 'dbb0e6ab3e3565cf49de6b2c3bcd62339aafebb099514ec3c86771a096cd920b', '{"id":"Timmy6942025/bob-workspace/web-perf","name":"web-perf","description":{"en":"The web-perf skill audits web page performance using Chrome DevTools MCP tools, focusing on Core Web Vitals and network optimization for developers.","zh":"Web Perf AIエージェント是一种用于优化网页性能的工具，包括Core Web Vitals、网络优化和无障碍功能","ja":"Web Perf AIエージェントは、Core Web Vitals、ネットワーク最適化、ハイレベルアクセシビリティを最適化するためのツール","ko":"Web Perf AI 에이전트는 웹 페이지 성능을 최적화하기 위한 도구로, Core Web Vitals, 네트워크 최적화 및 고급 접근성 기능을 개선","es":"web-perf es un skill que audita el rendimiento de las páginas web utilizando Chrome DevTools y MCP, enfocándose en Core Web Vitals y optimización de la red.","fr":"web-perf est une compétence qui audite les performances des pages web en utilisant Chrome DevTools et MCP, en se concentrant sur les Core Web Vitals et l''optimisation du réseau.","de":"web-perf ist ein Skill, der die Leistung von Webseiten mit Chrome DevTools und MCP audiert, wobei der Fokus auf Core Web Vitals und Netzwerktopimierung liegt.","pt":"O web-perf é uma habilidade que permite auditorias de desempenho da web usando Chrome DevTools e MCP tools, focando em Core Web Vitals e otimização de rede.","ru":"Web-perf - это навык, который позволяет проводить аудит производительности веб-страниц с помощью Chrome DevTools и MCP инструментов, с фокусом на Core Web Vitals и оптимизацией сети.","ar":"أداة web-perf هي مهارة تسمح بفحص أداء الويب باستخدام Chrome DevTools وأدوات MCP، تركز على Core Web Vitals وتحسين الشبكة."},"seo":{"title":{"en":"web-perf: Web Performance Audit Setup Guide | AI Agent Skill","zh":"Web Perf Setup Guide - AIエージェント优化工具","ja":"Web Perf Setup Guide - AIエージェントによるウェブパフォーマンス最適化","ko":"Web Perf Setup Guide - AI 에이전트를 통한 웹 성능 최적화","es":"Guía de configuración de web-perf para optimización de re...","fr":"Guide de configuration de web-perf pour l''optimisation de...","de":"Konfigurationsleitfaden für web-perf zur Optimierung der ...","pt":"Guia de Configuração web-perf: Otimização de Desempenho d...","ru":"ИИ Агенты web-perf: Настройка производительности веб-страниц","ar":"إعداد أداة web-perf: تحسين أداء الويب"},"description":{"en":"Unlock faster webpage loads with web-perf! Learn how to configure Chrome DevTools MCP tools and optimize Core Web Vitals - get started now!","zh":"使用Web Perf AIエージェント优化您的网页性能，包括Core Web Vitals、网络优化和无障碍功能","ja":"Web Perf AIエージェントを使用して、Core Web Vitals、ネットワーク最適化、ハイレベルアクセシビリティを最適化","ko":"Web Perf AI 에이전트를 사용하여 웹 페이지 성능을 최적화하여 Core Web Vitals, 네트워크 최적화 및 고급 접근성 기능을 개선","es":"Aprende a configurar web-perf para mejorar el rendimiento de tus páginas web con Chrome DevTools y MCP","fr":"Découvrez comment configurer web-perf pour améliorer les performances de vos pages web avec Chrome DevTools et MCP","de":"Erfahren Sie, wie Sie web-perf konfigurieren, um die Leistung Ihrer Webseiten mit Chrome DevTools und MCP zu verbessern","pt":"Aprenda a configurar o web-perf para auditorias de desempenho da web com Chrome DevTools e MCP tools","ru":"Узнайте, как настроить web-perf для аудита производительности веб-страниц с помощью Chrome DevTools и MCP инструментов","ar":"تعرف على كيفية إعداد أداة web-perf لاختبار أداء الويب باستخدام Chrome DevTools وأدوات MCP"},"definition":{"en":"web-perf is a skill that audits web page performance using Chrome DevTools MCP tools, analyzing Core Web Vitals and accessibility gaps.","zh":"Web Perf AIエージェント是一种用于分析和优化网页性能的工具","ja":"Web Perf AIエージェントは、ウェブページのパフォーマンスを分析および最適化するためのツール","ko":"Web Perf AI 에이전트는 웹 페이지 성능을 분석하고 최적화하기 위한 도구","es":"web-perf es una herramienta de auditoría de rendimiento web que utiliza Chrome DevTools y MCP para identificar problemas de rendimiento y accesibilidad","fr":"web-perf est un outil d''audit de performances web qui utilise Chrome DevTools et MCP pour identifier les problèmes de performances et d''accessibilité","de":"web-perf ist ein Tool zur Leistungsüberprüfung von Webseiten, das Chrome DevTools und MCP verwendet, um Leistungs- und Zugänglichkeitsprobleme zu identifizieren","pt":"O que é web-perf? É uma habilidade de auditoria de desempenho da web que utiliza Chrome DevTools e MCP tools.","ru":"Что такое web-perf? Это навык аудита производительности веб-страниц, использующий Chrome DevTools и MCP инструменты.","ar":"ما هي أداة web-perf? هي مهارة لفحص أداء الويب باستخدام Chrome DevTools وأدوات MCP."},"features":{"en":["Runs performance audits using Chrome DevTools MCP tools","Analyzes Core Web Vitals for optimization opportunities","Identifies high-level accessibility gaps","Verifies MCP Tools availability using navigate_page or performance_start_trace commands","Configures chrome-devtools MCP server for local use","Utilizes JSON configuration files for setup"],"zh":["使用Chrome DevTools MCP工具进行网页性能分析","优化Core Web Vitals，包括LCP、CLS和FID","网络优化，包括资源加载和请求优化","高级无障碍功能，包括WCAG指南支持"],"ja":["Chrome DevTools MCPツールを使用したウェブページのパフォーマンス分析","Core Web Vitalsの最適化、LCP、CLS、およびFIDを含む","ネットワーク最適化、リソースの読み込みとリクエストの最適化を含む","ハイレベルアクセシビリティ機能、WCAGガイドラインのサポートを含む"],"ko":["Chrome DevTools MCP 툴을 사용한 웹 페이지 성능 분석","Core Web Vitals 최적화, LCP, CLS 및 FID 포함","네트워크 최적화, 리소스 로딩 및 요청 최적화 포함","고급 접근성 기능, WCAG 가이드라인 지원 포함"],"es":["Análisis de Core Web Vitals","Optimización de la red con Chrome DevTools","Identificación de brechas de accesibilidad","Uso de MCP para auditar el rendimiento","Configuración de servidores locales con npx","Integración con herramientas de desarrollo como CLI"],"fr":["Analyse des Core Web Vitals","Optimisation du réseau avec Chrome DevTools","Identification des lacunes d''accessibilité","Utilisation de MCP pour auditer les performances","Configuration de serveurs locaux avec npx","Intégration avec des outils de développement comme CLI"],"de":["Analyse von Core Web Vitals","Optimierung des Netzwerks mit Chrome DevTools","Identifizierung von Zugänglichkeitslücken","Verwendung von MCP zur Leistungsüberprüfung","Konfiguration von lokalen Servern mit npx","Integration mit Entwicklungstools wie CLI"],"pt":["Auditoria de desempenho da web com Chrome DevTools","Foco em Core Web Vitals","Otimização de rede","Detecção de gaps de acessibilidade","Utilização de MCP tools"],"ru":["Аудит производительности веб-страниц с помощью Chrome DevTools","Фокус на Core Web Vitals","Оптимизация сети","Обнаружение пробелов в доступности","Использование MCP инструментов"],"ar":["فحص أداء الويب باستخدام Chrome DevTools","التركيز على Core Web Vitals","تحسين الشبكة","كشف الفجوات في سهولة الوصول","استخدام أدوات MCP"]},"keywords":{"en":["how to use web-perf","web-perf setup guide","web performance audit tools","Chrome DevTools MCP tutorial","Core Web Vitals optimization","web-perf vs Lighthouse","web-perf install","web performance optimization techniques","web-perf alternative"],"zh":["Web Perf AIエージェント","网页性能优化","Core Web Vitals","网络优化","无障碍功能","Chrome DevTools MCP","AIエージェント工具"],"ja":["Web Perf AIエージェント","ウェブページのパフォーマンス最適化","Core Web Vitals","ネットワーク最適化","ハイレベルアクセシビリティ","Chrome DevTools MCP","AIエージェントツール"],"ko":["Web Perf AI 에이전트","웹 페이지 성능 최적화","Core Web Vitals","네트워크 최적화","고급 접근성","Chrome DevTools MCP","AI 에이전트 도구"],"es":["web-perf","optimización de rendimiento web","Chrome DevTools","MCP","Core Web Vitals","accesibilidad web","desarrollo web","herramientas de desarrollo","CLI","npx"],"fr":["web-perf","optimisation des performances web","Chrome DevTools","MCP","Core Web Vitals","accessibilité web","développement web","outils de développement","CLI","npx"],"de":["web-perf","Optimierung der Webleistung","Chrome DevTools","MCP","Core Web Vitals","Zugänglichkeit von Webseiten","Webentwicklung","Entwicklungstools","CLI","npx"],"pt":["web-perf","auditoria de desempenho da web","Chrome DevTools","MCP tools","Core Web Vitals","otimização de rede","acessibilidade"],"ru":["web-perf","ИИ Агенты","аудит производительности веб-страниц","Chrome DevTools","MCP инструменты","Core Web Vitals","оптимизация сети","доступность"],"ar":["web-perf","أداة web-perf","فحص أداء الويب","Chrome DevTools","أدوات MCP","Core Web Vitals","تحسين الشبكة","سهولة الوصول"]}},"owner":"Timmy6942025","repo":"bob-workspace","repoPath":"Timmy6942025/bob-workspace","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.280Z","topics":[],"category":"community","skillMd":{"name":"web-perf","description":"Analyzes web performance using Chrome DevTools MCP. Measures Core Web Vitals (FCP, LCP, TBT, CLS, Speed Index), identifies render-blocking resources, network dependency chains, layout shifts, caching issues, and accessibility gaps. Use when asked to audit, profile, debug, or optimize page load performance, Lighthouse scores, or site speed.","bodyPreview":"# Web Performance Audit\n\nAudit web page performance using Chrome DevTools MCP tools. This skill focuses on Core Web Vitals, network optimization, and high-level accessibility gaps.\n\n## FIRST: Verify MCP Tools Available\n\n**Run this before starting.** Try calling `navigate_page` or `performance_start_trace`. If unavailable, STOP—the chrome-devtools MCP server isn''t configured.\n\nAsk the user to add this to their MCP config:\n\n```json\n\"chrome-devtools\": {\n  \"type\": \"local\",\n  \"command\": [\"npx\", \"-y\",","body":"# Web Performance Audit\n\nAudit web page performance using Chrome DevTools MCP tools. This skill focuses on Core Web Vitals, network optimization, and high-level accessibility gaps.\n\n## FIRST: Verify MCP Tools Available\n\n**Run this before starting.** Try calling `navigate_page` or `performance_start_trace`. If unavailable, STOP—the chrome-devtools MCP server isn''t configured.\n\nAsk the user to add this to their MCP config:\n\n```json\n\"chrome-devtools\": {\n  \"type\": \"local\",\n  \"command\": [\"npx\", \"-y\", \"chrome-devtools-mcp@latest\"]\n}\n```\n\n## Key Guidelines\n\n- **Be assertive**: Verify claims by checking network requests, DOM, or codebase—then state findings definitively.\n- **Verify before recommending**: Confirm something is unused before suggesting removal.\n- **Quantify impact**: Use estimated savings from insights. Don''t prioritize changes with 0ms impact.\n- **Skip non-issues**: If render-blocking resources have 0ms estimated impact, note but don''t recommend action.\n- **Be specific**: Say \"compress hero.png (450KB) to WebP\" not \"optimize images\".\n- **Prioritize ruthlessly**: A site with 200ms LCP and 0 CLS is already excellent—say so.\n\n## Quick Reference\n\n| Task | Tool Call |\n|------|-----------|\n| Load page | `navigate_page(url: \"...\")` |\n| Start trace | `performance_start_trace(autoStop: true, reload: true)` |\n| Analyze insight | `performance_analyze_insight(insightSetId: \"...\", insightName: \"...\")` |\n| List requests | `list_network_requests(resourceTypes: [\"Script\", \"Stylesheet\", ...])` |\n| Request details | `get_network_request(reqid: <id>)` |\n| A11y snapshot | `take_snapshot(verbose: true)` |\n\n## Workflow\n\nCopy this checklist to track progress:\n\n```\nAudit Progress:\n- [ ] Phase 1: Performance trace (navigate + record)\n- [ ] Phase 2: Core Web Vitals analysis (includes CLS culprits)\n- [ ] Phase 3: Network analysis\n- [ ] Phase 4: Accessibility snapshot\n- [ ] Phase 5: Codebase analysis (skip if third-party site)\n```\n\n### Phase 1: Performance Trace\n\n1. Navigate to the target URL:\n   ```\n   navigate_page(url: \"<target-url>\")\n   ```\n\n2. Start a performance trace with reload to capture cold-load metrics:\n   ```\n   performance_start_trace(autoStop: true, reload: true)\n   ```\n\n3. Wait for trace completion, then retrieve results.\n\n**Troubleshooting:**\n- If trace returns empty or fails, verify the page loaded correctly with `navigate_page` first\n- If insight names don''t match, inspect the trace response to list available insights\n\n### Phase 2: Core Web Vitals Analysis\n\nUse `performance_analyze_insight` to extract key metrics.\n\n**Note:** Insight names may vary across Chrome DevTools versions. If an insight name doesn''t work, check the `insightSetId` from the trace response to discover available insights.\n\nCommon insight names:\n\n| Metric | Insight Name | What to Look For |\n|--------|--------------|------------------|\n| LCP | `LCPBreakdown` | Time to largest contentful paint; breakdown of TTFB, resource load, render delay |\n| CLS | `CLSCulprits` | Elements causing layout shifts (images without dimensions, injected content, font swaps) |\n| Render Blocking | `RenderBlocking` | CSS/JS blocking first paint |\n| Document Latency | `DocumentLatency` | Server response time issues |\n| Network Dependencies | `NetworkRequestsDepGraph` | Request chains delaying critical resources |\n\nExample:\n```\nperformance_analyze_insight(insightSetId: \"<id-from-trace>\", insightName: \"LCPBreakdown\")\n```\n\n**Key thresholds (good/needs-improvement/poor):**\n- TTFB: < 800ms / < 1.8s / > 1.8s\n- FCP: < 1.8s / < 3s / > 3s\n- LCP: < 2.5s / < 4s / > 4s\n- INP: < 200ms / < 500ms / > 500ms\n- TBT: < 200ms / < 600ms / > 600ms\n- CLS: < 0.1 / < 0.25 / > 0.25\n- Speed Index: < 3.4s / < 5.8s / > 5.8s\n\n### Phase 3: Network Analysis\n\nList all network requests to identify optimization opportunities:\n```\nlist_network_requests(resourceTypes: [\"Script\", \"Stylesheet\", \"Document\", \"Font\", \"Image\"])\n```\n\n**Look for:**\n\n1. **Render-blocking resources**: JS/CSS in `<head>` without `async`/`defer`/`media` attributes\n2. **Network chains**: Resources discovered late because they depend on other resources loading first (e.g., CSS imports, JS-loaded fonts)\n3. **Missing preloads**: Critical resources (fonts, hero images, key scripts) not preloaded\n4. **Caching issues**: Missing or weak `Cache-Control`, `ETag`, or `Last-Modified` headers\n5. **Large payloads**: Uncompressed or oversized JS/CSS bundles\n6. **Unused preconnects**: If flagged, verify by checking if ANY requests went to that origin. If zero requests, it''s definitively unused—recommend removal. If requests exist but loaded late, the preconnect may still be valuable.\n\nFor detailed request info:\n```\nget_network_request(reqid: <id>)\n```\n\n### Phase 4: Accessibility Snapshot\n\nTake an accessibility tree snapshot:\n```\ntake_snapshot(verbose: true)\n```\n\n**Flag high-level gaps:**\n- Missing or duplicate ARIA IDs\n- Elements with poor contrast ratios (check against WCAG AA: 4.5:1 for normal text, 3:1 for large text)\n- Focus traps or missing focus indicators\n- Interactive elements without accessible names\n\n## Phase 5: Codebase Analysis\n\n**Skip if auditing a third-party site without codebase access.**\n\nAnalyze the codebase to understand where improvements can be made.\n\n### Detect Framework & Bundler\n\nSearch for configuration files to identify the stack:\n\n| Tool | Config Files |\n|------|--------------|\n| Webpack | `webpack.config.js`, `webpack.*.js` |\n| Vite | `vite.config.js`, `vite.config.ts` |\n| Rollup | `rollup.config.js`, `rollup.config.mjs` |\n| esbuild | `esbuild.config.js`, build scripts with `esbuild` |\n| Parcel | `.parcelrc`, `package.json` (parcel field) |\n| Next.js | `next.config.js`, `next.config.mjs` |\n| Nuxt | `nuxt.config.js`, `nuxt.config.ts` |\n| SvelteKit | `svelte.config.js` |\n| Astro | `astro.config.mjs` |\n\nAlso check `package.json` for framework dependencies and build scripts.\n\n### Tree-Shaking & Dead Code\n\n- **Webpack**: Check for `mode: ''production''`, `sideEffects` in package.json, `usedExports` optimization\n- **Vite/Rollup**: Tree-shaking enabled by default; check for `treeshake` options\n- **Look for**: Barrel files (`index.js` re-exports), large utility libraries imported wholesale (lodash, moment)\n\n### Unused JS/CSS\n\n- Check for CSS-in-JS vs. static CSS extraction\n- Look for PurgeCSS/UnCSS configuration (Tailwind''s `content` config)\n- Identify dynamic imports vs. eager loading\n\n### Polyfills\n\n- Check for `@babel/preset-env` targets and `useBuiltIns` setting\n- Look for `core-js` imports (often oversized)\n- Check `browserslist` config for overly broad targeting\n\n### Compression & Minification\n\n- Check for `terser`, `esbuild`, or `swc` minification\n- Look for gzip/brotli compression in build output or server config\n- Check for source maps in production builds (should be external or disabled)\n\n## Output Format\n\nPresent findings as:\n\n1. **Core Web Vitals Summary** - Table with metric, value, and rating (good/needs-improvement/poor)\n2. **Top Issues** - Prioritized list of problems with estimated impact (high/medium/low)\n3. **Recommendations** - Specific, actionable fixes with code snippets or config changes\n4. **Codebase Findings** - Framework/bundler detected, optimization opportunities (omit if no codebase access)\n"},"lastSynced":"2026-03-08T02:00:50.846Z","agentAnalysis":{"suitability":{"en":"Perfect for Performance Optimization Agents needing advanced web page auditing capabilities using Chrome DevTools MCP tools.","zh":"非常适合需要使用Chrome DevTools MCP工具进行高级网页审计的性能优化代理。","ja":"Chrome DevTools MCPツールを使用した高度なWebページ監査機能を必要とするパフォーマンス最適化エージェントに最適です。","ko":"Chrome DevTools MCP 도구를 사용하여 고급 웹 페이지 감사를 수행해야 하는 성능 최적화 에이전트에 적합합니다.","es":"Perfecto para agentes de optimización de rendimiento que necesitan capacidades avanzadas de auditoría de páginas web utilizando herramientas de MCP de Chrome DevTools.","fr":"Parfait pour les agents d''optimisation des performances nécessitant des capacités de vérification avancées de pages Web à l''aide d''outils MCP de Chrome DevTools.","de":"Perfekt für Leistungs-Optimierungs-Agents, die erweiterte Webseiten-Prüf-Funktionen unter Verwendung von Chrome DevTools MCP-Tools benötigen.","pt":"Perfeito para agentes de otimização de desempenho que necessitam de capacidades avançadas de auditoria de páginas web usando ferramentas MCP do Chrome DevTools.","ru":"Идеально подходит для агентов оптимизации производительности, которым требуются расширенные возможности аудита веб-страниц с помощью инструментов MCP Chrome DevTools.","ar":"مثالي لعمليات تحسين الأداء التي تحتاج إلى قدرات متقدمة لمراجعة صفحات الويب باستخدام أدوات MCP من Chrome DevTools."},"recommendation":{"en":"Empowers agents to audit web page performance, focusing on Core Web Vitals and network optimization using Chrome DevTools MCP tools, and identify high-level accessibility gaps, ultimately enhancing user experience through optimized web page load times and improved overall performance.","zh":"赋予代理审计Web页面性能的能力，重点关注核心Web指标和使用Chrome DevTools MCP工具的网络优化，并找出高级可访问性差距， 궁극上通过优化的网页加载时间和改进的整体性能来增强用户体验。","ja":"エージェントにWebページのパフォーマンスを監査する機能を与え、Core Web VitalsとChrome DevTools MCPツールを使用したネットワークの最適化に焦点を当て、また、高レベルのアクセシビリティギャップを特定し、最終的に最適化されたWebページの読み込み時間と全体的なパフォーマンスの改善を通じてユーザーエクスペリエンスを強化します。","ko":"에이전트가 웹 페이지 성능을 감사할 수 있는 기능을 부여하여 핵심 웹 비탈과 Chrome DevTools MCP 도구를 사용한 네트워크 최적화를 중점으로 하며, 또한 고수준의 접근성 격차를 식별하여 궁극적으로 최적화된 웹 페이지 로드 시간과 개선된 전체 성능을 통해 사용자 경험을 향상시킵니다.","es":"Habilita a los agentes a auditar el rendimiento de las páginas web, centrándose en Core Web Vitals y optimización de red utilizando herramientas de MCP de Chrome DevTools, e identificar brechas de accesibilidad de alto nivel, mejorando en última instancia la experiencia del usuario a través de tiempos de carga de páginas web optimizados y un rendimiento general mejorado.","fr":"Permet aux agents de vérifier les performances des pages Web, en se concentrant sur Core Web Vitals et l''optimisation du réseau à l''aide d''outils MCP de Chrome DevTools, et d''identifier les lacunes d''accessibilité de haut niveau, améliorant ainsi l''expérience utilisateur grâce à des temps de chargement de pages Web optimisés et à des performances globales améliorées.","de":"Ermächtigt Agents, die Leistung von Webseiten zu prüfen, wobei der Schwerpunkt auf Core Web Vitals und Netzwerkoptimierung unter Verwendung von Chrome DevTools MCP-Tools liegt, und erkennt Lücken in der Zugänglichkeit auf hohem Niveau, wodurch letztendlich die Benutzererfahrung durch optimierte Ladezeiten von Webseiten und verbesserte Gesamtleistung verbessert wird.","pt":"Habilita os agentes a auditar o desempenho da página web, focando em Core Web Vitals e otimização de rede usando ferramentas MCP do Chrome DevTools, e identificar lacunas de acessibilidade de alto nível, melhorando em última análise a experiência do usuário por meio de tempos de carregamento de página web otimizados e desempenho geral aprimorado.","ru":"Наделяет агентов возможностью аудита производительности веб-страниц, сосредотачиваясь на Core Web Vitals и оптимизации сети с помощью инструментов MCP Chrome DevTools, и выявления высокоуровневых пробелов в доступности, в конечном итоге улучшая опыт пользователя за счет оптимизированных времен загрузки веб-страниц и улучшенной общей производительности.","ar":"تمكّن الوكلاء من مراجعة أداء صفحة الويب، مع التركيز على معايير الويب الأساسية وتنظيم الشبكة باستخدام أدوات MCP من Chrome DevTools، وتحديد الفجوات في إمكانية الوصول على مستوى عال، مما يؤدي في النهاية إلى تعزيز تجربة المستخدم من خلال أوقات تحميل صفحات الويب المُحسّنة وأداء عام مُحسّن."},"useCases":{"en":["Auditing web page performance using Core Web Vitals","Optimizing network requests for faster page loads","Identifying and addressing high-level accessibility gaps"],"zh":["使用核心Web指标进行网页性能审计","优化网络请求以实现更快的页面加载","识别和解决高级可访问性差距"],"ja":["Core Web Vitalsを使用したWebページのパフォーマンス監査","ページの読み込みを速めるためのネットワークリクエストの最適化","高レベルのアクセシビリティギャップの特定と解決"],"ko":["핵심 웹 비탈을 사용한 웹 페이지 성능 감사","페이지 로드를 더 빠르게 하기 위한 네트워크 요청 최적화","고수준의 접근성 격차 식별 및 해결"],"es":["Auditoría del rendimiento de la página web utilizando Core Web Vitals","Optimización de solicitudes de red para cargas de página más rápidas","Identificación y atención de brechas de accesibilidad de alto nivel"],"fr":["Vérification des performances de la page Web à l''aide de Core Web Vitals","Optimisation des requêtes réseau pour des chargements de pages plus rapides","Identification et traitement des lacunes d''accessibilité de haut niveau"],"de":["Prüfung der Leistung von Webseiten unter Verwendung von Core Web Vitals","Optimierung von Netzwerkanfragen für schnellere Seitenladezeiten","Erkennung und Behandlung von Lücken in der Zugänglichkeit auf hohem Niveau"],"pt":["Auditoria do desempenho da página web usando Core Web Vitals","Otimização de solicitações de rede para carregamento de página mais rápido","Identificação e tratamento de lacunas de acessibilidade de alto nível"],"ru":["Аудит производительности веб-страниц с помощью Core Web Vitals","Оптимизация сетевых запросов для более быстрой загрузки страниц","Выявление и устранение высокоуровневых пробелов в доступности"],"ar":["مراجعة أداء صفحة الويب باستخدام معايير الويب الأساسية","تحسين طلبات الشبكة لتحميل الصفحات بشكل أسرع","تحديد الفجوات في إمكانية الوصول على مستوى عال وتصحيحها"]},"limitations":{"en":["Requires Chrome DevTools MCP server configuration","Needs navigate_page or performance_start_trace availability"],"zh":["需要Chrome DevTools MCP服务器配置","需要navigate_page或performance_start_trace的可用性"],"ja":["Chrome DevTools MCPサーバーの構成が必要","navigate_pageまたはperformance_start_traceの可用性が必要"],"ko":["Chrome DevTools MCP 서버 구성이 필요","navigate_page 또는 performance_start_trace 가용성이 필요"],"es":["Requiere configuración del servidor MCP de Chrome DevTools","Necesita disponibilidad de navigate_page o performance_start_trace"],"fr":["Nécessite une configuration du serveur MCP de Chrome DevTools","Nécessite la disponibilité de navigate_page ou performance_start_trace"],"de":["Benötigt Konfiguration des Chrome DevTools MCP-Servers","Benötigt Verfügbarkeit von navigate_page oder performance_start_trace"],"pt":["Exige configuração do servidor MCP do Chrome DevTools","Necessita de disponibilidade de navigate_page ou performance_start_trace"],"ru":["Требует настройки сервера MCP Chrome DevTools","Требует доступности navigate_page или performance_start_trace"],"ar":["يتطلب تكوين خادم MCP من Chrome DevTools","يتطلب توافر navigate_page أو performance_start_trace"]},"version":4},"contentHash":"dbb0e6ab3e3565cf49de6b2c3bcd62339aafebb099514ec3c86771a096cd920b","qualityScore":60}');
