INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dailydotdev/daily/daily.dev', 'daily.dev', 'dailydotdev', 'daily', 'community', 'daily.dev dailydotdev daily community daily.dev is a professional network for developers to learn, collaborate, and grow together, providing real-time content and structured taxonomy for precise discovery. daily.dev是一个专业的开发者网络，提供实时开发者内容和结构化分类，帮助开发者学习、协作和成长 daily.devは、開発者が學び、コラボレーションし、成長するためのプロフェッショナルなネットワークです。リアルタイムの開発者コンテンツと構造化された分類を提供しています daily.dev는 개발자가 학습, 협업, 성장할 수 있는 전문 개발자 네트워크로, 실시간 개발자 콘텐츠와 구조화된 분류를 제공합니다 daily.dev es una red profesional para desarrolladores que ofrece contenido en tiempo real y validado por la comunidad, con una taxonomía estructurada para una descubierta precisa daily.dev est un réseau professionnel pour les développeurs qui propose du contenu en temps réel validé par la communauté, avec une taxonomie structurée pour une découverte précise daily.dev ist ein professionelles Netzwerk für Entwickler, das Echtzeit-Inhalte und communityvalidierte Taxonomie bietet, mit einer strukturierten Taxonomie für eine präzise Entdeckung daily.dev é uma rede profissional para desenvolvedores aprender, colaborar e crescer juntos, com API para superar limitações de conhecimento de LLM daily.dev - это профессиональная сеть для разработчиков, чтобы учиться, сотрудничать и расти вместе, с API для преодоления ограничений знаний LLM daily.dev هي شبكة احترافية للمطورين للتعلم والتعاون والنمو معًا، مع واجهة برمجة تطبيقات لتحقيق المعرفة في LLM how to use daily.dev API daily.dev alternative for developers daily.dev setup guide for AI agents what is daily.dev daily.dev vs other developer networks install daily.dev API token daily.dev security best practices daily.dev for AI agent development daily.dev API 开发者网络 实时开发者内容 结构化分类 API令牌保护 开发语言 AI工具 开发者平台 Aggregates articles from thousands of sources Validates content through community engagement Provides structured taxonomy for precise discovery Offers personalized content via API token Supports secure API token management with prefix ''dda_'' Restricts token usage to ''api.daily.dev'' domain daily.dev is a platform aggregating articles from thousands of sources, validated by community engagement, for developers to access personalized content');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('muratcankoylan/Agent-Skills-for-Context-Engineering/project-development', 'community', 'muratcankoylan', 'Agent-Skills-for-Context-Engineering', 'muratcankoylan/Agent-Skills-for-Context-Engineering', 'project-development', 0, 0, 60, '2026-03-08T01:57:15.282Z', '2026-03-08T02:00:52.546Z', 'd75b1d65a24d948134e5243020117280efe082c11d6928627dad0675af85d405', '{"id":"muratcankoylan/Agent-Skills-for-Context-Engineering/project-development","name":"project-development","description":{"en":"The project-development skill covers principles for identifying tasks suited to LLM processing and designing effective project architectures. It benefits developers building agent systems that require context management.","zh":"项目开发技能是一套综合的Agent技能，用于上下文工程、多代理架构和生产代理系统","ja":"プロジェクト開発スキルは、コンテキストエンジニアリング、マルチエージェントアーキテクチャ、プロダクションエージェントシステムを構築するための包括的なエージェントスキル","ko":"프로젝트 개발 스킬은 컨텍스트 엔지니어링, 멀티 에이전트 아키텍처 및 프로덕션 에이전트 시스템을 구축하기 위한 포괄적인 에이전트 스킬","es":"El desarrollo de proyectos con Agentes de Inteligencia Artificial implica diseñar arquitecturas efectivas y optimizar sistemas de agentes. Esta habilidad cubre los principios para identificar tareas adecuadas para el procesamiento LLM","fr":"Le développement de projets avec des Outils d''Intelligence Artificielle implique la conception d''architectures efficaces et l''optimisation de systèmes d''agents. Cette compétence couvre les principes pour identifier les tâches adaptées au traitement LLM","de":"Die Projektentwicklung mit KI-Agents umfasst das Entwerfen effektiver Architekturen und das Optimieren von Agentensystemen. Diese Fähigkeit deckt die Prinzipien für die Identifizierung von Aufgaben ab, die für die LLM-Verarbeitung geeignet sind","pt":"Desenvolvimento de projetos com ferramentas de AI para criação de arquiteturas de agentes e processamento de LLM","ru":"Разработка проектов с помощью ИИ Агентов для создания архитектуры агентов и обработки LLM","ar":"تطوير المشاريع باستخدام أدوات الذكاء الاصطناعي لإنشاء هندسة السياق وتحليل LLM"},"seo":{"title":{"en":"project-development: Setup Guide for AI Agents | AI Agent...","zh":"项目开发快速入门指南 - AIエージェント","ja":"プロジェクト開発ベストプラクティス - AIエージェント","ko":"프로젝트 개발 설정 가이드 - AI 에이전트","es":"Guía de configuración para el desarrollo de proyectos con...","fr":"Guide de mise en place pour le développement de projets a...","de":"Einrichtungsleitfaden für die Projektentwicklung mit KI-A...","pt":"Guia de Configuração de Desenvolvimento de Projetos com F...","ru":"Руководство по настройке ИИ Агентов для разработки проектов","ar":"دليل إعداد أدوات الذكاء الاصطناعي لتطوير المشاريع"},"description":{"en":"Unlock efficient context management in your agent systems. Learn how to activate project-development for LLM processing and multi-agent architectures.","zh":"了解项目开发技能，掌握LLM处理和多代理架构的设计","ja":"プロジェクト開発スキルを活用して、LLM処理とマルチエージェントアーキテクチャを設計","ko":"프로젝트 개발 스킬을 활용하여 LLM 처리 및 멀티 에이전트 아키텍처를 설계","es":"Aprende a desarrollar proyectos con Agentes de Inteligencia Artificial. Descubre cómo diseñar arquitecturas efectivas y optimizar sistemas de agentes","fr":"Découvrez comment développer des projets avec des Outils d''Intelligence Artificielle. Apprenez à concevoir des architectures efficaces et à optimiser les sys...","de":"Erfahren Sie, wie Sie Projekte mit KI-Agents entwickeln. Entdecken Sie, wie Sie effektive Architekturen entwerfen und Agentensysteme optimieren","pt":"Aprenda a criar projetos eficazes com ferramentas de AI, incluindo arquiteturas de agentes e processamento de LLM","ru":"Узнайте, как создать эффективные проекты с помощью ИИ Агентов, включая архитектуру агентов и обработку LLM","ar":"تعلم كيفية إنشاء مشاريع فعالة باستخدام أدوات الذكاء الاصطناعي، بما في ذلك هندسة السياق وتحليل LLM"},"definition":{"en":"project-development is a comprehensive collection of Agent Skills for context engineering, multi-agent architectures, and production agent systems.","zh":"项目开发技能是指用于设计和优化代理系统的技能","ja":"プロジェクト開発スキルとは、エージェントシステムを設計および最適化するためのスキル","ko":"프로젝트 개발 스킬이란 에이전트 시스템을 설계 및 최적화하기 위한 스킬","es":"El desarrollo de proyectos es una habilidad que cubre los principios para identificar tareas adecuadas para el procesamiento LLM y diseñar arquitecturas efectivas","fr":"Le développement de projets est une compétence qui couvre les principes pour identifier les tâches adaptées au traitement LLM et concevoir des architectures efficaces","de":"Die Projektentwicklung ist eine Fähigkeit, die die Prinzipien für die Identifizierung von Aufgaben abdeckt, die für die LLM-Verarbeitung geeignet sind, und das Entwerfen effektiver Architekturen","pt":"Desenvolvimento de projetos é uma habilidade que abrange princípios para identificar tarefas adequadas para processamento de LLM","ru":"Разработка проектов - это навык, который охватывает принципы для определения задач, подходящих для обработки LLM","ar":"تطوير المشاريع هو مهارة تشمل مبادئ لتحديد المهام المناسبة لمعالجة LLM"},"features":{"en":["Applies to batch processing pipelines, multi-agent research systems, and interactive agent applications","Enables effective context management for agent systems","Supports rapid iteration using agent-assisted development","Helps identify tasks suited to LLM processing","Covers principles for designing effective project architectures"],"zh":["LLM处理任务识别","多代理架构设计","代理系统优化","批处理管道构建","交互式代理应用开发"],"ja":["LLM処理タスクの識別","マルチエージェントアーキテクチャの設計","エージェントシステムの最適化","バッチ処理パイプラインの構築","インタラクティブエージェントアプリケーションの開発"],"ko":["LLM 처리 태스크 식별","멀티 에이전트 아키텍처 설계","에이전트 시스템 최적화","배치 처리 파이프라인 구축","인터랙티브 에이전트 애플리케이션 개발"],"es":["Diseño de arquitecturas efectivas para sistemas de agentes","Identificación de tareas adecuadas para el procesamiento LLM","Optimización de sistemas de agentes para el procesamiento LLM","Desarrollo de pipelines de procesamiento por lotes","Creación de sistemas de investigación de multi-agentes","Desarrollo de aplicaciones interactivas de agentes"],"fr":["Conception d''architectures efficaces pour les systèmes d''agents","Identification de tâches adaptées au traitement LLM","Optimisation de systèmes d''agents pour le traitement LLM","Développement de pipelines de traitement par lot","Création de systèmes de recherche de multi-agents","Développement d''applications interactives d''agents"],"de":["Entwurf effektiver Architekturen für Agentensysteme","Identifizierung von Aufgaben, die für die LLM-Verarbeitung geeignet sind","Optimierung von Agentensystemen für die LLM-Verarbeitung","Entwicklung von Batch-Verarbeitungspipelines","Erstellung von Multi-Agenten-Forschungssystemen","Entwicklung interaktiver Agenten-Anwendungen"],"pt":["Identificação de tarefas adequadas para processamento de LLM","Criação de arquiteturas de agentes eficazes","Iteração rápida com desenvolvimento assistido por agentes","Integração com pipelines de processamento de LLM","Suporte à criação de sistemas de agentes interativos"],"ru":["Определение задач, подходящих для обработки LLM","Создание эффективной архитектуры агентов","Быстрая итерация с разработкой, помогаемой агентами","Интеграция с конвейерами обработки LLM","Поддержка создания интерактивных систем агентов"],"ar":["تحديد المهام المناسبة لمعالجة LLM","إنشاء هندسة سياق فعالة","التكرار السريع مع التطوير المدعوم بالوكلاء","التكامل مع أنابيب معالجة LLM","دعم إنشاء أنظمة وكلاء تفاعلية"]},"keywords":{"en":["how to use project-development","project-development setup guide","what is project-development","project-development vs competitor skills","project-development alternative","project-development install","project-development for LLM processing","project-development for multi-agent architectures"],"zh":["AIエージェント","项目开发","LLM处理","多代理架构","代理系统优化","批处理管道","交互式代理应用"],"ja":["AIエージェント","プロジェクト開発","LLM処理","マルチエージェントアーキテクチャ","エージェントシステムの最適化","バッチ処理パイプライン","インタラクティブエージェントアプリケーション"],"ko":["AI 에이전트","프로젝트 개발","LLM 처리","멀티 에이전트 아키텍처","에이전트 시스템 최적화","배치 처리 파이프라인","인터랙티브 에이전트 애플리케이션"],"es":["desarrollo de proyectos con Agentes de Inteligencia Artificial","diseño de arquitecturas efectivas","procesamiento LLM","sistemas de agentes","pipelines de procesamiento por lotes","sistemas de investigación de multi-agentes","aplicaciones interactivas de agentes","optimización de sistemas de agentes"],"fr":["développement de projets avec des Outils d''Intelligence Artificielle","conception d''architectures efficaces","traitement LLM","systèmes d''agents","pipelines de traitement par lot","systèmes de recherche de multi-agents","applications interactives d''agents","optimisation de systèmes d''agents"],"de":["Projektentwicklung mit KI-Agents","Entwurf effektiver Architekturen","LLM-Verarbeitung","Agentensysteme","Batch-Verarbeitungspipelines","Multi-Agenten-Forschungssysteme","interaktive Agenten-Anwendungen","Optimierung von Agentensystemen"],"pt":["desenvolvimento de projetos com AI","ferramentas de AI para desenvolvimento","arquitetura de agentes","processamento de LLM","criação de pipelines de LLM","desenvolvimento assistido por agentes","sistemas de agentes interativos","herramientas de desenvolvimento de projetos"],"ru":["разработка проектов с ИИ","ИИ Агенты для разработки","архитектура агентов","обработка LLM","создание конвейеров LLM","разработка, помогаемая агентами","интерактивные системы агентов","инструменты разработки проектов"],"ar":["تطوير المشاريع باستخدام الذكاء الاصطناعي","أدوات الذكاء الاصطناعي لتطوير المشاريع","هندسة السياق","معالجة LLM","إنشاء أنابيب معالجة LLM","تطوير مدعوم بالوكلاء","أنظمة وكلاء تفاعلية","أدوات تطوير المشاريع"]}},"owner":"muratcankoylan","repo":"Agent-Skills-for-Context-Engineering","repoPath":"muratcankoylan/Agent-Skills-for-Context-Engineering","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.282Z","topics":[],"category":"community","skillMd":{"name":"project-development","description":"This skill should be used when the user asks to start an LLM project, design batch pipeline, evaluate task-model fit, structure agent project, or mentions pipeline architecture, agent-assisted development, cost estimation, or choosing between LLM and traditional approaches.","bodyPreview":"# Project Development Methodology\n\nThis skill covers the principles for identifying tasks suited to LLM processing, designing effective project architectures, and iterating rapidly using agent-assisted development. The methodology applies whether building a batch processing pipeline, a multi-agent research system, or an interactive agent application.\n\n## When to Activate\n\nActivate this skill when:\n- Starting a new project that might benefit from LLM processing\n- Evaluating whether a task is well","body":"# Project Development Methodology\n\nThis skill covers the principles for identifying tasks suited to LLM processing, designing effective project architectures, and iterating rapidly using agent-assisted development. The methodology applies whether building a batch processing pipeline, a multi-agent research system, or an interactive agent application.\n\n## When to Activate\n\nActivate this skill when:\n- Starting a new project that might benefit from LLM processing\n- Evaluating whether a task is well-suited for agents versus traditional code\n- Designing the architecture for an LLM-powered application\n- Planning a batch processing pipeline with structured outputs\n- Choosing between single-agent and multi-agent approaches\n- Estimating costs and timelines for LLM-heavy projects\n\n## Core Concepts\n\n### Task-Model Fit Recognition\n\nNot every problem benefits from LLM processing. The first step in any project is evaluating whether the task characteristics align with LLM strengths. This evaluation should happen before writing any code.\n\n**LLM-suited tasks share these characteristics:**\n\n| Characteristic | Why It Fits |\n|----------------|-------------|\n| Synthesis across sources | LLMs excel at combining information from multiple inputs |\n| Subjective judgment with rubrics | LLMs handle grading, evaluation, and classification with criteria |\n| Natural language output | When the goal is human-readable text, not structured data |\n| Error tolerance | Individual failures do not break the overall system |\n| Batch processing | No conversational state required between items |\n| Domain knowledge in training | The model already has relevant context |\n\n**LLM-unsuited tasks share these characteristics:**\n\n| Characteristic | Why It Fails |\n|----------------|--------------|\n| Precise computation | Math, counting, and exact algorithms are unreliable |\n| Real-time requirements | LLM latency is too high for sub-second responses |\n| Perfect accuracy requirements | Hallucination risk makes 100% accuracy impossible |\n| Proprietary data dependence | The model lacks necessary context |\n| Sequential dependencies | Each step depends heavily on the previous result |\n| Deterministic output requirements | Same input must produce identical output |\n\nThe evaluation should happen through manual prototyping: take one representative example and test it directly with the target model before building any automation.\n\n### The Manual Prototype Step\n\nBefore investing in automation, validate task-model fit with a manual test. Copy one representative input into the model interface. Evaluate the output quality. This takes minutes and prevents hours of wasted development.\n\nThis validation answers critical questions:\n- Does the model have the knowledge required for this task?\n- Can the model produce output in the format you need?\n- What level of quality should you expect at scale?\n- Are there obvious failure modes to address?\n\nIf the manual prototype fails, the automated system will fail. If it succeeds, you have a baseline for comparison and a template for prompt design.\n\n### Pipeline Architecture\n\nLLM projects benefit from staged pipeline architectures where each stage is:\n- **Discrete**: Clear boundaries between stages\n- **Idempotent**: Re-running produces the same result\n- **Cacheable**: Intermediate results persist to disk\n- **Independent**: Each stage can run separately\n\n**The canonical pipeline structure:**\n\n```\nacquire → prepare → process → parse → render\n```\n\n1. **Acquire**: Fetch raw data from sources (APIs, files, databases)\n2. **Prepare**: Transform data into prompt format\n3. **Process**: Execute LLM calls (the expensive, non-deterministic step)\n4. **Parse**: Extract structured data from LLM outputs\n5. **Render**: Generate final outputs (reports, files, visualizations)\n\nStages 1, 2, 4, and 5 are deterministic. Stage 3 is non-deterministic and expensive. This separation allows re-running the expensive LLM stage only when necessary, while iterating quickly on parsing and rendering.\n\n### File System as State Machine\n\nUse the file system to track pipeline state rather than databases or in-memory structures. Each processing unit gets a directory. Each stage completion is marked by file existence.\n\n```\ndata/{id}/\n├── raw.json         # acquire stage complete\n├── prompt.md        # prepare stage complete\n├── response.md      # process stage complete\n├── parsed.json      # parse stage complete\n```\n\nTo check if an item needs processing: check if the output file exists. To re-run a stage: delete its output file and downstream files. To debug: read the intermediate files directly.\n\nThis pattern provides:\n- Natural idempotency (file existence gates execution)\n- Easy debugging (all state is human-readable)\n- Simple parallelization (each directory is independent)\n- Trivial caching (files persist across runs)\n\n### Structured Output Design\n\nWhen LLM outputs must be parsed programmatically, prompt design directly determines parsing reliability. The prompt must specify exact format requirements with examples.\n\n**Effective structure specification includes:**\n\n1. **Section markers**: Explicit headers or prefixes for parsing\n2. **Format examples**: Show exactly what output should look like\n3. **Rationale disclosure**: \"I will be parsing this programmatically\"\n4. **Constrained values**: Enumerated options, score ranges, formats\n\n**Example prompt structure:**\n```\nAnalyze the following and provide your response in exactly this format:\n\n## Summary\n[Your summary here]\n\n## Score\nRating: [1-10]\n\n## Details\n- Key point 1\n- Key point 2\n\nFollow this format exactly because I will be parsing it programmatically.\n```\n\nThe parsing code must handle variations gracefully. LLMs do not follow instructions perfectly. Build parsers that:\n- Use regex patterns flexible enough to handle minor formatting variations\n- Provide sensible defaults when sections are missing\n- Log parsing failures for later review rather than crashing\n\n### Agent-Assisted Development\n\nModern agent-capable models can accelerate development significantly. The pattern is:\n\n1. Describe the project goal and constraints\n2. Let the agent generate initial implementation\n3. Test and iterate on specific failures\n4. Refine prompts and architecture based on results\n\nThis is about rapid iteration: generate, test, fix, repeat. The agent handles boilerplate and initial structure while you focus on domain-specific requirements and edge cases.\n\nKey practices for effective agent-assisted development:\n- Provide clear, specific requirements upfront\n- Break large projects into discrete components\n- Test each component before moving to the next\n- Keep the agent focused on one task at a time\n\n### Cost and Scale Estimation\n\nLLM processing has predictable costs that should be estimated before starting. The formula:\n\n```\nTotal cost = (items × tokens_per_item × price_per_token) + API overhead\n```\n\nFor batch processing:\n- Estimate input tokens per item (prompt + context)\n- Estimate output tokens per item (typical response length)\n- Multiply by item count\n- Add 20-30% buffer for retries and failures\n\nTrack actual costs during development. If costs exceed estimates significantly, re-evaluate the approach. Consider:\n- Reducing context length through truncation\n- Using smaller models for simpler items\n- Caching and reusing partial results\n- Parallel processing to reduce wall-clock time (not token cost)\n\n## Detailed Topics\n\n### Choosing Single vs Multi-Agent Architecture\n\nSingle-agent pipelines work for:\n- Batch processing with independent items\n- Tasks where items do not interact\n- Simpler cost and complexity management\n\nMulti-agent architectures work for:\n- Parallel exploration of different aspects\n- Tasks exceeding single context window capacity\n- When specialized sub-agents improve quality\n\nThe primary reason for multi-agent is context isolation, not role anthropomorphization. Sub-agents get fresh context windows for focused subtasks. This prevents context degradation on long-running tasks.\n\nSee `multi-agent-patterns` skill for detailed architecture guidance.\n\n### Architectural Reduction\n\nStart with minimal architecture. Add complexity only when proven necessary. Production evidence shows that removing specialized tools often improves performance.\n\nVercel''s d0 agent achieved 100% success rate (up from 80%) by reducing from 17 specialized tools to 2 primitives: bash command execution and SQL. The file system agent pattern uses standard Unix utilities (grep, cat, find, ls) instead of custom exploration tools.\n\n**When reduction outperforms complexity:**\n- Your data layer is well-documented and consistently structured\n- The model has sufficient reasoning capability\n- Your specialized tools were constraining rather than enabling\n- You are spending more time maintaining scaffolding than improving outcomes\n\n**When complexity is necessary:**\n- Your underlying data is messy, inconsistent, or poorly documented\n- The domain requires specialized knowledge the model lacks\n- Safety constraints require limiting agent capabilities\n- Operations are truly complex and benefit from structured workflows\n\nSee `tool-design` skill for detailed tool architecture guidance.\n\n### Iteration and Refactoring\n\nExpect to refactor. Production agent systems at scale require multiple architectural iterations. Manus refactored their agent framework five times since launch. The Bitter Lesson suggests that structures added for current model limitations become constraints as models improve.\n\nBuild for change:\n- Keep architecture simple and unopinionated\n- Test across model strengths to verify your harness is not limiting performance\n- Design systems that benefit from model improvements rather than locking in limitations\n\n## Practical Guidance\n\n### Project Planning Template\n\n1. **Task Analysis**\n   - What is the input? What is the desired output?\n   - Is this synthesis, generation, classification, or analysis?\n   - What error rate is acceptable?\n   - What is the value per successful completion?\n\n2. **Manual Validation**\n   - Test one example with target model\n   - Evaluate output quality and format\n   - Identify failure modes\n   - Estimate tokens per item\n\n3. **Architecture Selection**\n   - Single pipeline vs multi-agent\n   - Required tools and data sources\n   - Storage and caching strategy\n   - Parallelization approach\n\n4. **Cost Estimation**\n   - Items × tokens × price\n   - Development time\n   - Infrastructure requirements\n   - Ongoing operational costs\n\n5. **Development Plan**\n   - Stage-by-stage implementation\n   - Testing strategy per stage\n   - Iteration milestones\n   - Deployment approach\n\n### Anti-Patterns to Avoid\n\n**Skipping manual validation**: Building automation before verifying the model can do the task wastes significant time when the approach is fundamentally flawed.\n\n**Monolithic pipelines**: Combining all stages into one script makes debugging and iteration difficult. Separate stages with persistent intermediate outputs.\n\n**Over-constraining the model**: Adding guardrails, pre-filtering, and validation logic that the model could handle on its own. Test whether your scaffolding helps or hurts.\n\n**Ignoring costs until production**: Token costs compound quickly at scale. Estimate and track from the beginning.\n\n**Perfect parsing requirements**: Expecting LLMs to follow format instructions perfectly. Build robust parsers that handle variations.\n\n**Premature optimization**: Adding caching, parallelization, and optimization before the basic pipeline works correctly.\n\n## Examples\n\n**Example 1: Batch Analysis Pipeline (Karpathy''s HN Time Capsule)**\n\nTask: Analyze 930 HN discussions from 10 years ago with hindsight grading.\n\nArchitecture:\n- 5-stage pipeline: fetch → prompt → analyze → parse → render\n- File system state: data/{date}/{item_id}/ with stage output files\n- Structured output: 6 sections with explicit format requirements\n- Parallel execution: 15 workers for LLM calls\n\nResults: $58 total cost, ~1 hour execution, static HTML output.\n\n**Example 2: Architectural Reduction (Vercel d0)**\n\nTask: Text-to-SQL agent for internal analytics.\n\nBefore: 17 specialized tools, 80% success rate, 274s average execution.\n\nAfter: 2 tools (bash + SQL), 100% success rate, 77s average execution.\n\nKey insight: The semantic layer was already good documentation. Claude just needed access to read files directly.\n\nSee [Case Studies](./references/case-studies.md) for detailed analysis.\n\n## Guidelines\n\n1. Validate task-model fit with manual prototyping before building automation\n2. Structure pipelines as discrete, idempotent, cacheable stages\n3. Use the file system for state management and debugging\n4. Design prompts for structured, parseable outputs with explicit format examples\n5. Start with minimal architecture; add complexity only when proven necessary\n6. Estimate costs early and track throughout development\n7. Build robust parsers that handle LLM output variations\n8. Expect and plan for multiple architectural iterations\n9. Test whether scaffolding helps or constrains model performance\n10. Use agent-assisted development for rapid iteration on implementation\n\n## Integration\n\nThis skill connects to:\n- context-fundamentals - Understanding context constraints for prompt design\n- tool-design - Designing tools for agent systems within pipelines\n- multi-agent-patterns - When to use multi-agent versus single pipelines\n- evaluation - Evaluating pipeline outputs and agent performance\n- context-compression - Managing context when pipelines exceed limits\n\n## References\n\nInternal references:\n- [Case Studies](./references/case-studies.md) - Karpathy HN Capsule, Vercel d0, Manus patterns\n- [Pipeline Patterns](./references/pipeline-patterns.md) - Detailed pipeline architecture guidance\n\nRelated skills in this collection:\n- tool-design - Tool architecture and reduction patterns\n- multi-agent-patterns - When to use multi-agent architectures\n- evaluation - Output evaluation frameworks\n\nExternal resources:\n- Karpathy''s HN Time Capsule project: https://github.com/karpathy/hn-time-capsule\n- Vercel d0 architectural reduction: https://vercel.com/blog/we-removed-80-percent-of-our-agents-tools\n- Manus context engineering: Peak Ji''s blog on context engineering lessons\n- Anthropic multi-agent research: How we built our multi-agent research system\n\n---\n\n## Skill Metadata\n\n**Created**: 2025-12-25\n**Last Updated**: 2025-12-25\n**Author**: Agent Skills for Context Engineering Contributors\n**Version**: 1.0.0\n\n"},"lastSynced":"2026-03-08T02:00:52.546Z","agentAnalysis":{"suitability":{"en":"Ideal for Developer Agents requiring effective project architecture design and task management for LLM processing","zh":"适用于需要有效的项目架构设计和任务管理以进行LLM处理的开发者代理","ja":"LLM処理のための効果的なプロジェクトアーキテクチャ設計とタスク管理を必要とするデベロッパー エージェントに適しています","ko":"LLM 처리를 위한 효과적인 프로젝트 아키텍처 설계 및 태스크 관리가 필요한 개발자 에이전트에 적합합니다","es":"Ideal para Agentes de Desarrollador que requieren un diseño de arquitectura de proyecto efectivo y gestión de tareas para el procesamiento LLM","fr":"Idéal pour les agents de développement nécessitant une conception d''architecture de projet efficace et une gestion de tâches pour le traitement LLM","de":"Ideal für Entwickleragenten, die ein effektives Projektarchitektur-Design und eine Aufgabenverwaltung für die LLM-Verarbeitung benötigen","pt":"Ideal para Agentes de Desenvolvedor que requerem uma arquitetura de projeto eficaz e gerenciamento de tarefas para processamento LLM","ru":"Идеально для агентов разработчиков, требующих эффективного проектирования архитектуры проекта и управления задачами для обработки LLM","ar":"مثالي لعميل المطور الذي يتطلب تصميمًا فعّالًا لهيئة المشروع وإدارة المهام لمعالجة LLM"},"recommendation":{"en":"Empowers agents to identify tasks suited to LLM processing, design effective project architectures, and iterate rapidly using agent-assisted development with context management and multi-agent system integration","zh":"赋予代理识别适合LLM处理的任务、设计有效的项目架构、并使用代理辅助开发和上下文管理以及多代理系统集成快速迭代的能力","ja":"LLM処理に適したタスクを特定し、効果的なプロジェクトアーキテクチャを設計し、エージェント支援開発とコンテキスト管理およびマルチエージェントシステム統合を使用して迅速に反復する能力をエージェントに与えます","ko":"LLM 처리에 적합한 태스크를 식별하고, 효과적인 프로젝트 아키텍처를 설계하며, 에이전트 보조 개발 및 콘텍스트 관리 및 다중 에이전트 시스템 통합을 사용하여 빠르게 반복할 수 있는 능력을 에이전트에게 부여합니다","es":"Habilita a los agentes a identificar tareas adecuadas para el procesamiento LLM, diseñar arquitecturas de proyecto efectivas y iterar rápidamente utilizando el desarrollo asistido por agentes con gestión de contexto e integración de sistemas de multi-agente","fr":"Permet aux agents d''identifier les tâches adaptées au traitement LLM, de concevoir des architectures de projet efficaces et d''itérer rapidement en utilisant le développement assisté par agent avec la gestion de contexte et l''intégration de systèmes multi-agents","de":"Ermöglicht es Agenten, Aufgaben zu identifizieren, die für die LLM-Verarbeitung geeignet sind, effektive Projektarchitekturen zu entwerfen und schnell mit agentenunterstützter Entwicklung unter Verwendung von Kontextverwaltung und Multi-Agenten-Systemintegration zu iterieren","pt":"Habilita os agentes a identificar tarefas adequadas para processamento LLM, projetar arquiteturas de projeto eficazes e iterar rapidamente usando desenvolvimento assistido por agente com gerenciamento de contexto e integração de sistema de vários agentes","ru":"Наделяет агентов возможностью выявлять задачи, подходящие для обработки LLM, проектировать эффективные архитектуры проекта и быстро итерировать с помощью разработки, ассистируемой агентом, с управлением контекстом и интеграцией системы多агентной","ar":"يمنح الوكلاء القدرة على تحديد المهام المناسبة لمعالجة LLM وتصميم هيئات المشروع الفعّالة والتكرار السريع باستخدام التطوير المدعوم بواسطة العميل مع إدارة السياق وتكامل نظام متعدد الوكلاء"},"useCases":{"en":["Designing batch processing pipelines","Building multi-agent research systems","Developing interactive agent applications"],"zh":["设计批处理管道","构建多代理研究系统","开发交互式代理应用"],"ja":["バッチ処理パイプラインの設計","マルチエージェント研究システムの構築","インタラクティブエージェントアプリケーションの開発"],"ko":["배치 처리 파이프라인 설계","다중 에이전트 연구 시스템 구축","인터랙티브 에이전트 애플리케이션 개발"],"es":["Diseñar tuberías de procesamiento por lotes","Crear sistemas de investigación multi-agente","Desarrollar aplicaciones de agente interactivas"],"fr":["Concevoir des pipelines de traitement par lots","Créer des systèmes de recherche multi-agents","Développer des applications d''agent interactives"],"de":["Entwurf von Batchverarbeitungspipelines","Erstellung von Multi-Agenten-Forschungssystemen","Entwicklung interaktiver Agenten-Anwendungen"],"pt":["Projetar pipelines de processamento em lotes","Construir sistemas de pesquisa de vários agentes","Desenvolver aplicações de agente interativo"],"ru":["Проектирование конвейеров пакетной обработки","Строительство систем исследований с несколькими агентами","Разработка интерактивных агентских приложений"],"ar":["تصميم خطوط أنابيب معالجة الدفعة","بناء أنظمة البحث متعددة الوكلاء","تطوير تطبيقات عميل تفاعلية"]},"limitations":{"en":["Requires understanding of LLM processing principles","Context management capabilities needed"],"zh":["需要了解LLM处理原理","需要上下文管理能力"],"ja":["LLM処理の原理の理解が必要","コンテキスト管理能力が必要"],"ko":["LLM 처리 원리의 이해가 필요","콘텍스트 관리 능력이 필요"],"es":["Requiere comprensión de los principios de procesamiento LLM","Se necesitan capacidades de gestión de contexto"],"fr":["Nécessite une compréhension des principes de traitement LLM","Des capacités de gestion de contexte sont nécessaires"],"de":["Erfordert das Verständnis der LLM-Verarbeitungsprinzipien","Kontextverwaltungsfähigkeiten sind erforderlich"],"pt":["Exige compreensão dos princípios de processamento LLM","Capacidades de gerenciamento de contexto necessárias"],"ru":["Требует понимания принципов обработки LLM","Необходимы возможности управления контекстом"],"ar":["يتطلب فهم مبادئ معالجة LLM","يحتاج إلى قدرات إدارة السياق"]},"version":4},"contentHash":"d75b1d65a24d948134e5243020117280efe082c11d6928627dad0675af85d405","qualityScore":60}');
