INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('openprose/prose/open-prose', 'open-prose', 'openprose', 'prose', 'community', 'open-prose openprose prose community open-prose is a programming language for AI sessions, allowing LLMs to simulate detailed system descriptions. It benefits developers working with AI agents and large language models. OpenProse 是一种用于 AI 会话的编程语言，允许您创建模拟系统。它使用 npx skills add 命令进行安装 OpenProse は、AI エージェントのためのプログラミング言語です。システムのシミュレーションを作成するために使用されます OpenProse는 AI 에이전트를 위한 프로그래밍 언어입니다. 시스템을 시뮬레이션하는 데 사용됩니다 OpenProse es un lenguaje de programación para sesiones de IA que simula sistemas descritos OpenProse est un langage de programmation pour les sessions d''IA qui simule les systèmes décrits OpenProse ist eine Programmiersprache für KI-Sitzungen, die beschriebene Systeme simuliert OpenProse é uma linguagem de programação para sessões de IA que simula sistemas descritos OpenProse - язык программирования для сессий ИИ Агентов, который симулирует описанные системы OpenProse هي لغة برمجة للعمليات الذكية التي تحاكي الأنظمة الموصوفة how to use open-prose what is open-prose open-prose alternative open-prose vs LLM open-prose install open-prose setup guide open-prose programming language LLM simulators AI session programming OpenProse AI 编程语言 npx skills add 模拟系统 AI 会话 prose.md 远程安装 Installs via npm using the command `npx skills add openprose/prose` Requires a restart of the session after installation Utilizes the `prose.md` file for local system descriptions Simulates detailed system descriptions using LLMs Enables remote installation and setup for AI agents open-prose is a programming language for AI sessions, enabling the simulation of complex systems and behaviors.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('xenitV1/Antigravity-Workflows/mcp-builder', 'community', 'xenitV1', 'Antigravity-Workflows', 'xenitV1/Antigravity-Workflows', 'mcp-builder', 0, 0, 60, '2026-03-08T01:57:15.285Z', '2026-03-08T02:00:56.557Z', 'd13eb1291ed76e0375b43d434e4676e4802264501a48ddeddcc961324133567a', '{"id":"xenitV1/Antigravity-Workflows/mcp-builder","name":"mcp-builder","description":{"en":"mcp-builder is a skill for building MCP servers, enabling AI systems to connect with external tools and data sources. It benefits developers working with Model Context Protocol.","zh":"MCP Builder是一种用于构建MCP服务器的工具，提供Model Context Protocol标准的实现","ja":"MCP Builderは、MCPサーバーを構築するためのツールで、Model Context Protocol標準を実現する","ko":"MCP Builder는 MCP 서버를 구축하기 위한 도구로 Model Context Protocol 표준을 구현합니다","es":"MCP Builder es una herramienta para conectar sistemas de IA con herramientas y fuentes de datos externas. Permite la creación de servidores MCP con una arquitectura de proyecto flexible","fr":"MCP Builder est un outil pour connecter les systèmes d''IA avec des outils et des sources de données externes. Il permet la création de serveurs MCP avec une architecture de projet flexible","de":"MCP Builder ist ein Tool, um KI-Systeme mit externen Tools und Datenquellen zu verbinden. Es ermöglicht die Erstellung von MCP-Servern mit einer flexiblen Projektarchitektur","pt":"O MCP Builder é uma ferramenta para conectar sistemas de IA com ferramentas e fontes de dados externas, utilizando o Protocolo de Contexto de Modelo","ru":"MCP Builder - это инструмент для подключения систем ИИ к внешним инструментам и источникам данных, использующий Протокол контекста модели","ar":"MCP Builder هو أداة لربط أنظمة الذكاء الاصطناعي بأدوات ومصادر بيانات خارجية، باستخدام بروتوكول سياق النموذج"},"seo":{"title":{"en":"mcp-builder: MCP Server Setup Guide | AI Agent Skill","zh":"MCP Builder 