INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('xenitV1/Antigravity-Workflows/mcp-builder', 'mcp-builder', 'xenitV1', 'Antigravity-Workflows', 'community', 'mcp-builder xenitV1 Antigravity-Workflows community mcp-builder is a skill for building MCP servers, enabling AI systems to connect with external tools and data sources. It benefits developers working with Model Context Protocol. MCP Builder是一种用于构建MCP服务器的工具，提供Model Context Protocol标准的实现 MCP Builderは、MCPサーバーを構築するためのツールで、Model Context Protocol標準を実現する MCP Builder는 MCP 서버를 구축하기 위한 도구로 Model Context Protocol 표준을 구현합니다 MCP Builder es una herramienta para conectar sistemas de IA con herramientas y fuentes de datos externas. Permite la creación de servidores MCP con una arquitectura de proyecto flexible MCP Builder est un outil pour connecter les systèmes d''IA avec des outils et des sources de données externes. Il permet la création de serveurs MCP avec une architecture de projet flexible MCP Builder ist ein Tool, um KI-Systeme mit externen Tools und Datenquellen zu verbinden. Es ermöglicht die Erstellung von MCP-Servern mit einer flexiblen Projektarchitektur O MCP Builder é uma ferramenta para conectar sistemas de IA com ferramentas e fontes de dados externas, utilizando o Protocolo de Contexto de Modelo MCP Builder - это инструмент для подключения систем ИИ к внешним инструментам и источникам данных, использующий Протокол контекста модели MCP Builder هو أداة لربط أنظمة الذكاء الاصطناعي بأدوات ومصادر بيانات خارجية، باستخدام بروتوكول سياق النموذج how to use mcp-builder what is mcp-builder mcp-builder alternative mcp-builder vs MCP alternatives mcp-builder install mcp-builder setup guide Model Context Protocol implementation MCP server deployment AI system connectivity with MCP MCP Builder AI工具集成 Model Context Protocol TypeScript 服务器架构 AI解决方案 工具集成 MCP服务器 Implements Model Context Protocol (MCP) for AI system connectivity Utilizes core concepts like Tools, Resources, and Prompts for MCP servers Supports project structure with src/ and index.ts entry point Enables connection to external tools and data sources for AI systems Follows MCP standards for building and deploying MCP servers Provides a framework for working with Prompts, Tools, and Resources in MCP mcp-builder is a skill that implements the Model Context Protocol standard for connecting AI systems with external tools and data sources, utilizing core concepts like Tools, Resources, and Prompts');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('figma/mcp-server-guide/implement-design', 'community', 'figma', 'mcp-server-guide', 'figma/mcp-server-guide', 'implement-design', 0, 0, 60, '2026-03-08T01:57:15.285Z', '2026-03-08T02:00:58.063Z', '8eed282f173196053d3864a69c7fb6d02ea3fc3ad990f1349feba04919f5ccb6', '{"id":"figma/mcp-server-guide/implement-design","name":"implement-design","description":{"en":"The implement-design skill provides a structured workflow for translating Figma designs into production-ready code with pixel-perfect accuracy, ensuring consistent integration with the Figma MCP server.","zh":"本指南介绍如何使用Figma MCP服务器实现设计自动化，确保与设计的1：1视觉一致性","ja":"Figma MCPサーバーを使用してデザインの自動化を実現し、デザインとの1：1視覺一致性を確保する方法を紹介します","ko":"피그마 MCP 서버를 사용하여 디자인 자동화를 구현하고 디자인との 1:1視覺 일치를 달성하는 방법을介绍합니다","es":"Guía para implementar diseños de Figma con precisión de píxel utilizando el servidor Figma MCP y los tokens de diseño","fr":"Guide pour mettre en œuvre des conceptions Figma avec une précision de pixel en utilisant le serveur Figma MCP et les jetons de conception","de":"Leitfaden zur Implementierung von Figma-Designs mit Pixelgenauigkeit mithilfe des Figma-MCP-Servers und der Designtokens","pt":"O Implement Design fornece um fluxo de trabalho estruturado para traduzir designs do Figma em código de produção pronto com precisão pixel-perfeita.","ru":"Реализация дизайна обеспечивает структурированный рабочий процесс для перевода дизайнов Figma в готовый к производству код с точностью до пикселя.","ar":"أداة التصميم توفر تدفق عمل منظم لترجمة تصاميم Figma إلى كود جاهز للانتاج بدقة بكسل مثالية"},"seo":{"title":{"en":"Implement-Design: Figma MCP Server Integration Setup Guid...","zh":"Implement Design Setup Guide - Figma MCP 服务器集成","ja":"Implement Design ベストプラクティス - AIエージェントによるFigma MCPサーバー接続","ko":"Implement Design 구현 가이드 - 피그마 MCP 서버 연동","es":"Implementar Diseño con Figm