INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('figma/mcp-server-guide/implement-design', 'implement-design', 'figma', 'mcp-server-guide', 'community', 'implement-design figma mcp-server-guide community The implement-design skill provides a structured workflow for translating Figma designs into production-ready code with pixel-perfect accuracy, ensuring consistent integration with the Figma MCP server. 本指南介绍如何使用Figma MCP服务器实现设计自动化，确保与设计的1：1视觉一致性 Figma MCPサーバーを使用してデザインの自動化を実現し、デザインとの1：1視覺一致性を確保する方法を紹介します 피그마 MCP 서버를 사용하여 디자인 자동화를 구현하고 디자인との 1:1視覺 일치를 달성하는 방법을介绍합니다 Guía para implementar diseños de Figma con precisión de píxel utilizando el servidor Figma MCP y los tokens de diseño Guide pour mettre en œuvre des conceptions Figma avec une précision de pixel en utilisant le serveur Figma MCP et les jetons de conception Leitfaden zur Implementierung von Figma-Designs mit Pixelgenauigkeit mithilfe des Figma-MCP-Servers und der Designtokens O Implement Design fornece um fluxo de trabalho estruturado para traduzir designs do Figma em código de produção pronto com precisão pixel-perfeita. Реализация дизайна обеспечивает структурированный рабочий процесс для перевода дизайнов Figma в готовый к производству код с точностью до пикселя. أداة التصميم توفر تدفق عمل منظم لترجمة تصاميم Figma إلى كود جاهز للانتاج بدقة بكسل مثالية how to use implement-design implement-design Figma MCP server integration what is implement-design implement-design alternative implement-design setup guide Figma MCP server tutorial Figma MCP服务器 设计自动化 AIエージェント 设计tokens get_design_context 视觉一致性 Implement Design Figma MCP工具 Connects to the Figma MCP server for design data access Utilizes design tokens for consistent design implementation Ensures 1:1 visual parity with Figma designs Verifies Figma MCP server connection using tools like get_design_context Provides a structured workflow for design implementation Implement-design is a skill that enables the translation of Figma designs into production-ready code with pixel-perfect accuracy using the Figma MCP server.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('w-winter/dot314/surf', 'community', 'w-winter', 'dot314', 'w-winter/dot314', 'surf', 0, 0, 60, '2026-03-08T01:57:15.286Z', '2026-03-08T02:00:58.271Z', '330269cfd8fb4f018210dae7670dc04beaf2ba7a8ff98d45ee63abc0720f1ed8', '{"id":"w-winter/dot314/surf","name":"surf","description":{"en":"The surf skill provides extensions, commands, and themes for Pi, enabling developers to automate Chrome browser tasks via CLI or Unix socket. This skill benefits developers seeking efficient browser automation.","zh":"Surf是一种浏览器自动化控制工具，支持CLI和Unix socket。它提供了方便的命令行工具来控制Chrome浏览器","ja":"Surfはブラウザ自動化コントロールツールで、CLIとUnix socketをサポートしています。Chromeブラウザを制御するための便利なコマンドラインツールを提供します","ko":"Surf는 브라우저 자동화 제어 도구로, CLI와 Unix socket를 지원합니다. Chrome 브라우저를 제어하기 위한 편리한 명령줄 도구를 제공합니다","es":"Surf es una herramienta de automatización de navegador que permite controlar Chrome via CLI o socket de Unix","fr":"Surf est un outil d''automatisation de navigateur qui permet de contrôler Chrome via CLI ou socket Unix","de":"Surf ist ein Werkzeug für die Automatisierung von Browsern, das die Steuerung von Chrome über CLI oder Unix-Socket ermöglicht","pt":"O Surf é uma ferramenta de automação de navegador que permite controlar o Chrome via CLI ou soquete Unix. Ele oferece comandos para navegação, espera, diálogo e emulação.","ru":"Surf - это инструмент для автоматизации браузера, который позволяет контролировать Chrome через CLI или Unix-сокет. Он предлагает команды для навигации, ожидания, диалога и эмуляции.","ar":"Surf هو أداة آليّة لمتصفح يسمح بالتحكم في كروم عبر واجهة سطر الأوامر أو сокيت يونكس. يقدم أوامر للتنقل، الانتظار، الحوار والمحاكاة."},"seo":{"title":{"en":"surf: Browser Automation Control Setup Guide | AI Agent S...","zh":"Surf 浏览器自动化控制指南","ja":"Surf ブラウザ自動化コントロールセットアップガイド","ko":"Surf 브라우저 자동화 제어 설정 가이드","es":"Guía de configuración de Surf para automatización de nave...","fr":"Guide de mise en route de Surf pour l''automatisation du n...","de":"Surf-Einrichtungsleitfaden für Browser-Automatisierung","pt":"Guia de Configuração do Surf: Automação de Navegador","ru":"Настройка Surf: Автоматизация браузера Chrome","ar":"دليل إعداد Surf: آليّة متصفح كروم"},"description":{"en":"Unlock the full potential of surf browser automation. Learn how to control Chrome via CLI or Unix socket and discover expert tips for seamless integration.","zh":"了解Surf浏览器自动化控制，包括CLI和Unix socket的使用方法","ja":"Surfブラウザ自動化コントロールの使い方を紹介。CLIとUnix socketの使用方法を学ぶ","ko":"Surf 브라우저 자동화 제어의 기능과 사용方法을 알아보세요. CLI와 Unix socket의 사용법을 포함합니다","es":"Aprende a controlar Chrome via CLI o socket de Unix con Surf, una herramienta de automatización de navegador","fr":"Découvrez comment contrôler Chrome via CLI ou socket Unix avec Surf, un outil d''automatisation de navigateur","de":"Erfahren Sie, wie Sie Chrome über CLI oder Unix-Socket mit Surf steuern, einem Werkzeug für die Automatisierung von Browsern","pt":"Aprenda a controlar o navegador Chrome via CLI ou soquete Unix com o Surf. Descubra os comandos e recursos para automação de navegador.","ru":"Узнайте, как контролировать браузер Chrome через CLI или Unix-сокет с помощью Surf. Откройте для себя команды и возможности для автоматизации браузера.","ar":"تعرف على كيفية التحكم في متصفح كروم عبر واجهة سطر الأوامر أو сокيت يونكس مع Surf. اكتشف الأوامر والخصائص لآليّة المتصفح."},"definition":{"en":"surf is a browser automation tool that allows control of Chrome via CLI or Unix socket, providing various commands and features for efficient browser management.","zh":"Surf是一种浏览器自动化控制工具，用于控制Chrome浏览器","ja":"Surfは、Chromeブラウザを制御するためのブラウザ自動化コントロールツールです","ko":"Surf는 Chrome 브라우저를 제어하기 위한 브라우저 자동화 제어 도구입니다","es":"Surf es una herramienta de automatización de navegador que permite controlar Chrome","fr":"Surf est un outil d''automatisation de navigateur qui permet de contrôler Chrome","de":"Surf ist ein Werkzeug für die Automatisierung von Browsern, das die Steuerung von Chrome ermöglicht","pt":"O Surf é uma ferramenta de automação de navegador que permite controlar o Chrome via CLI ou soquete Unix.","ru":"Surf - это инструмент для автоматизации браузера, который позволяет контролировать Chrome через CLI или Unix-сокет.","ar":"Surf هو أداة آليّة لمتصفح يسمح بالتحكم في كروم عبر واجهة سطر الأوامر أو сокيت يونكس."},"features":{"en":["CLI Quick Reference for easy command access","Supports Unix socket for programmatic browser control","Provides `surf navigate` command for page navigation","Offers `surf --help-full` command for comprehensive documentation","Includes `surf --find` command for searching tools and topics","Enables topic guides with `surf --help-topic` command"],"zh":["支持CLI和Unix socket","提供方便的命令行工具来控制Chrome浏览器","支持导航、滚动、等待和对话框等功能","支持性能优化和人工智能功能","提供全面的帮助文档和主题指南"],"ja":["CLIとUnix socketをサポート","Chromeブラウザを制御するための便利なコマンドラインツールを提供","ナビゲーション、スクロール、待機とダイアログボックス等の機能をサポート","パフォーマンス最適化と人工知能機能をサポート","包括的なヘルプドキュメントとトピックガイドを提供"],"ko":["CLI와 Unix socket를 지원","Chrome 브라우저를 제어하기 위한 편리한 명령줄 도구를 제공","导航、滚动、等待和对话框等功能을 지원","성능 최적화와 인공지능 기능을 지원","포괄적인 도움말 문서와 주제 가이드를 제공"],"es":["Control de Chrome via CLI o socket de Unix","Comandos para navegar, esperar y emular","Búsqueda de herramientas con surf --find","Guía de temas con surf --help-topic","Soporte para grupos de comandos"],"fr":["Contrôle de Chrome via CLI ou socket Unix","Commandes pour naviguer, attendre et émuler","Recherche d''outils avec surf --find","Guide de sujets avec surf --help-topic","Prise en charge de groupes de commandes"],"de":["Steuerung von Chrome über CLI oder Unix-Socket","Befehle zum Navigieren, Warten und Emulieren","Suche nach Werkzeugen mit surf --find","Themenführer mit surf --help-topic","Unterstützung für Befehlsgruppen"],"pt":["Controle do navegador Chrome via CLI ou soquete Unix","Comandos para navegação, espera, diálogo e emulação","Suporte a busca de ferramentas com `surf --find`","Guia de tópicos com `surf --help-topic`","Suporte a emulação de dispositivos e janelas"],"ru":["Контроль браузера Chrome через CLI или Unix-сокет","Команды для навигации, ожидания, диалога и эмуляции","Поддержка поиска инструментов с `surf --find`","Руководство по темам с `surf --help-topic`","Поддержка эмуляции устройств и окон"],"ar":["التحكم في متصفح كروم عبر واجهة سطر الأوامر أو сокيت يونكس","أوامر للتنقل، الانتظار، الحوار والمحاكاة","دعم البحث عن أدوات مع `surf --find`","دليل المواضيع مع `surf --help-topic`","دعم محاكاة الأجهزة والنوافذ"]},"keywords":{"en":["how to use surf","surf alternative","surf browser automation","surf setup guide","surf vs puppeteer","what is surf","surf install","surf cli commands","surf unix socket","surf chrome automation"],"zh":["Surf浏览器自动化控制","CLI和Unix socket","Chrome浏览器控制","浏览器自动化工具","AIエージェント","浏览器性能优化","人工智能功能"],"ja":["Surfブラウザ自動化コントロール","CLIとUnix socket","Chromeブラウザ制御","ブラウザ自動化ツール","AIエージェント","ブラウザパフォーマンス最適化","人工知能機能"],"ko":["Surf 브라우저 자동화 제어","CLI와 Unix socket","Chrome 브라우저 제어","브라우저 자동화 도구","AI 에이전트","브라우저 성능 최적화","인공지능 기능"],"es":["automatización de navegador","control de Chrome","CLI","socket de Unix","herramientas de desarrollo","surf","agentes de IA","herramientas de automatización"],"fr":["automatisation de navigateur","contrôle de Chrome","CLI","socket Unix","outils de développement","surf","agents d''IA","outils d''automatisation"],"de":["Automatisierung von Browsern","Steuerung von Chrome","CLI","Unix-Socket","Entwicklungstools","surf","KI-Agents","Automatisierungstools"],"pt":["automação de navegador","Surf","CLI","soquete Unix","navegação","espera","diálogo","emulação","busca de ferramentas","guia de tópicos"],"ru":["автоматизация браузера","Surf","CLI","Unix-сокет","навигация","ожидание","диалог","эмуляция","поиск инструментов","руководство по темам"],"ar":["آليّة متصفح","Surf","واجهة سطر الأوامر","сокيت يونكس","التنقل","الانتظار","الحوار","المحاكاة","بحث أدوات","دليل المواضيع"]}},"owner":"w-winter","repo":"dot314","repoPath":"w-winter/dot314","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.286Z","topics":[],"category":"community","skillMd":{"name":"surf","description":"Control Chrome browser via CLI for testing, automation, and debugging. Use when the user needs browser automation, screenshots, form filling, page inspection, network/CPU emulation, DevTools streaming, or AI queries via ChatGPT/Gemini/Perplexity/Grok/AI Studio.","bodyPreview":"# Surf Browser Automation\n\nControl Chrome browser via CLI or Unix socket.\n\n## CLI Quick Reference\n\n```bash\nsurf --help                    # Full help\nsurf <group>                   # Group help (tab, scroll, page, wait, dialog, emulate, form, perf, ai)\nsurf --help-full               # All commands\nsurf --find <term>             # Search tools\nsurf --help-topic <topic>      # Topic guide (refs, semantic, frames, devices, windows)\n```\n\n## Core Workflow\n\n```bash\n# 1. Navigate to page\nsurf navigate","body":"# Surf Browser Automation\n\nControl Chrome browser via CLI or Unix socket.\n\n## CLI Quick Reference\n\n```bash\nsurf --help                    # Full help\nsurf <group>                   # Group help (tab, scroll, page, wait, dialog, emulate, form, perf, ai)\nsurf --help-full               # All commands\nsurf --find <term>             # Search tools\nsurf --help-topic <topic>      # Topic guide (refs, semantic, frames, devices, windows)\n```\n\n## Core Workflow\n\n```bash\n# 1. Navigate to page\nsurf navigate \"https://example.com\"\n\n# 2. Read page to get element refs\nsurf page.read\n\n# 3. Click by ref or coordinates\nsurf click --ref \"e1\"\nsurf click --x 100 --y 200\n\n# 4. Type text\nsurf type --text \"hello\"\n\n# 5. Screenshot\nsurf screenshot --output /tmp/shot.png\n```\n\n## AI Assistants (No API Keys)\n\nQuery AI models using your browser''s logged-in session. Must be logged into the respective service in Chrome.\n\n### ChatGPT\n```bash\nsurf chatgpt \"explain this code\"\nsurf chatgpt \"summarize\" --with-page              # Include current page context\nsurf chatgpt \"review\" --model gpt-4o              # Specify model\nsurf chatgpt \"analyze\" --file document.pdf        # With file attachment\n```\n\n### Gemini\n```bash\nsurf gemini \"explain quantum computing\"\nsurf gemini \"summarize\" --with-page               # Include page context\nsurf gemini \"analyze\" --file data.csv             # Attach file\nsurf gemini \"a robot surfing\" --generate-image /tmp/robot.png\nsurf gemini \"add sunglasses\" --edit-image photo.jpg --output out.jpg\nsurf gemini \"summarize\" --youtube \"https://youtube.com/...\"\nsurf gemini \"hello\" --model gemini-2.5-flash      # Models: gemini-3-pro (default), gemini-2.5-pro, gemini-2.5-flash\nsurf gemini \"wide banner\" --generate-image /tmp/banner.png --aspect-ratio 16:9\n```\n\n### Perplexity\n```bash\nsurf perplexity \"what is quantum computing\"\nsurf perplexity \"explain this page\" --with-page   # Include page context\nsurf perplexity \"deep dive\" --mode research       # Research mode (Pro)\nsurf perplexity \"latest news\" --model sonar       # Model selection (Pro)\n```\n\n### Grok (via x.com - requires X.com login in Chrome)\n```bash\nsurf grok \"what are the latest AI trends on X\"    # Search X posts\nsurf grok \"analyze @username recent activity\"     # Profile analysis  \nsurf grok \"summarize this page\" --with-page       # Include page context\nsurf grok \"find viral AI posts\" --deep-search     # DeepSearch mode\nsurf grok \"quick question\" --model fast           # Models: auto, fast, expert, thinking (default)\n```\n\n**Grok Validation & Troubleshooting:**\n```bash\n# Validate Grok UI and check available models (no query sent)\nsurf grok --validate\n\n# If models changed, save discovered models to surf.json config\nsurf grok --validate --save-models\n```\n\n### AI Studio (via aistudio.google.com - requires Google login in Chrome)\n```bash\nsurf aistudio \"explain quantum computing\"\nsurf aistudio \"redteam this\" --with-page          # Include current page context\nsurf aistudio \"quick answer\" --model gemini-3-flash-preview  # Model selection\nsurf aistudio \"analyze\" --timeout 600             # Custom timeout (default: 300s)\n```\n\n**Why AI Studio over Gemini?** AI Studio gives access to less restricted Gemini models. For Gemini 3 Pro the difference can be significant with certain prompts. Downside: aggressive per-day rate limits on Pro and Flash models.\n\n**Model selection is best-effort:** Pass any AI Studio model id (e.g. `gemini-3.1-pro-preview`, `gemini-3-flash-preview`, `gemini-flash-lite-latest`). If the model isn''t found, AI Studio uses whatever model was last selected in the UI.\n\n### AI Studio App Builder\n```bash\nsurf aistudio.build \"build a portfolio site\"\nsurf aistudio.build \"todo app\" --model gemini-3.1-pro-preview   # Model override\nsurf aistudio.build \"crm dashboard\" --output ./out              # Extract zip to directory\nsurf aistudio.build \"game\" --keep-open --timeout 600            # Keep tab open, 10min timeout\n```\n\nAutomates AI Studio''s App Builder at `aistudio.google.com/apps`. Types your prompt, clicks Build, waits for completion, downloads the generated zip, and optionally extracts it.\n\n- `--output <dir>` extracts the zip to a directory\n- `--model <id>` overrides the model in Advanced Settings\n- `--timeout <seconds>` build timeout (default: 600s)\n- `--keep-open` leaves the AI Studio tab open after completion\n\nReturns `zipPath`, `extractedPath`, `model`, `buildDuration`, and `tookMs`.\n\n### AI Tool Troubleshooting\n\nWhen AI queries fail, check these common issues:\n\n1. **Not logged in**: The error \"login required\" means you need to log into the service in Chrome (chatgpt.com, gemini.google.com, perplexity.ai, x.com, or aistudio.google.com)\n2. **Model selection failed**: The UI may have changed. Run `surf grok --validate` to check\n3. **Response timeout**: Thinking models (ChatGPT o1, Grok thinking) can take 45+ seconds. AI Studio builds can take several minutes.\n4. **Element not found**: The service''s UI changed. Check for surf-cli updates\n\n**Debugging workflow for agents:**\n```bash\n# 1. Check if the service is accessible and UI is valid\nsurf grok --validate\n\n# 2. If models mismatch, update the local settings\nsurf grok --validate --save-models\n\n# 3. Retry with explicit model name from validation output\nsurf grok \"query\" --model <model-from-validation>\n\n# 4. If still failing, try with longer timeout\nsurf grok \"query\" --timeout 600\n```\n\n## Tab Management\n\n```bash\nsurf tab.list\nsurf tab.new \"https://google.com\"\nsurf tab.switch 12345\nsurf tab.close 12345\nsurf tab.reload                # Reload current tab\n\n# Named tabs (aliases)\nsurf tab.name myapp            # Name current tab\nsurf tab.switch myapp          # Switch by name\nsurf tab.named                 # List named tabs\nsurf tab.unname myapp          # Remove name\n\n# Tab groups\nsurf tab.group                 # Create/add to tab group\nsurf tab.ungroup               # Remove from group\nsurf tab.groups                # List all tab groups\n```\n\n## Window Management\n\n```bash\nsurf window.list                              # List all windows\nsurf window.list --tabs                       # Include tab details\nsurf window.new                               # New window\nsurf window.new --url \"https://example.com\"   # New window with URL\nsurf window.new --incognito                   # New incognito window\nsurf window.new --unfocused                   # Don''t focus new window\nsurf window.focus 12345                       # Focus window by ID\nsurf window.close 12345                       # Close window\nsurf window.resize --id 123 --width 1920 --height 1080\nsurf window.resize --id 123 --state maximized # States: normal, minimized, maximized, fullscreen\n```\n\n**Window isolation for agents:**\n```bash\n# Create isolated window for agent work\nsurf window.new \"https://example.com\"\n# Returns window ID, use with subsequent commands:\nsurf --window-id 123 tab.list\nsurf --window-id 123 go \"https://other.com\"\n```\n\n## Input Methods\n\n```bash\n# CDP method (real events) - default\nsurf type --text \"hello\"\nsurf click --x 100 --y 200\n\n# JS method (DOM manipulation) - for contenteditable\nsurf type --text \"hello\" --selector \"#input\" --method js\n\n# Keys\nsurf key Enter\nsurf key \"cmd+a\"\nsurf key.repeat --key Tab --count 5           # Repeat key presses\n\n# Hover and drag\nsurf hover --ref e5\nsurf drag --from-x 100 --from-y 100 --to-x 200 --to-y 200\n```\n\n## Page Inspection\n\n```bash\nsurf page.read                 # Accessibility tree with refs + page text\nsurf page.read --no-text       # Interactive elements only (no text content)\nsurf page.read --ref e5        # Get specific element details\nsurf page.read --depth 3       # Limit tree depth\nsurf page.read --compact       # Minimal output for LLM efficiency\nsurf page.text                 # Plain text content only\nsurf page.state                # Modals, loading state, scroll info\n```\n\n## Semantic Element Location\n\nFind and act on elements by role, text, or label instead of refs:\n\n```bash\n# Find by ARIA role\nsurf locate.role button --name \"Submit\" --action click\nsurf locate.role textbox --name \"Email\" --action fill --value \"test@example.com\"\nsurf locate.role link --all                    # Return all matches\n\n# Find by text content\nsurf locate.text \"Sign In\" --action click\nsurf locate.text \"Accept\" --exact --action click\n\n# Find form field by label\nsurf locate.label \"Username\" --action fill --value \"john\"\nsurf locate.label \"Password\" --action fill --value \"secret\"\n```\n\n**Actions:** `click`, `fill`, `hover`, `text` (get text content)\n\n## Text Search\n\n```bash\nsurf search \"login\"                    # Find text in page\nsurf search \"Error\" --case-sensitive   # Case-sensitive\nsurf search \"button\" --limit 5         # Limit results\nsurf find \"login\"                      # Alias for search\n```\n\n## Element Inspection\n\n```bash\nsurf element.styles e5                 # Get computed styles by ref\nsurf element.styles \".card\"            # Or by CSS selector\n# Returns: font, color, background, border, padding, bounding box\n```\n\n## Scrolling\n\n```bash\nsurf scroll.bottom\nsurf scroll.top  \nsurf scroll.to --y 500         # Scroll to Y position\nsurf scroll.to --ref e5        # Scroll element into view\nsurf scroll.by --y 200         # Scroll by amount\nsurf scroll.info               # Get scroll position\n```\n\n## Waiting\n\n```bash\nsurf wait 2                    # Wait 2 seconds\nsurf wait.element \".loaded\"    # Wait for element\nsurf wait.network              # Wait for network idle\nsurf wait.url \"/success\"       # Wait for URL pattern\nsurf wait.dom --stable 100     # Wait for DOM stability\nsurf wait.load                 # Wait for page load complete\n```\n\n## Dialog Handling\n\n```bash\nsurf dialog.info               # Get current dialog type/message\nsurf dialog.accept             # Accept (OK)\nsurf dialog.accept --text \"response\"  # Accept prompt with text\nsurf dialog.dismiss            # Dismiss (Cancel)\n```\n\n## Device/Network Emulation\n\n```bash\n# Network throttling\nsurf emulate.network slow-3g   # Presets: slow-3g, fast-3g, 4g, offline\nsurf emulate.network reset     # Disable throttling\n\n# CPU throttling  \nsurf emulate.cpu 4             # 4x slower\nsurf emulate.cpu 1             # Reset\n\n# Device emulation (19 presets)\nsurf emulate.device \"iPhone 14\"\nsurf emulate.device \"Pixel 7\"\nsurf emulate.device --list     # List available devices\n\n# Custom viewport\nsurf emulate.viewport --width 1280 --height 720\nsurf emulate.touch --enable    # Enable touch emulation\n\n# Geolocation\nsurf emulate.geo --lat 37.7749 --lon -122.4194\nsurf emulate.geo --clear\n```\n\n## Form Automation\n\n```bash\nsurf page.read                 # Get element refs first\n\n# Fill by ref\nsurf form.fill --data ''[{\"ref\":\"e1\",\"value\":\"John\"},{\"ref\":\"e2\",\"value\":\"john@example.com\"}]''\n\n# Checkboxes: true/false\nsurf form.fill --data ''[{\"ref\":\"e7\",\"value\":true}]''\n\n# Dropdown selection\nsurf select e5 \"Option A\"                    # By value (default)\nsurf select e5 \"Option A\" \"Option B\"         # Multi-select\nsurf select e5 --by label \"Display Text\"     # By visible label\nsurf select e5 --by index 2                  # By index (0-based)\n```\n\n## File Upload\n\n```bash\nsurf upload --ref e5 --files \"/path/to/file.txt\"\nsurf upload --ref e5 --files \"/path/file1.txt,/path/file2.txt\"\n```\n\n## Iframe Handling\n\n```bash\nsurf frame.list                # List frames with IDs\nsurf frame.switch \"FRAME_ID\"   # Switch to iframe context\nsurf frame.main                # Return to main frame\nsurf frame.js --id \"FRAME_ID\" --code \"return document.title\"\n\n# After frame.switch, subsequent commands target that frame:\nsurf frame.switch \"iframe-1\"\nsurf page.read                 # Reads iframe content\nsurf click e5                  # Clicks in iframe\nsurf frame.main                # Back to main page\n```\n\n## Network Inspection\n\n```bash\nsurf network                   # List captured requests\nsurf network --stream          # Real-time network events\nsurf network.get --id \"req-123\"   # Full request details\nsurf network.body --id \"req-123\"  # Get response body\nsurf network.curl --id \"req-123\"  # Generate curl command\nsurf network.origins           # List origins with stats\nsurf network.stats             # Capture statistics\nsurf network.export            # Export all requests\nsurf network.clear             # Clear captured requests\n```\n\n## Console\n\n```bash\nsurf console                   # Get console messages\nsurf console --stream          # Real-time console\nsurf console --stream --level error  # Errors only\n```\n\n## JavaScript Execution\n\n```bash\nsurf js \"return document.title\"\nsurf js \"document.querySelector(''.btn'').click()\"\n```\n\n## Performance\n\n```bash\nsurf perf.metrics              # Current metrics snapshot\nsurf perf.start                # Start trace\nsurf perf.stop                 # Stop and get results\n```\n\n## Screenshots\n\n```bash\nsurf screenshot                           # Auto-saves to /tmp/surf-snap-*.png\nsurf screenshot --output /tmp/shot.png    # Save to specific file\nsurf screenshot --selector \".card\"        # Element only\nsurf screenshot --full-page               # Full page scroll capture\nsurf screenshot --no-save                 # Return base64 only, don''t save file\n```\n\n## Zoom\n\n```bash\nsurf zoom                      # Get current zoom level\nsurf zoom 1.5                  # Set zoom to 150%\nsurf zoom 1                    # Reset to 100%\n```\n\n## Cookies & Storage\n\n```bash\nsurf cookie.list               # List cookies for current page\nsurf cookie.list --domain .google.com\nsurf cookie.set --name \"token\" --value \"abc123\"\nsurf cookie.get --name \"token\"\nsurf cookie.clear              # Clear all cookies\n```\n\n## History & Bookmarks\n\n```bash\nsurf history --query \"github\" --max 20\nsurf bookmarks --query \"docs\"\nsurf bookmark.add --url \"https://...\" --title \"My Bookmark\"\nsurf bookmark.remove\n```\n\n## Health Checks & Smoke Tests\n\n```bash\nsurf health --url \"http://localhost:3000\"\nsurf smoke --urls \"http://localhost:3000\" \"http://localhost:3000/about\"\nsurf smoke --urls \"...\" --screenshot /tmp/smoke\n```\n\n## Workflows\n\nExecute multi-step browser automation as a single command with smart auto-waits.\n\n### Inline Workflows\n\n```bash\n# Pipe-separated commands\nsurf do ''go \"https://example.com\" | click e5 | screenshot''\n\n# Multi-step login flow\nsurf do ''go \"https://example.com/login\" | type \"user@example.com\" --selector \"#email\" | type \"pass\" --selector \"#password\" | click --selector \"button[type=submit]\"''\n\n# Validate without executing\nsurf do ''go \"url\" | click e5'' --dry-run\n```\n\n### Named Workflows\n\nSave workflows as JSON files in `~/.surf/workflows/` (user) or `./.surf/workflows/` (project):\n\n```bash\n# List available workflows\nsurf workflow.list\n\n# Show workflow details\nsurf workflow.info my-workflow\n\n# Run by name with arguments\nsurf do my-workflow --email \"user@example.com\" --password \"secret\"\n\n# Validate workflow file\nsurf workflow.validate workflow.json\n```\n\n### Workflow JSON Format\n\n```json\n{\n  \"name\": \"Login Flow\",\n  \"description\": \"Automate login process\",\n  \"args\": {\n    \"email\": { \"required\": true },\n    \"password\": { \"required\": true },\n    \"url\": { \"default\": \"https://example.com/login\" }\n  },\n  \"steps\": [\n    { \"tool\": \"navigate\", \"args\": { \"url\": \"%{url}\" } },\n    { \"tool\": \"type\", \"args\": { \"text\": \"%{email}\", \"selector\": \"input[name=email]\" } },\n    { \"tool\": \"type\", \"args\": { \"text\": \"%{password}\", \"selector\": \"input[name=password]\" } },\n    { \"tool\": \"click\", \"args\": { \"selector\": \"button[type=submit]\" } },\n    { \"tool\": \"screenshot\", \"args\": {}, \"as\": \"result\" }\n  ]\n}\n```\n\n### Loops and Step Outputs\n\n```json\n{\n  \"steps\": [\n    // Capture step output for later use\n    { \"tool\": \"js\", \"args\": { \"code\": \"return [1,2,3]\" }, \"as\": \"items\" },\n    \n    // Fixed iterations\n    { \"repeat\": 5, \"steps\": [\n      { \"tool\": \"click\", \"args\": { \"ref\": \"e5\" } }\n    ]},\n    \n    // Iterate over array\n    { \"each\": \"%{items}\", \"as\": \"item\", \"steps\": [\n      { \"tool\": \"js\", \"args\": { \"code\": \"console.log(''%{item}'')\" } }\n    ]},\n    \n    // Repeat until condition\n    { \"repeat\": 20, \"until\": { \"tool\": \"js\", \"args\": { \"code\": \"return done\" } }, \"steps\": [...] }\n  ]\n}\n```\n\n### Workflow Options\n\n```bash\n--file, -f <path>     # Load from JSON file\n--dry-run             # Parse and validate without executing\n--on-error stop|continue  # Error handling (default: stop)\n--step-delay <ms>     # Delay between steps (default: 100, 0 to disable)\n--no-auto-wait        # Disable automatic waits\n--json                # Structured JSON output\n```\n\n**Auto-waits:** Commands automatically wait for completion:\n- Navigation (`go`, `back`, `forward`) → waits for page load\n- Clicks, key presses, form fills → waits for DOM stability\n- Tab switches → waits for tab to load\n\n**Why use `do`?** Instead of 6-8 separate CLI calls with LLM orchestration between each, a workflow executes deterministically. Faster, cheaper, and more reliable.\n\n## Error Diagnostics\n\n```bash\n# Auto-capture screenshot + console on failure\nsurf wait.element \".missing\" --auto-capture --timeout 2000\n# Saves to /tmp/surf-error-*.png\n```\n\n## Common Options\n\n```bash\n--tab-id <id>         # Target specific tab\n--window-id <id>      # Target specific window\n--json                # Raw JSON output  \n--auto-capture        # Screenshot + console on error\n--timeout <ms>        # Override default timeout\n```\n\n## Tips\n\n1. **First CDP operation is slow** (~5-8s) - debugger attachment overhead, subsequent calls fast\n2. **Use refs from page.read** for reliable element targeting over CSS selectors\n3. **JS method for contenteditable** - Modern editors (ChatGPT, Claude, Notion) need `--method js`\n4. **Named tabs for workflows** - `tab.name app` then `tab.switch app`\n5. **Auto-capture for debugging** - `--auto-capture` saves diagnostics on failure\n6. **AI tools use browser session** - Must be logged into the service (ChatGPT, Gemini, Perplexity, Grok, AI Studio), no API keys needed\n7. **Grok validation** - Run `surf grok --validate` if queries fail to check UI changes\n8. **Long timeouts for thinking models** - ChatGPT o1, Grok thinking can take 60+ seconds. AI Studio builds default to 600s.\n9. **AI Studio for unrestricted Gemini** - `surf aistudio` gives less filtered responses than `surf gemini` for the same models\n10. **Use `surf do` for multi-step tasks** - Reduces token overhead and improves reliability\n11. **Dry-run workflows first** - `surf do ''...'' --dry-run` validates without executing\n12. **Window isolation** - Use `window.new` + `--window-id` to keep agent work separate from your browsing\n13. **Semantic locators** - `locate.role`, `locate.text`, `locate.label` for more robust element finding\n14. **Frame context** - Use `frame.switch` before interacting with iframe content\n\n## Socket API\n\nFor programmatic access:\n\n```bash\necho ''{\"type\":\"tool_request\",\"method\":\"execute_tool\",\"params\":{\"tool\":\"tab.list\",\"args\":{}},\"id\":\"1\"}'' | nc -U /tmp/surf.sock\n```\n"},"lastSynced":"2026-03-08T02:00:58.271Z","agentAnalysis":{"suitability":{"en":"Perfect for Automation Agents needing efficient Chrome browser control via CLI or Unix socket.","zh":"适用于需要通过CLI或Unix套接字高效控制Chrome浏览器的自动化代理。","ja":"CLIまたはUnixソケット経由でChromeブラウザを効率的に制御する必要がある自動化エージェントに最適です。","ko":"CLI 또는 Unix 소켓을 통해 Chrome 브라우저를 효율적으로 제어해야 하는 자동화 에이전트에 적합합니다.","es":"Perfecto para Agentes de Automatización que necesitan un control eficiente del navegador Chrome a través de CLI o socket de Unix.","fr":"Parfait pour les Agents d''Automatisation ayant besoin d''un contrôle efficace du navigateur Chrome via CLI ou socket Unix.","de":"Perfekt für Automatisierungsagenten, die eine effiziente Steuerung des Chrome-Browsers über CLI oder Unix-Socket benötigen.","pt":"Perfeito para Agentes de Automação que necessitam de controle eficiente do navegador Chrome via CLI ou soquete Unix.","ru":"Идеально подходит для агентов автоматизации, требующих эффективного управления браузером Chrome через CLI или сокет Unix.","ar":"مثالي للوكلاء الآليين الذين يحتاجون إلى التحكم الفعال في متصفح Chrome عبر CLI أو منفذ Unix."},"recommendation":{"en":"Empowers agents to automate Chrome browser tasks using Unix socket or CLI commands, enabling efficient browser automation with features like navigation, tab management, and dialog handling via protocols and tools.","zh":"赋予代理自动化Chrome浏览器任务的能力，使用Unix套接字或CLI命令，实现高效的浏览器自动化，具有导航、标签管理和对话框处理等功能。","ja":"エージェントにChromeブラウザのタスクを自動化する能力を与え、UnixソケットまたはCLIコマンドを使用して、ナビゲーション、タブ管理、ダイアログハンドリングなどの機能を備えた効率的なブラウザ自動化を実現します。","ko":"에이전트에 Chrome 브라우저 작업을 자동화할 수 있는 능력을 부여하여 Unix 소켓 또는 CLI 명령을 사용하여 탐색, 탭 관리, 대화 상자 처리 등의 기능을 갖춘 효율적인 브라우저 자동화를实现합니다.","es":"Habilita a los agentes a automatizar tareas del navegador Chrome utilizando socket de Unix o comandos de CLI, lo que permite una automatización eficiente del navegador con características como la navegación, la gestión de pestañas y el manejo de diálogos a través de protocolos y herramientas.","fr":"Permet aux agents d''automatiser les tâches du navigateur Chrome en utilisant le socket Unix ou les commandes CLI, permettant ainsi une automation efficace du navigateur avec des fonctionnalités comme la navigation, la gestion des onglets et la gestion des dialogues via des protocoles et des outils.","de":"Ermächtigt die Agenten, Aufgaben des Chrome-Browsers zu automatisieren, indem sie Unix-Sockets oder CLI-Befehle verwenden, wodurch eine effiziente Automation des Browsers mit Funktionen wie Navigation, Tab-Verwaltung und Dialogverwaltung über Protokolle und Tools ermöglicht wird.","pt":"Habilita os agentes a automatizar tarefas do navegador Chrome usando soquete Unix ou comandos CLI, permitindo automação de navegador eficiente com recursos como navegação, gerenciamento de guias e tratamento de diálogos via protocolos e ferramentas.","ru":"Наделяет агентов возможностью автоматизировать задачи браузера Chrome с помощью сокета Unix или команд CLI, обеспечивая эффективную автоматизацию браузера с функциями như навигация, управление вкладками и обработка диалогов через протоколы и инструменты.","ar":"يُمنح الوكلاء القدرة على ت 자동化 مهام متصفح Chrome باستخدام منفذ Unix أو أوامر CLI، مما يتيح Automatization فعالة للمتصفح مع ميزات مثل التنقل وإدارة علامات التبويب ومعالجة الحوارات عبر البروتوكولات والأدوات."},"useCases":{"en":["Automating browser navigation and interaction","Controlling Chrome browser tabs and windows via CLI","Debugging browser-based applications using Unix socket"],"zh":["自动化浏览器导航和交互","通过CLI控制Chrome浏览器标签和窗口","使用Unix套接字调试基于浏览器的应用程序"],"ja":["ブラウザのナビゲーションとインタラクションの自動化","CLIを使用してChromeブラウザのタブとウィンドウを制御する","Unixソケットを使用してブラウザベースのアプリケーションをデバッグする"],"ko":["브라우저 탐색 및 상호작용 자동화","CLI를 사용하여 Chrome 브라우저 탭 및 창 제어","Unix 소켓을 사용하여 브라우저 기반 애플리케이션 디버깅"],"es":["Automatizar la navegación y la interacción del navegador","Controlar las pestañas y ventanas del navegador Chrome a través de CLI","Depurar aplicaciones basadas en navegador mediante socket de Unix"],"fr":["Automatiser la navigation et l''interaction du navigateur","Contrôler les onglets et les fenêtres du navigateur Chrome via CLI","Déboguer les applications basées sur le navigateur en utilisant le socket Unix"],"de":["Automatisieren der Browser-Navigation und -Interaktion","Steuerung der Chrome-Browser-Registerkarten und -Fenster über CLI","Debuggen von browserbasierten Anwendungen mithilfe von Unix-Sockets"],"pt":["Automatizar navegação e interação do navegador","Controlar guias e janelas do navegador Chrome via CLI","Depurar aplicativos baseados em navegador usando soquete Unix"],"ru":["Автоматизировать навигацию и взаимодействие браузера","Управлять вкладками и окнами браузера Chrome через CLI","Отлаживать приложения на основе браузера с помощью сокета Unix"],"ar":["تأتمتة التنقل والتتفاعل مع متصفح","التحكم في علامات التبويب ونوافذ متصفح Chrome عبر CLI","تصحيح الأخطاء في التطبيقات المعتمدة على المتصفح باستخدام منفذ Unix"]},"limitations":{"en":["Requires Chrome browser installation","Limited to Chrome browser automation","Dependent on CLI or Unix socket connectivity"],"zh":["需要Chrome浏览器安装","仅限Chrome浏览器自动化","依赖于CLI或Unix套接字连接"],"ja":["Chromeブラウザのインストールが必要","Chromeブラウザの自動化のみ","CLIまたはUnixソケット接続に依存"],"ko":["Chrome 브라우저 설치가必要","Chrome 브라우저 자동화만 가능","CLI 또는 Unix 소켓 연결에 종속"],"es":["Requiere la instalación del navegador Chrome","Limitado a la automatización del navegador Chrome","Dependiente de la conectividad de CLI o socket de Unix"],"fr":["Nécessite l''installation du navigateur Chrome","Limité à l''automatisation du navigateur Chrome","Dépendant de la connectivité CLI ou du socket Unix"],"de":["Erfordert die Installation des Chrome-Browsers","Begrenzt auf die Automation des Chrome-Browsers","Abhängig von der Konnektivität von CLI oder Unix-Socket"],"pt":["Requer instalação do navegador Chrome","Limitado à automação do navegador Chrome","Dependente da conectividade CLI ou soquete Unix"],"ru":["Требует установки браузера Chrome","Ограничен автоматизацией браузера Chrome","Зависит от подключения CLI или сокета Unix"],"ar":["يتطلب تثبيت متصفح Chrome","محدود بتأتمتة متصفح Chrome","يعتمد على الاتصال CLI أو منفذ Unix"]},"version":4},"contentHash":"330269cfd8fb4f018210dae7670dc04beaf2ba7a8ff98d45ee63abc0720f1ed8","qualityScore":60}');
